INSERT INTO "public"."iso_codes" ("id", "code", "name", "description", "parent_code", "level", "is_active", "display_order", "created_at", "updated_at") VALUES ('003f9350-4aef-4265-8600-d761e210b609', '27 06 24', '색상 측정용 보조기구 및 도구', '색상의 다양한 성분을 식별하는 도구', null, '3', 'true', '8', '2025-12-28 01:55:49.321516+00', '2026-02-09 03:28:28.465723+00'), ('00cacd91-e1e3-44a7-b0a2-04894153a451', '28 03 03', '업무용 책상', '주로 업무 현장에서 사용하는 쓰기, 읽기, 그리기 또는 컴퓨터용 책상 예를 들어 사무용 책상, 컴퓨터 책상 등이 있다. 독서대, 책상 및 입식 책상, 18 03 06 참조 제도용 테이블 및 그리기 테이블, 18 03 09 참조', null, '3', 'true', '1', '2025-12-28 01:55:08.314249+00', '2026-02-09 03:28:28.465723+00'), ('01070f42-5741-4cf6-a498-32147752e89b', '24 18 30', '로봇 조작기', '팔, 손 및 손가락 기능을 대체하며 공간에서 물체에 도달하여 잡고 이동하는 조이스틱 등을 사용하여 사용자가 제어하는 전동 보조기구 영양 장치, 15 09 27 참조 업무 현장에서 물건을 고정하고 손을 뻗어 잡기 위한 보조기구, 28 12 참조 업무 현장에서 사용하기 위한 기계 및 도구, 28 15 참조', null, '3', 'true', '8', '2025-12-28 01:55:49.23463+00', '2026-02-09 03:28:28.465723+00'), ('015f7b5b-df7a-44e5-8709-b519cafd2d49', '28 06 07', '전동식 탑승자 작동 산업용 수송 차량', '물품을 운반하기 위한 바퀴가 2개 이상인 장치. 사람이 차량에 앉거나 서서 차량을 조작함. 예를 들어 전기 트랙터 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:30.60508+00', '2026-02-09 03:28:28.465723+00'), ('018f0b0d-e312-4fbb-b4b3-62ef6a73a69a', '06 24 36', '둔부 장치', '정상 사지의 일부 동적 및 감각적 특성을 대체하고 제어된 동작을 통해 정상 둔부의 일부 기능을 대체하는 하지 보철물의 기능적 구성요소', null, '3', 'true', '13', '2025-12-28 01:55:58.177659+00', '2026-02-09 03:27:15.521366+00'), ('0224fd57-0e93-4cf0-8376-f65040e37e24', '12 12 18', '휠체어에 앉은 사람을 차량에 승하차할 수 있는 보조기구', '사람과 휠체어를 들어올려 승하차하거나 휠체어를 탄 사람이 차량에 들어갈 수 있게 하는 장치 예를 들어 휠체어를 탄 사람을 승하차시키기 위한 호이스트, 탑승한 휠체어를 싣거나 내리기 위해 차량에 설치된 경사로, 탑승한 휠체어를 쉽게 싣거나 내리기 위해 차량에 설치된 리프팅 플랫폼 등이 있다. 섀시 높이를 조절할 수 있는 자동차, 밴 및 트럭, 12 10 03 참조 이동식 경사로, 18 30 15 참조', null, '3', 'true', '7', '2025-12-28 01:55:43.227512+00', '2026-02-09 03:36:39.110787+00'), ('026acd6f-945e-4f61-a573-a0edc2d6ef1c', '09 03 30', '잠옷', '잠옷', null, '3', 'true', '9', '2025-12-28 01:55:50.344682+00', '2026-02-09 03:27:15.521366+00'), ('02706834-40eb-4052-be34-329f79ad926b', '09 21 09', '멸균제', '세균과 박테리아를 박멸하는 물질', null, '3', 'true', '3', '2025-12-28 01:55:19.399275+00', '2026-02-09 03:27:15.521366+00'), ('02e52a1a-27c1-41dc-ac81-58bb6e08dc77', '22 29 15', '마킹 기재 및 마킹 도구', '표시 및 식별 장치 예를 들어 표지판, 기호, 라벨 등을 포함한다.', null, '3', 'true', '5', '2025-12-28 01:55:35.64944+00', '2026-02-09 03:28:46.630705+00'), ('03231206-5947-4e6e-a910-c8731f5d6704', '22 18 06', '비디오 녹화 및 재생 장치', '테이프나 기타 전자 매체에 영상 및 동영상을 저장하고 재생하는 장치 예를 들어 카메라, 비디오 플레이어, 디지털 비디오 레코더 및 플레이어 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:15.356949+00', '2026-02-09 03:28:46.630705+00'), ('03335000-7bba-4d95-9548-0775524a9caa', '09 27 13', '소변 수거기용 서스펜더 및 고정 장치', '수거 백을 신체, 이동식 봉, 의자, 휠체어, 침대 등에 고정하는 장치', null, '3', 'true', '4', '2025-12-28 01:55:26.615477+00', '2026-02-09 03:30:20.740792+00'), ('033939e9-3e42-428b-afe2-7b1e639ab366', '09 18 20', '장루 성형 치료용 충전재', '일체형 유출물 시스템 또는 이분형 유출물 시스템의 플레이트르 피부에 부착하여 장루 부위의 요철을 균일하게 하고 누설을 방지하는 보조기구', null, '3', 'true', '6', '2025-12-28 01:55:37.885114+00', '2026-02-09 03:27:15.521366+00'), ('0422cb6f-03bb-4bff-9302-190d36bdc028', '06 06 39', '어깨 관절', '해부학적 어깨 관절의 움직임을 허용하거나 제어하는 상지 보조기의 관절 구성요소', null, '3', 'true', '16', '2025-12-28 01:56:00.861584+00', '2026-02-09 03:27:15.521366+00'), ('044caf7f-1146-454d-bbca-419d20515a61', '12 18 21', '자전거 개조물', '조작이 용이하도록 자전거에 추가하거나 변경하는 보조기구 예를 들어 추가 모터, 트레이너 휠 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:38.624758+00', '2026-02-09 03:36:39.110787+00'), ('04754ebe-9aa3-4205-8040-3bf68ea3cb1c', '12 31 03', '환승 및 전환용 보조기구', '사람이 자신의 힘을 사용하거나 사람의 자세 또는 방향을 변경하는 데 도움이 되는 장치 예를 들어 슬라이딩 보드, 슬라이딩 매트, 터닝 시트, 터닝 쿠션 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:04.976015+00', '2026-02-09 03:36:39.110787+00'), ('04a5e297-9926-47e4-a61f-67e0c765f1ff', '04 03 24', '호흡용 벤치 및 쿠션', '호흡을 돕거나 폐의 분비물을 배출할 수 있도록 사람을 위치시키는 장치', null, '3', 'true', '6', '2025-12-28 01:55:36.695595+00', '2026-02-09 03:26:41.971174+00'), ('0511feb2-4b6e-4657-93dd-6fff5919493f', '22 03 15', '시야 범위 및 시야각 확장 및 조정을 위한 보조기구', '시야각을 확대 또는 변경하는 장치 예를 들어 프리즘 안경, 청와용 안경 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:34.67726+00', '2026-02-09 03:28:46.630705+00'), ('056fdb21-42f6-4093-887a-dba23f36a381', '12 07 05', '보행 보조기구용 팁', '보행 보조기구의 안정성을 향상시키기 위해 지팡이 또는 목발의 팁 또는 보행 프레임 또는 보행 보조기의 말단에 장착하는 보조기구 예를 들어 추가 미끄럼 방지 소재의 팁, 빙판 위를 걷기 위한 팁, 유연한 팁 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:03.989788+00', '2026-02-09 03:36:39.110787+00'), ('05ab7b86-10cc-4fd5-b304-bfbb3cc7949b', '22 06 03', '나팔형 보청기', '소리를 귀에 집중시키고 전달하는 장치', null, '3', 'true', '1', '2025-12-28 01:55:06.647468+00', '2026-02-09 03:28:46.630705+00'), ('05c66e45-85df-43ee-8c86-469744ca053e', '06 03 06', '요천골 보조기', '몸통의 요추 및 천장골 부위의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '2', '2025-12-28 01:55:10.404975+00', '2026-02-09 03:27:15.521366+00'), ('05fd5de8-ef97-416f-a695-0fd5a364b775', '12 12 27', '차량 섀시 및 차량 개조물', '운전자 또는 장애가 있는 승객을 위해 접근성, 사용성 또는 편안함을 높이기 위한 차량의 섀시, 프레임 또는 기타 시스템에 대한 개조물 예를 들어 올림 루프, 확대 창, 서스펜션 시스템 등이 있다.', null, '3', 'true', '10', '2025-12-28 01:55:53.653456+00', '2026-02-09 03:36:39.110787+00'), ('0600d9d3-8c92-45c0-be4a-b07679a8d017', '09 12 30', '화장지 걸이', '접근 가능한 위치에 화장지를 고정하는 장치', null, '3', 'true', '12', '2025-12-28 01:55:57.032394+00', '2026-02-09 03:27:15.521366+00'), ('06e06b57-2caf-41e7-ba02-4ac3e81c14eb', '18 30 15', '이동식 경사로', '두 레벨 사이의 제한된 간격을 연결하는 이동식 경사면', null, '3', 'true', '7', '2025-12-28 01:55:44.496194+00', '2026-02-09 03:36:58.313004+00'), ('06e4f00f-0b3f-43b2-9245-1a284114a655', '09 24 06', '요도를 통해 삽입된 간헐적 카테터', '방광의 일회 배수 및 세척을 위해 요도에 삽입되는 일회용 관형 장치', null, '3', 'true', '2', '2025-12-28 01:55:11.568176+00', '2026-02-09 03:27:48.703289+00'), ('07489ff2-2cbf-4ae2-9b52-77e18d4fd239', '22 13 12', '입술 읽기 및 타이포스코프', '제한된 텍스트 영역을 한 번에 볼 수 있도록 하는 기기', null, '3', 'true', '4', '2025-12-28 01:55:29.340768+00', '2026-02-09 03:28:46.630705+00'), ('0793bfdc-130f-4240-aa4b-5eef8be3de4d', '04 19 24', '주입 펌프', '약물(영양제 포함)을 혈관에 직접 자동 투여하기 위해 신체에 부착하는 장치 예를 들어 인슐린 펌프, 공급 펌프, 비경구(정맥 주사) 급식용 액세서리 등이 있다. 장내 영양 공급을 위한 영양 시스템, 15 09 30 참조', null, '3', 'true', '7', '2025-12-28 01:55:41.569385+00', '2026-02-09 03:26:41.971174+00'), ('07b683b2-93ef-4136-a344-071d7b0f0c16', '04 03 33', '목젖 지지대', '자유로운 호흡이 가능하도록 목젖을 지지하는 장치 예를 들어 호흡의 연속성을 유지하고 코골이를 방지하기 위한 장치 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:45.932888+00', '2026-02-09 03:26:41.971174+00'), ('09008c28-6e24-42a9-8594-a695c83e39a0', '22 13 15', '텍스트 음성 변환 장치 및 소프트웨어', '전자 음성으로 인쇄된 텍스트나 디지털 텍스트를 소리 내어 읽어주는 기기 및 소프트웨어 독서기, 리딩 펜, 스크린 리더 및 전자 음성 등을 포함한다.', null, '3', 'true', '5', '2025-12-28 01:55:34.815425+00', '2026-02-09 03:28:46.630705+00'), ('09869bab-2bf5-4d30-b01c-174a43a9d0e4', '18 33 09', '가스 공급용 안전 밸브', '비상 상황을 방지하기 위해 가스의 흐름을 자동으로 차단하는 장치', null, '3', 'true', '4', '2025-12-28 01:55:28.955474+00', '2026-02-09 03:36:58.313004+00'), ('09de4d29-adce-4008-a100-b3b5ef6e658b', '12 07 21', '보행 보조기구용 시트', '보행 보조기구를 사용하는 사람의 체중을 지탱할 수 있는 지팡이, 보행 프레임, 보행 보조기 및 보행 테이블에 추가할 수 있는 시트 예를 들어 보행 보조기용 접이식 및 비접이식 고정 시트, 보행 보조기 및 보행 테이블용 슬링 시트 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:33.001288+00', '2026-02-09 03:36:39.110787+00'), ('0a409c9d-99cd-48d6-a633-fc05d96883ff', '22 18 15', '텔레비전', '예를 들어 디지털 및 고화질 텔레비전 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:35.057925+00', '2026-02-09 03:28:46.630705+00'), ('0a5a3744-74c1-478a-8e5c-17edfc573989', '12 23 18', '자가 균형 휠체어', '2개의 캐스터 없이 균형을 유지하며 탑승자의 신체 움직임이나 조이스틱을 통해 조종하는 이륜 전동 휠체어', null, '3', 'true', '6', '2025-12-28 01:55:38.779887+00', '2026-02-09 03:36:39.110787+00'), ('0a987c33-79b7-47d2-a529-4ef775637897', '09 54 03', '성행위용 인체 모형', '성행위 중 훈련 및 보조를 위한 모조품 예를 들어 음경, 질 및 전신(공기 주입식 러브 돌) 인체 모형 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:03.786247+00', '2026-02-09 03:30:20.740792+00'), ('0ab94c17-20ea-4351-944f-040d2174870d', '28 21 09', '사무용 기계 및 사무용 장비', '예를 들어 문서 세단기, 복사기 등이 있다. 컴퓨터용 출력 장치, 22 39 참조', null, '3', 'true', '3', '2025-12-28 01:55:24.500526+00', '2026-02-09 03:28:05.359464+00'), ('0c00e1f5-a064-4233-a7b4-00e835f1f624', '12 27 24', '수동 구동 스탠드온 이동 장치', '탑승자가 팔을 사용하여 추진하며 선 자세로 사용하는 장치 스탠딩 프레임 및 스탠딩 지지대, 04 48 39 참조', null, '3', 'true', '9', '2025-12-28 01:55:51.126931+00', '2026-02-09 03:36:39.110787+00'), ('0dbb52a8-ad54-456e-9bb7-08de9b4dfb2c', '09 12 12', '독립형 올림 변기 시트', '시트를 변기에서 쉽게 탈거할 수 있는 바닥에 세워진 올림 변기 시트(분리형) 예를 들어 변기 위 프레임 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:32.308692+00', '2026-02-09 03:27:15.521366+00'), ('0deaa7e6-24b7-424a-b709-5cc0ef1eb0b9', '30 09 37', '육상 경기용 장비', '육상 경기를 보조기구 예를 들어 트랙 훈련, 던지기 훈련, 높이뛰기 훈련 등을 포함한다.', null, '3', 'true', '12', '2025-12-28 01:55:57.813891+00', '2026-02-09 03:28:05.359464+00'), ('0e41e262-f266-4a5f-af4d-7e856871dd7e', '09 03 51', '넥타이와 나비넥타이', '넥타이와 나비넥타이', null, '3', 'true', '15', '2025-12-28 01:56:00.370862+00', '2026-02-09 03:27:15.521366+00'), ('106e72c9-ab3a-4d4d-85de-64ac692c0003', '22 29 06', '개인 비상 경보 시스템', '사용자가 조작하거나 개인 긴급 상황 발생 시 자동으로 활성화되는 장치 예를 들어 간질 환자를 위한 인슐린 경보, 추락 경보, 발작 경보 등을 포함한다.', null, '3', 'true', '2', '2025-12-28 01:55:15.643459+00', '2026-02-09 03:28:46.630705+00'), ('1092679a-5586-43ed-93b9-e0b4b70ff29f', '04 27 24', '임플란트와 관련하여 사용되는 자극기', '이식된 수신기를 자극하는 데 도움이 되는 장치 임플란트와 관련하여 사용되는 보청기, 22 06 21 참조', null, '3', 'true', '4', '2025-12-28 01:55:25.149489+00', '2026-02-09 03:26:58.608329+00'), ('10e42f2b-08cc-4fac-9000-4ce346c52faa', '30 24 06', '낚시용 보조기구', '조개류를 포함하여 모든 종류의 물고기를 잡는 것을 지원하는 장치', null, '3', 'true', '1', '2025-12-28 01:55:09.171306+00', '2026-02-09 03:26:26.759831+00'), ('1188718c-e320-4989-ac0e-c804f2e3091b', '27 06 06', '각도 및 수평 측정용 보조기구 및 도구', '물체의 각도를 측정하는 장치 예를 들어 수위계 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:16.584075+00', '2026-02-09 03:28:28.465723+00'), ('119474de-d440-484a-978e-7316c5297a75', '12 12 24', '차량 내 휠체어 고정용 보조기구', '차량 내에서 휠체어를 고정하기 위한 장치 예를 들어 휠체어 고정 용구 등이 있다.', null, '3', 'true', '9', '2025-12-28 01:55:50.947854+00', '2026-02-09 03:36:39.110787+00'), ('119d1575-d01b-402a-ada1-c73bf17f9f71', '12 24 03', '휠체어용 조향 및 제어 시스템', '휠체어의 이동 및 주행 방향 제어 장치', null, '3', 'true', '1', '2025-12-28 01:55:04.760411+00', '2026-02-09 03:36:39.110787+00'), ('11c33c34-1e32-4edd-88c8-5f51d32cdfa5', '22 33 15', '브라우저 소프트웨어', '예를 들어 SMS, WAP 및 이메일용 소프트웨어 등이 있다. 사무용 소프트웨어 및 산업용 소프트웨어, 28 21 12 참조', null, '3', 'true', '5', '2025-12-28 01:55:35.732171+00', '2026-02-09 03:28:46.630705+00'), ('11c5485f-2ecf-4269-844c-67804ca40149', '15 03 18', '조리 및 튀김용 보조기구', '예를 들어 요리용 접시, 프라이팬, 달걀 삶는 기구, 커피 및 차 메이커, 소스 팬 홀더/손잡이, 여과기, 프라이팬 덮개, 야채 바구니, 달걀 링, 집게, 팬, 주방 용품 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:39.214621+00', '2026-02-09 03:36:58.313004+00'), ('1274da82-8592-41a6-8049-728265fc8bb2', '18 21 03', '문 개폐기', '문 개폐기', null, '3', 'true', '1', '2025-12-28 01:55:06.136901+00', '2026-02-09 03:36:58.313004+00'), ('1299d608-8161-416b-88ba-83f8051c14d5', '06 18 06', '손목 절단 보철물', '절단 후 또는 선천적 사지 결손으로 인한 손목 관절에서 상지의 일부를 대체하는 장치', null, '3', 'true', '2', '2025-12-28 01:55:10.683323+00', '2026-02-09 03:27:15.521366+00'), ('12dd87b4-aa41-421b-be2a-8b7e1b6784c2', '09 06 27', '기도 보호용 보조기구', '유해한 외부 영향으로부터 호흡기를 보호하는 장치 기관 절개 치료용 보조기구, 09 15 참조', null, '3', 'true', '9', '2025-12-28 01:55:50.423754+00', '2026-02-09 03:27:15.521366+00'), ('13036532-ff9b-4295-81b2-a1954c22c8ce', '24 13 15', '배전반', '전화 교환대, 22 24 18 참조', null, '3', 'true', '5', '2025-12-28 01:55:35.955602+00', '2026-02-09 03:28:28.465723+00'), ('13432fff-1985-439a-aea8-0ad00c46b175', '12 36 12', '벽, 바닥 또는 천장에 고정된 고정식 호이스트', '시스템에 의해 특정한 위치에서 사람을 들어올려 이송하는 장비 예를 들어 수영장용 리프트 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:33.780757+00', '2026-02-09 03:36:39.110787+00'), ('1375d072-3c05-4809-b748-e79501379bb9', '22 15 15', '기초 기하학적 기술 훈련용 보조기구', '기하학적 도형의 주요 특징을 학습하고 모양을 인식하고 이름을 붙이고 비교할 수 있는 보조기구', null, '3', 'true', '5', '2025-12-28 01:55:34.91268+00', '2026-02-09 03:28:46.630705+00'), ('150f4f1a-22e2-459e-b04a-717b20cb7248', '09 12 25', '독립형 변기 팔 지지대 및 변기 등받이', '독립형 변기 팔 지지대 및 변기 등받이', null, '3', 'true', '10', '2025-12-28 01:55:53.202898+00', '2026-02-09 03:27:15.521366+00'), ('153f9cdb-eabd-4a1a-9cae-ca7028102098', '30 18 03', '직물 수공예용 공구, 기재 및 장비', '실, 직물 또는 기타 섬유 기반 기재로 만든 공예품을 만드는 데 사용되는 보조기구 예를 들어 바느질, 마크라메, 뜨개질, 크로셰 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:09.109842+00', '2026-02-09 03:28:05.359464+00'), ('1562849a-9a11-4c77-abce-b5b3d5a39822', '12 24 21', '휠체어용 타이어, 바퀴 및 캐스터', '예를 들어 스노 러너, 허브 캡 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:38.863777+00', '2026-02-09 03:36:39.110787+00'), ('15cdcb61-828f-4e43-af14-4f20062f45c8', '12 31 15', '리프팅 벨트 및 하네스', '사람이 수동으로 다른 사람을 이동하도록 지원하는 장치', null, '3', 'true', '5', '2025-12-28 01:55:33.710608+00', '2026-02-09 03:36:39.110787+00'), ('15dac8dc-6bb1-4744-872a-207a11971e89', '18 06 09', '연단 조명 및 칠판 조명', '연단 조명 및 칠판 조명', null, '3', 'true', '3', '2025-12-28 01:55:21.758129+00', '2026-02-09 03:36:58.313004+00'), ('15ded644-101b-43f3-9aa4-5747f01ce686', '04 27 09', '보조기로 사용되지 않는 근육 자극기', '근육 또는 근육의 특정 부위를 자극하여 근육을 수축 또는 이완시키는 기구 골반 저부 훈련용 보조기구, 04 48 33 참조 근육 자극기가 내장된 상지 보조기, 06 06 참조 근육 자극기가 내장된 하지 보조기, 06 12 참조', null, '3', 'true', '1', '2025-12-28 01:55:01.535978+00', '2026-02-09 03:26:58.608329+00'), ('1676bddb-6af8-46b9-bc71-78abd5465cc3', '30 09 03', '팀 구기 스포츠용 보조기구', '득점을 용이하게 하기 위해 팀이 실내 또는 실외 구역에서 공을 움직여야 하는 스포츠에 개인이 참여할 수 있도록 하는 보조기구 예를 들어 미식축구, 야구, 농구, 축구, 럭비, 하키, 골볼(goalball) 등이 있다. 볼링용 보조기구, 30 09 12 참조', null, '3', 'true', '1', '2025-12-28 01:55:09.038618+00', '2026-02-09 03:28:05.359464+00'), ('168a66b2-3b1e-4c0d-b655-e7a81e0fd8a5', '12 27 22', '러닝 바이크', '안장과 핸들이 장착되어 발로 밀어서 움직이는 좌식형 차량', null, '3', 'true', '7', '2025-12-28 01:55:43.656151+00', '2026-02-09 03:36:39.110787+00'), ('169004b8-b632-4c2f-96b8-433bff36495f', '18 12 30', '침대 길이 단축용 보조기구', '침대 길이를 줄이기 위한 장치', null, '3', 'true', '11', '2025-12-28 01:55:56.043843+00', '2026-02-09 03:36:58.313004+00'), ('169540b6-2909-4397-b1fd-004e79204e4f', '09 30 28', '미리 형성된 모양으로 소변을 담는 남성용 패드, 일회용', '소변을 담는 남성용 패드, 미리 형성된 모양, 일회용', null, '3', 'true', '11', '2025-12-28 01:55:55.469935+00', '2026-02-09 03:30:20.740792+00'), ('16baf37d-b47d-488b-83bd-6bcd052909eb', '04 19 04', '비액상 의약품 투여용 보조기구', '알약 및 기타 비액상 의약품의 투여, 복용 및 취급을 위한 보조기구 예를 들어 좌약을 포함한다. 시간, 계획, 기억 및 체계화 표시를 위한 보조기구, 22 28 참조', null, '3', 'true', '1', '2025-12-28 01:55:01.256364+00', '2026-02-09 03:26:41.971174+00'), ('16eae761-2c4e-4a5a-9e88-2c3c4b7c7325', '18 15 06', '높이 조절식 플린스 및 브래킷', '가구를 올릴 수 있는 높이 조절 가능한 표면 또는 브래킷', null, '3', 'true', '2', '2025-12-28 01:55:14.46089+00', '2026-02-09 03:36:58.313004+00'), ('17d366ba-302b-4d57-8995-79ac8ed9788c', '12 03 21', '측면 지지 프레임', '한 팔로 조작하고 몸의 측면에 고정하는 안정화를 위한 보행 프레임. 팁(페룰)이 달린 4개의 다리, 하나 또는 두 개의 손잡이가 있다. 보행 프레임, 12 06 03 참조', null, '3', 'true', '7', '2025-12-28 01:55:43.062061+00', '2026-02-09 03:36:39.110787+00'), ('17eba791-b7de-4c91-98d1-3a90269a9aa2', '27 03 12', '진동 저감 보조기구', '진동을 완화하기 위한 장치 또는 기재 업무 현장의 진동 저감용 보조기구, 28 24 09 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.391485+00', '2026-02-09 03:28:28.465723+00'), ('181d9dab-3d27-44f1-8314-ef5fc2941134', '06 12 17', '대퇴 보조기', '허벅지를 감싸는 보조기', null, '3', 'true', '8', '2025-12-28 01:55:46.586089+00', '2026-02-09 03:27:15.521366+00'), ('184d252b-97a4-4514-a1c9-b02e112ed662', '22 13 42', '그리기 및 페인팅 소프트웨어', '컴퓨터를 사용하여 그리기 및 페인팅 활동을 가능하게 하는 소프트웨어 사무용 소프트웨어 및 산업용 소프트웨어, 28 21 12 참조', null, '3', 'true', '14', '2025-12-28 01:55:59.960728+00', '2026-02-09 03:28:46.630705+00'), ('187c3821-8ab4-4c65-9454-3851ff51e862', '04 48 24', '운동, 근력 및 균형 훈련용 바이오 피드백 장치', '특정한 물리적 또는 생리적 작용에 반응하여 청각, 시각 또는 촉각 신호를 제공하는 장치', null, '3', 'true', '5', '2025-12-28 01:55:31.571593+00', '2026-02-09 03:26:58.608329+00'), ('18a60ead-853e-4669-90b0-2f8a5f6c51c8', '06 24 18', '고관절 이단 보철물', '절단 후 또는 선천적 사지 결손으로 인한 고관절의 하지를 대체하는 장치', null, '3', 'true', '6', '2025-12-28 01:55:37.429506+00', '2026-02-09 03:27:15.521366+00'), ('190e4b18-1c28-4693-8a44-1e76e86684b4', '24 13 24', '전기기기 작동용 소프트웨어', '예를 들어 개인 환경 제어용 소프트웨어, 온스크린 키보드, 음성 인식 소프트웨어 및 마우스 기능용 소프트웨어 등을 포함한다.', null, '3', 'true', '8', '2025-12-28 01:55:49.143913+00', '2026-02-09 03:28:28.465723+00'), ('1934d213-aff7-4ace-9d72-dc72ce836469', '28 09 09', '업무 현장용 리프팅 및 위치 결정 시스템', '화물 및 기타 물체를 사용자가 쉽게 접근할 수 있는 위치에 배치하거나 들어 올리는 고정식, 회전식 슬라이딩 또는 경사식 장비 예를 들어 리프팅 테이블 등이 있다. 스탠드, 24 18 12 참조 위치 지정 보조기구, 24 24 참조', null, '3', 'true', '3', '2025-12-28 01:55:24.35733+00', '2026-02-09 03:28:28.465723+00'), ('195fabf5-4e95-4095-b92b-194d31a5dc39', '12 36 06', '견고한 좌석이 있는 앉은 자세로 사람을 이송하기 위한 이동식 호이스트', '앉은 자세로 사람을 들어 올리고 자유롭게 움직여 이송하는 장비. 신체 지지 장치는 견고한 시트, 스페이드형 시트 또는 그와 동등한 시트로 구성', null, '3', 'true', '3', '2025-12-28 01:55:21.129916+00', '2026-02-09 03:36:39.110787+00'), ('1a0ecf11-1391-4df0-8d06-6152acb61619', '22 18 33', '마이크', '예를 들어 헤드셋 마이크 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:48.908085+00', '2026-02-09 03:28:46.630705+00'), ('1a44b171-ac19-4f97-90a7-cc779e0ae847', '22 33 06', '휴대용 컴퓨터 및 개인용 정보 단말기(PDA)', '배터리로 전원을 공급할 수 있어 어디서나 사용할 수 있는 컴퓨터 예를 들어 스마트폰과 같은 휴대전화와 결합된 컴퓨터 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:15.708475+00', '2026-02-09 03:28:46.630705+00'), ('1a48e76f-2ebe-4f52-ad0f-a588e40ee359', '04 26 09', '주의력 훈련용 보조기구', '집중력 및 기타 주의력 기능 개발용 기기', null, '3', 'true', '3', '2025-12-28 01:55:17.977161+00', '2026-02-09 03:26:58.608329+00'), ('1ab8c581-b582-4db0-8965-fad73ab9e9ba', '09 12 10', '변기 스플래시 가드', '신체 배설물이 변기 밖으로 튀지 않도록 하는 장치', null, '3', 'true', '4', '2025-12-28 01:55:26.24171+00', '2026-02-09 03:27:15.521366+00'), ('1b642113-a3a9-43d1-bd3b-a7b63dae0082', '12 10 06', '저속 자동차', '공공 도로에서 사용할 수 있는 최대 속도가 제한된 자동차. 일부 국가에서는 운전 면허 없이 운전할 수 있음.', null, '3', 'true', '2', '2025-12-28 01:55:12.65589+00', '2026-02-09 03:36:39.110787+00'), ('1bc3b08d-a629-473e-a507-2ad7adc7418b', '12 18 06', '발로 움직이는 삼륜거 및 사륜거', '1인용 페달 추진 삼륜 이상의 자전거 예를 들어 캐리어 사이클 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:20.63241+00', '2026-02-09 03:36:39.110787+00'), ('1c0d5033-c3ef-4cc3-ba68-59ba71b6afde', '15 15 19', '손바느질용 보조기구', '예를 들어 바늘 꿰는 기구, 골무 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:39.51737+00', '2026-02-09 03:36:58.313004+00'), ('1cc32d1c-99b5-4306-9442-3727ca5a622d', '06 30 03', '가발', '사람의 모든 머리카락을 대체하는 장치', null, '3', 'true', '1', '2025-12-28 01:55:02.398196+00', '2026-02-09 03:27:15.521366+00'), ('1d050a92-cd95-47f7-9ecc-95a01684d9ce', '12 25 18', '휠체어용 몸통 지지대 및 골반 지지대', '앉아 있을 때 사람의 어깨, 몸통, 엉덩이 또는 골반 부위를 지지하거나 안정시키기 위해 휠체어에 부착되거나 통합된 장치 신체 안정을 위한 보조기구, 09 07 참조 차량 탑승자 보호 시스템, 12 12 09 참조', null, '3', 'true', '6', '2025-12-28 01:55:38.934678+00', '2026-02-09 03:36:39.110787+00'), ('1dbd09b0-3f47-4949-a146-c168ea599a76', '06 18 33', '팔꿈치 장치', '정상 사지의 동적 및 감각적 특성 중 일부를 대체하고 제어된 동작을 통해 정상 팔꿈치의 일부 기능을 대체하는 상지 보철물의 기능적 구성요소', null, '3', 'true', '12', '2025-12-28 01:55:56.669934+00', '2026-02-09 03:27:15.521366+00'), ('1e086c38-fb99-4b70-9365-257b91585840', '27 03 03', '실내 공기 온도 및 습도 조절을 위한 보조기구', '밀폐된 공간의 내부 기후 특성(온도, 습도, 환기)을 조절하는 장치 예를 들어 가습기 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:08.182649+00', '2026-02-09 03:28:28.465723+00'), ('1ec482ed-30d1-4867-bcee-df91c93fa6ce', '28 15 21', '업무용 로봇', '화물 및 기타 물체를 들어 올리고, 배치하고, 조작하고 플랜트에서 기계 작업을 수행하기 위한 프로그래밍 가능한 고정 또는 이동식 장치 유선 리모컨, 24 13 03 참조 운반 및 수송용 보조기구, 24 36 참조 업무 현장에서 물건을 운반하기 위한 보조기구, 28 06 참조', null, '3', 'true', '7', '2025-12-28 01:55:45.632214+00', '2026-02-09 03:28:28.465723+00'), ('1fdc53e4-5cf2-4e0b-95e1-7be0f888543e', '18 33 03', '바닥 및 계단용 미끄럼 방지 소재', '미끄러질 위험을 최소화하는 표면 소재 예를 들어 미끄럼 방지 매트, 미끄럼 방지 타일 등이 있다. 미끄럼 방지 목욕 매트, 미끄럼 방지 샤워 매트 및 미끄럼 방지 테이프, 09 33 06 참조 업무 현장 및 업무 현장 주변의 안전장치, 28 24 18 참조', null, '3', 'true', '1', '2025-12-28 01:55:06.405001+00', '2026-02-09 03:36:58.313004+00'), ('1fe9e965-e4d6-497e-92d6-1b4dec0a8f71', '15 03 06', '식음료 준비를 위한 절단, 찍기 및 분할 보조기구', '예를 들어 슬라이싱 머신, 칼, 도마, 치즈 슬라이서, 달걀 분할기, 달걀 슬라이서, 양파 홀더 등이 있다. 조리용 기계, 15 03 15 참조', null, '3', 'true', '2', '2025-12-28 01:55:13.689235+00', '2026-02-09 03:36:58.313004+00'), ('21444a2c-c8d0-464b-bc4d-2a0b7493d34a', '09 54 15', '콘돔', '임신이나 성병 사망으로부터 보호하기 위한 성기 덮개', null, '3', 'true', '5', '2025-12-28 01:55:32.80562+00', '2026-02-09 03:30:20.740792+00'), ('21bbf2f4-60db-4f03-8e0a-fb8eeff19774', '12 06 03', '보행 프레임', '걷거나 서 있는 동안 전체 체중을 지탱하며 안정성과 균형을 유지할 수 있는 사람이 들어올려 이동하는 프레임. 팁이 달린 4개의 다리, 완전 지지대 미포함 및 4개의 팁 또는 2개의 팁과 2개의 캐스터 포함 예를 들어 경질 또는 관절 보행 프레임 등이 있다. 측면 지지 프레임, 12 03 21 참조', null, '3', 'true', '1', '2025-12-28 01:55:03.924621+00', '2026-02-09 03:36:39.110787+00'), ('21d708e8-9226-42c7-be84-ad929649c08b', '22 03 18', '이미지 확대 시스템', '카메라로 전송, 촬영된 사물의 영상을 확대하여 모니터를 통해 직접 표시하는 장치 예를 들어 카메라, 제어 장치, 모니터 및 디지털 시스템 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:39.933352+00', '2026-02-09 03:28:46.630705+00'), ('21e77ea4-fffe-4627-beb6-f62951343d1a', '12 07 24', '물건을 고정하거나 운반하기 위해 보행 보조기구에 부착된 액세서리', '예를 들어 바스켓, 파우치, 후크, 트레이, 테이블, 백, 산소 호흡기용 홀더, 우산용 홀더 등이 있다. 소변 수거기용 서스펜더 및 고정 장치, 09 27 13 참조 사용하지 않을 때 보행 보조기구를 제자리에 고정하는 보조기구, 12 07 27 참조', null, '3', 'true', '6', '2025-12-28 01:55:38.461446+00', '2026-02-09 03:36:39.110787+00'), ('224aa432-f556-4c39-9301-6d83811f5296', '06 03 21', '두개골 보조기', '두개골을 감싸는 보조기', null, '3', 'true', '9', '2025-12-28 01:55:49.922965+00', '2026-02-09 03:27:15.521366+00'), ('2298e481-d6d3-46ac-aedf-967c90c2c30c', '06 18 26', '의수용 특수 기기 또는 도구', '정상 사지의 일부 동적 및 감각적 특성을 대체하고 다양한 개별 기능을 수행하는 상지 보철물의 기능적 구성요소. 장치는 수동형, 조절식 또는 능동형일 수 있다. 집게 동작을 사용하는 장치, 06 18 25 참조', null, '3', 'true', '10', '2025-12-28 01:55:52.72058+00', '2026-02-09 03:27:15.521366+00'), ('22e289e8-7838-422e-ba73-2f967e99b2d2', '09 54 09', '성행위용 진동기', '성행위용 진동 장치', null, '3', 'true', '3', '2025-12-28 01:55:20.038377+00', '2026-02-09 03:30:20.740792+00'), ('231c95e8-ee67-45a7-941a-411eb3db45eb', '18 12 07', '수동 조절식 침대 및 분리형 침대 보드/매트리스 지지대', '높이나 각도를 조절할 수 있는 섹션이 하나 이상인 매트리스 지지대를 갖춘 침대. 조정은 사용자 또는 보조인 수동으로 수행함.', null, '3', 'true', '2', '2025-12-28 01:55:14.393028+00', '2026-02-09 03:36:58.313004+00'), ('231f3b80-47a7-45e9-87fd-f2540846a2e1', '06 06 42', '상지 보조기의 인터페이스 구성요소', '인터페이스 구성요소는 사용자와 직접 접촉한다. 이러한 구성요소는 보조기와 사용자 사이에 그 기능으로 인한 힘을 전달하며 보조기를 제자리에 유지할 수 있다. 예를 들어 쉘, 패드, 스트랩 등이 있다.', null, '3', 'true', '17', '2025-12-28 01:56:01.514304+00', '2026-02-09 03:27:15.521366+00'), ('231f8cf9-e25a-44e2-aed5-5db087b086d5', '06 24 37', '하지 보철물용 외부(측면) 관절', '정상 사지의 동적 및 감각적 특성 중 일부를 대체하고 인간 관절의 원치 않는 움직임을 억제하는 하지 보철물의 기능적 구성요소 예를 들어 고관절, 무릎 관절, 발목 관절 등이 있다.', null, '3', 'true', '14', '2025-12-28 01:55:59.417015+00', '2026-02-09 03:27:15.521366+00'), ('23990cc6-6bb8-4f4e-813c-5ce8ba8e4533', '15 03 12', '제빵용 보조기구', '예를 들어 롤링 핀, 베이킹 틴, 베이킹 접시 등이 있다. 조리용 기계, 15 03 15 참조', null, '3', 'true', '4', '2025-12-28 01:55:27.876908+00', '2026-02-09 03:36:58.313004+00'), ('24a0476b-1c1e-4431-bfe4-d3cdf89bf476', '15 12 06', '브러시, 스펀지, 카무이 가죽, 걸레 및 마룻걸레', '홀더 또는 손잡이가 있는 행주, 스펀지 및 브러시, 09 33 30 참조', null, '3', 'true', '2', '2025-12-28 01:55:13.917685+00', '2026-02-09 03:36:58.313004+00'), ('257f2669-ffc1-4aca-8fbb-60db551b285f', '24 27 18', '자석, 자석 스트립 및 클램프', '자기력으로 물체를 잡고 고정하기 위한 장치', null, '3', 'true', '4', '2025-12-28 01:55:30.263565+00', '2026-02-09 03:28:28.465723+00'), ('25c12b22-5fea-433f-a730-fe07581d38fd', '06 18 12', '팔꿈치 절단 보철물', '절단 후 또는 선천적 사지 결손으로 인한 팔꿈치 관절의 상지 일부를 대체하는 장치', null, '3', 'true', '4', '2025-12-28 01:55:25.757736+00', '2026-02-09 03:27:15.521366+00'), ('25fa2650-4c25-4aa4-ae9c-c389e2bbdfd8', '18 21 09', '커튼 개폐기', '커튼 개폐기', null, '3', 'true', '3', '2025-12-28 01:55:22.17431+00', '2026-02-09 03:36:58.313004+00'), ('26186ad6-3c66-4c6d-8258-7f5100bc3c78', '09 18 11', '장루 성형 치료용 이분형 유출 시스템용 플레이트', '구성요소 자체를 제자리에 유지한 채로 백을 부착하거나 탈거할 수 있는 장루 또는 누공 주변의 피부에 부착된 유출물 수거 시스템의 구성요소', null, '3', 'true', '2', '2025-12-28 01:55:11.42425+00', '2026-02-09 03:27:15.521366+00'), ('26b6429b-c643-4a4e-900a-db8edbf18922', '24 13 18', '키보드', '예를 들어 점자 키보드, 스크린 키보드 등을 포함한다.', null, '3', 'true', '6', '2025-12-28 01:55:40.635063+00', '2026-02-09 03:28:28.465723+00'), ('26f9655d-5386-418d-9440-f591f143cb5b', '04 26 18', '문제 해결 훈련용 보조기구', '개념적 문제와 특정 문제를 해결하는 방법에 대한 훈련용 기기 및 소프트웨어', null, '3', 'true', '6', '2025-12-28 01:55:36.933433+00', '2026-02-09 03:26:58.608329+00'), ('27016e08-a1c0-44db-a551-8c15d88c23be', '22 21 09', '대화 장치', '같은 장소에 있는 사람들 사이의 대체 및 보완적 의사소통을 위한 휴대용 및 비휴대용 전자 장치 예를 들어 디지털 전자 디스플레이, 녹음된 음성 및 합성 음성용 출력 장비 등을 포함한다.', null, '3', 'true', '2', '2025-12-28 01:55:15.429361+00', '2026-02-09 03:28:46.630705+00'), ('277c51bf-a371-4bb8-b4ff-500c3317d5aa', '28 15 09', '상품 생산 및 가공용 기계', '생산 또는 가공 중 기재를 개조하거나, 구성 또는 기재를 연결하거나, 공작물 및 물질 혼합물을 분리하거나, 공작물에 접착제를 도포하는 휴대용이 아닌 장비', null, '3', 'true', '3', '2025-12-28 01:55:24.428027+00', '2026-02-09 03:28:28.465723+00'), ('2881d169-5346-479b-a923-7eb6ed786b19', '04 48 36', '개인 이동 훈련용 보조기구', '예를 들어 훈련용 장비(예: 걷기와 휠체어 사용) 등을 포함한다.', null, '3', 'true', '9', '2025-12-28 01:55:49.839396+00', '2026-02-09 03:26:58.608329+00'), ('28b6673b-b415-46b1-a9a7-21f3037257e3', '09 09 12', '착의 및 탈의 후크 또는 스틱', '옷을 입거나 벗을 때 옷을 고정하거나 잡아주는 장치 옷을 입거나 벗을 때 필요한 보조기구, 09 09 03 참조', null, '3', 'true', '4', '2025-12-28 01:55:26.177346+00', '2026-02-09 03:27:15.521366+00'), ('28d57125-9ce2-44c2-bc82-4cd9cf7b76e2', '12 27 15', '크롤러 및 이동 보드', '사람이 눕거나 앉거나 팔이나 다리로 바닥을 밀면서 움직이는 바퀴 달린 장치', null, '3', 'true', '4', '2025-12-28 01:55:27.608011+00', '2026-02-09 03:36:39.110787+00'), ('29221670-7937-4713-8ac7-816386132202', '06 18 41', '추가 굴곡 장치', '팔꿈치의 유효 굴곡 범위를 개선하기 위한 어깨 절단 보철물의 어깨와 팔꿈치 관절 사이의 상지 보철물의 기능적 구성요소', null, '3', 'true', '16', '2025-12-28 01:56:01.036836+00', '2026-02-09 03:27:15.521366+00'), ('298014c7-2ff8-46b0-8d47-5eba2fd0506f', '09 30 33', '대변을 담는 패드, 일회용', '대변을 담도록 설계된 흡수성 요실금 패드', null, '3', 'true', '13', '2025-12-28 01:55:58.571735+00', '2026-02-09 03:30:20.740792+00'), ('2a2b28ce-b61d-46d0-acd2-8ed01b04f0a3', '22 18 36', '확성기', '확성기', null, '3', 'true', '9', '2025-12-28 01:55:51.84787+00', '2026-02-09 03:28:46.630705+00'), ('2a612659-19ae-442b-9053-327e0bd7df9d', '12 03 16', '다중 팁 지팡이', '손잡이, 샤프트 및 3개 이상의 팁이 있는 지지 및 균형을 제공하는 보행 장치', null, '3', 'true', '5', '2025-12-28 01:55:32.868894+00', '2026-02-09 03:36:39.110787+00'), ('2ae11510-1284-4177-85f4-490852f768af', '04 19 33', '의약품 투여용 기타 보조기구', '예를 들어 액상 의약품 측정, 주사바늘 취급 및 의약품 포장용 기기 등을 포함한다.', null, '3', 'true', '9', '2025-12-28 01:55:49.607706+00', '2026-02-09 03:26:41.971174+00'), ('2af66c8d-f045-4740-bd95-817000b0448d', '04 19 12', '다회용 주사기', '피부에 삽입된 바늘을 통해 액체 의약품을 체내에 직접 주입하기 위한 플런저가 있는 장치. 각 주사기는 살균하여 재사용할 수 있다.', null, '3', 'true', '4', '2025-12-28 01:55:24.936501+00', '2026-02-09 03:26:41.971174+00'), ('2b33f729-57c8-44b8-bd42-a0367af58b62', '22 24 18', '전화 교환대', '전화 시스템의 작동을 제어하기 위한 스위치 패널 및 보드', null, '3', 'true', '5', '2025-12-28 01:55:35.583586+00', '2026-02-09 03:28:46.630705+00'), ('2bb327af-c439-4202-b5ac-4f56b5b06cd8', '18 30 03', '승강기', '두 개 이상의 수직 레벨(예: 건물 층, 바닥 및 선박 데크) 사이의 운송 제공하는 수직 축에서 오르내리는 플랫폼 또는 인클로저', null, '3', 'true', '1', '2025-12-28 01:55:06.323892+00', '2026-02-09 03:36:58.313004+00'), ('2c62a866-36ab-423c-a174-e972a1fd35b2', '06 24 41', '하지 보철물용 소켓', '지지, 안정화 및 현수를 달성하기 위해 착용자와 직접 접촉하는 하지 보철물의 인터페이스 구성요소. 기능 구성요소의 활성화/제어에 기여하는 요소를 포함할 수 있다. 예를 들어 발 부분 절단, 발목 절단, 경골(무릎 아래) 절단, 무릎 절단, 경대퇴(무릎 위) 절단, 고절단, 경골반 절단용 조립식 및 맞춤형 소켓 등이 있다.', null, '3', 'true', '16', '2025-12-28 01:56:01.135589+00', '2026-02-09 03:27:15.521366+00'), ('2c8a11da-8a31-4382-8531-3f82251219c1', '04 24 24', '체온계', '체온 측정용 기기', null, '3', 'true', '7', '2025-12-28 01:55:41.657974+00', '2026-02-09 03:26:58.608329+00'), ('2d4e1205-30a3-44fa-85df-85a163e0ae89', '04 24 27', '체중계', '체중 측정용 기기', null, '3', 'true', '8', '2025-12-28 01:55:46.095212+00', '2026-02-09 03:26:58.608329+00'), ('2da6fef1-81e6-4bf5-9ba6-8fb494ccab41', '09 18 51', '장루 치료용 액세서리', '예를 들어 냄새 흡수제, 장루 백용 포켓 지지대, 장루 백 마개, 신체 배설물을 응축시키는 보조기구, 윤활제, 면봉 등이 있다.', null, '3', 'true', '12', '2025-12-28 01:55:57.142101+00', '2026-02-09 03:27:15.521366+00'), ('2e855757-abe7-4e80-a709-640ccc1f7cc3', '09 33 07', '바퀴가 있거나 없는 샤워 의자', '샤워 중 앉을 수 있는 장치 예를 들어 샤워 의자 등이 있다. 이동식 변기 의자, 09 12 03 참조', null, '3', 'true', '4', '2025-12-28 01:55:26.755732+00', '2026-02-09 03:30:20.740792+00'), ('2ea7a54c-35c0-4391-aa8a-2571cc22eed8', '22 09 12', '음성 훈련 및 발성 훈련용 보조기구', '특히 소리의 생성 및 인식과 관련된 음성 및 발음 교육 및 개발용 보조기구 예를 들어 음성/언어, S-, F- 및 Sch-지표, 음향 스펙트럼 분석기 훈련용 보조기구 등을 포함한다.', null, '3', 'true', '4', '2025-12-28 01:55:29.275583+00', '2026-02-09 03:28:46.630705+00'), ('2ec96ce7-d749-4956-9bde-96224819fd9f', '06 12 16', '둔부-무릎 보조기', '고관절 및 무릎 관절을 감싸는 보조기', null, '3', 'true', '7', '2025-12-28 01:55:42.038078+00', '2026-02-09 03:27:15.521366+00'), ('2f3339cc-0971-43b9-91cc-e890077276bc', '22 24 07', '주로 음성 통신용 기기', '예를 들어 전화용 수신기가 있거나 없는 고정식 전화, 휴대 전화, 인터넷 전화, 촉각 전화기, 핸즈프리 모델 등을 포함한다.', null, '3', 'true', '3', '2025-12-28 01:55:23.096448+00', '2026-02-09 03:28:46.630705+00'), ('2fb8ef8b-c3d8-4e9a-8a1c-3b49c3a41901', '15 03 09', '세척 및 필링 보조기구', '예를 들어 감자 브러시, 감자 껍질 벗기는 도구(수동 및 전자동), 감자 홀더, 코어링 나이프 등이 있다. 조리용 기계, 15 03 15 참조', null, '3', 'true', '3', '2025-12-28 01:55:21.216699+00', '2026-02-09 03:36:58.313004+00'), ('2fd4f311-6bb6-446d-ba69-6a9a7916f152', '18 09 03', '의자', '예를 들어 일어서거나 앉는 것을 도와주는 특별한 장치가 있거나 없는 의자 등이 있다. 작업용 의자 및 사무용 의자, 28 03 09 참조', null, '3', 'true', '1', '2025-12-28 01:55:05.762796+00', '2026-02-09 03:36:58.313004+00'), ('30d74dc1-1634-432d-bdaa-9881cea6fff5', '27 06 18', '압력 측정용 보조기구 및 도구', '예를 들어 기압계 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:40.893139+00', '2026-02-09 03:28:28.465723+00'), ('31c61734-ecce-46db-bfdb-e5754e68d710', '28 15 18', '기계 및 공구용 액세서리', '신체를 보호하기 위한 기계 또는 공구의 고정 장치 예를 들어 부스러기 보호 쉴드 등이 있다. 신체 보호를 위한 신체 착용 보조기구, 09 06 참조 업무 현장 및 업무 현장 주변의 안전장치, 28 24 18 참조', null, '3', 'true', '6', '2025-12-28 01:55:41.165349+00', '2026-02-09 03:28:28.465723+00'), ('31e926bf-dcbe-4c9a-ba29-1a45827d4da2', '30 03 09', '게임', '정해진 규칙에 따라 레크리에이션 활동을 할 수 있도록 고안된 보조기구 예를 들어 보드 게임, 카드 게임, 퍼즐, 비디오/컴퓨터 게임 등이 있다. 스포츠용 보조기구, 30 09 참조', null, '3', 'true', '3', '2025-12-28 01:55:24.638979+00', '2026-02-09 03:28:05.359464+00'), ('3256df15-cac6-451e-8fe4-948af0cf8a35', '06 18 21', '견갑골-흉부 절단 보철물', '절단 후 또는 선천적 사지 결손으로 인한 견갑골-흉부 및 흉골-쇄골 관절의 상지를 대체하는 장치', null, '3', 'true', '7', '2025-12-28 01:55:42.121219+00', '2026-02-09 03:27:15.521366+00'), ('32d9020e-ed41-48d1-843b-94747b5de218', '04 48 33', '골반 저부 훈련용 보조기구', '골반기저근의 기능을 물리적으로 강화하기 위한 보조기구 성행위용 보조기구, 09 54 참조', null, '3', 'true', '8', '2025-12-28 01:55:46.287551+00', '2026-02-09 03:26:58.608329+00'), ('32f10caf-7f28-40c2-9ff6-5af0339ccdfe', '12 07 39', '보행 보조기구용 타이어 및 바퀴', '기존 바퀴를 교체하기 위해 바퀴가 두 개인 보행 프레임 또는 보행 보조기에 추가할 수 있는 바퀴 또는 원래 바퀴가 장착되지 않은 보행 프레임의 다리에 부착할 수 있는 바퀴 예를 들어 보행 프레임 또는 보행 보조기의 다리 부분을 포함하는 바퀴 등이 있다.', null, '3', 'true', '11', '2025-12-28 01:55:55.659699+00', '2026-02-09 03:36:39.110787+00'), ('336fce30-750d-4f08-b2f4-7c034631e246', '09 12 39', '벽면 장착 소변기', '남성이 서서 소변을 볼 수 있도록 벽에 부착된 위생 설비 소변기, 09 27 참조', null, '3', 'true', '15', '2025-12-28 01:56:00.439787+00', '2026-02-09 03:27:15.521366+00'), ('33a6b424-0a15-4d28-bb59-44353a220827', '09 03 39', '턱받이 및 앞치마', '의복이나 몸이 더러워지는 것을 방지하기 위해 몸의 앞쪽에 걸쳐 입는 의류', null, '3', 'true', '11', '2025-12-28 01:55:55.233182+00', '2026-02-09 03:27:15.521366+00'), ('33e698e3-6ccb-41e3-af75-0cf8853d6775', '15 12 25', '창문 청소 장비', '예를 들어 창문, 자동차 앞유리 청소 장비 등을 포함한다.', null, '3', 'true', '8', '2025-12-28 01:55:48.276941+00', '2026-02-09 03:36:58.313004+00'), ('3436055e-0b94-49c5-8748-fa7a28eb1edd', '09 30 15', '어린이용 흡수성 보조기구, 세탁 가능', '세탁 가능한 어린이용 흡수성 요실금 보조기구: 삽입 패드, 고정 장치가 있는 패드, 속옷과 유사한 패드 및 뒷면이 없는 패드와 같은 일회용 디자인과 유사한 다양한 디자인을 사용할 수 있다.', null, '3', 'true', '4', '2025-12-28 01:55:26.691435+00', '2026-02-09 03:30:20.740792+00'), ('350f6d98-e383-4fcd-a9ab-ef6fdd5da1e1', '28 21 12', '사무용 소프트웨어 및 산업용 소프트웨어', '특정 작업을 용이하게 하는 소프트웨어 예를 들어 비즈니스 관리 소프트웨어, 회계 소프트웨어, 특정 회사 소프트웨어, 사무용 소프트웨어 등이 있다. 텍스트 및 멀티미디어 처리 소프트웨어, 22 13 39 참조 계산 소프트웨어, 22 15 09 참조 달력 및 시간표, 22 28 06 참조 출력 장치용 소프트웨어, 22 39 12 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.799493+00', '2026-02-09 03:28:05.359464+00'), ('3537fdd9-eea0-41ff-b56a-e8b914ab3f96', '06 06 13', '손목-손-손가락 보조기', '손목 관절 및 손과 하나 이상의 손가락을 감싸는 보조기', null, '3', 'true', '5', '2025-12-28 01:55:31.713582+00', '2026-02-09 03:27:15.521366+00'), ('3569ffc6-d854-4a2f-84d1-63d23355513c', '09 33 18', '비데', '주로 성기와 밑을 씻기 위한 고정식 또는 이동식 세면기 변기, 09 12 06 참조 변기에 부착하는 세정기 및 공기 건조기, 09 12 36 참조', null, '3', 'true', '9', '2025-12-28 01:55:50.752364+00', '2026-02-09 03:30:20.740792+00'), ('36099e98-4039-4e3b-a4e8-02db31f6d01f', '27 03 18', '정수기 및 연수기', '정수 또는 연수 장치나 기재 투석 치료용 보조기구, 04 15 참조', null, '3', 'true', '6', '2025-12-28 01:55:40.777277+00', '2026-02-09 03:28:28.465723+00'), ('36219601-01b5-4406-a209-e88a8d5dbbad', '22 21 36', '모스 통신 훈련용 보조기구', '모스 알파벳 교육 및 사용법 교육용 기기 신호, 경보, 모니터링 및 식별용 보조기구, 22 29 참조', null, '3', 'true', '10', '2025-12-28 01:55:54.242753+00', '2026-02-09 03:28:46.630705+00'), ('36b892a7-a38d-44ec-8793-25751b5df5de', '28 03 21', '칸막이 벽', '칸막이 벽', null, '3', 'true', '7', '2025-12-28 01:55:45.544486+00', '2026-02-09 03:28:28.465723+00'), ('370fdb39-1f0b-4284-aa44-2104750b9e46', '09 06 18', '무릎 보호 또는 다리 보호용 보조기구', '예를 들어 절단된 다리용 스타킹(단부 양말) 등이 있다. 스타킹 및 양말, 09 03 27 참조', null, '3', 'true', '6', '2025-12-28 01:55:37.67731+00', '2026-02-09 03:27:15.521366+00'), ('37294c54-9ed7-48c0-ab70-ff5304f16676', '09 33 39', '부유 보조기구', '목욕이나 수영 중에 물에 뜨도록 도와주는 장치 예를 들어 수영용 부낭, 목욕 목 칼라, 공기 주입식 목욕 모자 등이 있다. 수영 및 수상 스포츠용 보조기구, 30 09 33 참조', null, '3', 'true', '16', '2025-12-28 01:56:01.373473+00', '2026-02-09 03:30:20.740792+00'), ('3766e039-b8ae-4bee-8028-63f10ac1d736', '12 07 18', '부상으로부터 보호하기 위한 보행 보조기구용 액세서리', '지팡이, 목발, 보행 프레임, 보행 보조기, 보행 테이블에 추가하여 보행 보조기구의 특정 부위에 반복적으로 접촉하여 발생하는 타박상이나 피부 손상을 방지할 수 있는 보조기구(예: 패드 및 쿠션) 신체 보호용를 위한 신체 착용 보조기구, 09 06 참조', null, '3', 'true', '4', '2025-12-28 01:55:27.036365+00', '2026-02-09 03:36:39.110787+00'), ('37676b78-08dd-4081-b233-1babede75086', '12 16 06', '삼륜 모페드 및 오토바이', '삼륜 모페드 및 오토바이', null, '3', 'true', '2', '2025-12-28 01:55:12.863329+00', '2026-02-09 03:36:39.110787+00'), ('37dcc71b-3dfc-4ef0-99ce-3c3bd1d923bc', '22 09 03', '음성 발생기', '구강과 비강에서 공명하고 정상적인 방식으로 혀와 입술을 통해 조절할 수 있는 기계적 진동을 생성하여 발성을 생성하는 장치', null, '3', 'true', '1', '2025-12-28 01:55:06.72389+00', '2026-02-09 03:28:46.630705+00'), ('39176c2a-2b0c-4419-ae8e-8213c85b9e8a', '06 12 20', '발-발가락 관절', '해부학적 발 및 발가락 관절의 움직임을 허용하거나 제어하는 하지 보조기의 관절 구성요소', null, '3', 'true', '11', '2025-12-28 01:55:54.883128+00', '2026-02-09 03:27:15.521366+00'), ('39db809e-f4b5-4fdc-aae4-e81fb4448b81', '15 09 13', '커트러리, 젓가락 및 빨대', '식사 시에 음식을 자르거나 용기에서 사람의 입으로 음식을 옮기기 위해 사용하는 장비 그립 어댑터 및 부착물, 24 18 06 참조', null, '3', 'true', '4', '2025-12-28 01:55:28.0522+00', '2026-02-09 03:36:58.313004+00'), ('39f41411-dc12-4cee-bdb6-eafa6bc3986b', '27 03 09', '소음 저감 보조기구', '소음을 줄이거나 흡수하는 장치 또는 기재 예를 들어 흡음재 등이 있다. 업무 현장의 소음 저감용 보조기구, 28 24 15 참조', null, '3', 'true', '3', '2025-12-28 01:55:24.022417+00', '2026-02-09 03:28:28.465723+00'), ('3a15b8fc-d9ec-4739-a098-1af991a51c78', '22 06 18', '촉각 보청기', '소리를 수신, 증폭 및 촉각 신호로 변환하는 장치', null, '3', 'true', '6', '2025-12-28 01:55:40.004173+00', '2026-02-09 03:28:46.630705+00'), ('3a9aca15-129f-41c0-b7e7-c2f625673cd1', '24 13 09', '전기기기용 스위치', '전기 회로 제어용 스위치 휠체어용 조향 및 제어 시스템, 12 24 03 참조', null, '3', 'true', '3', '2025-12-28 01:55:23.646817+00', '2026-02-09 03:28:28.465723+00'), ('3ad59300-0327-46e8-ab38-f3dc7292b6d9', '04 24 33', '호흡 측정기', '들숨과 날숨 공기의 양을 측정하는 기구 예를 들어 폐활량계 등을 포함한다.', null, '3', 'true', '10', '2025-12-28 01:55:52.241263+00', '2026-02-09 03:26:58.608329+00'), ('3afc3286-ecd1-46b8-a941-f15a36af6170', '06 12 18', '둔부-무릎-발목-발 보조기', '고관절, 무릎관절, 발목 관절과 발을 감싸는 보조기', null, '3', 'true', '9', '2025-12-28 01:55:50.07069+00', '2026-02-09 03:27:15.521366+00'), ('3b017f4e-ee15-4985-87d1-cda5ff560215', '22 13 36', '점자용 휴대용 메모 장치', '점자를 사용하여 정보를 저장하는 휴대용 장치', null, '3', 'true', '12', '2025-12-28 01:55:57.746333+00', '2026-02-09 03:28:46.630705+00'), ('3bb08cbf-c24d-4933-9b85-a351070e70a4', '22 24 03', '다기능 통신 시스템', '음성, 문자, 이미지, 영상 통신을 결합한 장치 예를 들어 스마트폰, 전화 회의 시스템, 비디오폰 등을 포함한다. 청각 보조기구, 22 06 참조', null, '3', 'true', '1', '2025-12-28 01:55:07.05916+00', '2026-02-09 03:28:46.630705+00'), ('3bc84c8e-d78b-4dfa-a98e-3fee5acce50d', '06 06 20', '전완 보조기', '팔꿈치 또는 손목 관절을 포함하거나 포함하지 않은 팔뚝을 감싸는 보조기(예: 골절 치료)', null, '3', 'true', '8', '2025-12-28 01:55:46.49434+00', '2026-02-09 03:27:15.521366+00'), ('3bcc1c31-bc01-4077-ac91-1d643b13c01d', '22 15 09', '계산 소프트웨어', '사무용 소프트웨어 및 산업용 소프트웨어, 28 21 12 참조', null, '3', 'true', '3', '2025-12-28 01:55:22.889996+00', '2026-02-09 03:28:46.630705+00'), ('3bfd3390-e42e-4ce7-982e-80187ff27304', '06 18 40', '상완골 회전 장치', '보철물의 소켓으로 인한 어깨의 내회전/외회전 범위 제한을 대체하는 상지 보철물의 기능적 구성요소', null, '3', 'true', '15', '2025-12-28 01:56:00.173341+00', '2026-02-09 03:27:15.521366+00'), ('3c4bc055-d329-49c7-8c3d-3e7e30f3c700', '09 54 12', '성생활 및 재활 보조기구', '예를 들어 질 확장용 위한 보조 용품 등을 포함한다.', null, '3', 'true', '4', '2025-12-28 01:55:26.826463+00', '2026-02-09 03:30:20.740792+00'), ('3caa0431-204c-4fbb-8634-b2ecdd2f542f', '27 03 06', '실내 공기 질 개선을 위한 보조기구', '실내 기후 특성(온도, 습도, 환기)을 조절하는 장치 업무 현장용 공기청정기, 28 24 12 참조', null, '3', 'true', '2', '2025-12-28 01:55:16.518385+00', '2026-02-09 03:28:28.465723+00'), ('3cf13e5e-7c91-478a-9d66-2f757630fc10', '22 13 03', '페이지 터너', '책, 신문, 잡지 등의 페이지를 넘기는 데 사용하는 장치 작동 스틱, 24 18 15 참조', null, '3', 'true', '1', '2025-12-28 01:55:06.786494+00', '2026-02-09 03:28:46.630705+00'), ('3d0144c1-dbcd-4369-b480-1c2f1d36363e', '15 12 12', '건식 카펫 청소기', '카펫을 가로질러 밀면서 먼지를 내부 저장 용기로 쓸어담는 메커니즘이 탑재된 기계식 장치', null, '3', 'true', '5', '2025-12-28 01:55:34.054838+00', '2026-02-09 03:36:58.313004+00'), ('3d616c6b-abd4-4c4d-932a-d5b8732b313b', '06 18 42', '상지 보철물용 소켓', '지지, 안정화 및 지지를 달성하기 위한 착용자와 직접 접촉하는 상지 보철물의 인터페이스 구성요소. 기능 구성요소의 활성화/제어에 기여하는 요소를 포함할 수 있다 예를 들어 손 부분 절단, 손목 절단, 경요골(팔꿈치 아래) 절단, 팔꿈치 절단, 경상박골(팔꿈치 위) 절단, 어깨 절단, 전사반부절단용 소켓 등이 있다.', null, '3', 'true', '17', '2025-12-28 01:56:01.690216+00', '2026-02-09 03:27:15.521366+00'), ('3db52dca-245c-4159-84a2-5429ebb29cde', '30 18 12', '금속공예용 공구, 기재 및 장비', '금속으로 공예품을 만드는 데 사용되는 보조기구', null, '3', 'true', '4', '2025-12-28 01:55:31.045577+00', '2026-02-09 03:28:05.359464+00'), ('3dbccf6a-3d2d-413a-b9e4-1d1a343cabff', '09 33 12', '목욕용 들것, 샤워 테이블 및 기저귀 교환대', '목욕, 샤워 중에 또는 기저귀를 갈 때 사람이 눕는 고정식 또는 이동식 테이블 호이스트용 신체 지지 장치, 12 36 21 참조', null, '3', 'true', '7', '2025-12-28 01:55:42.986828+00', '2026-02-09 03:30:20.740792+00'), ('3dbd312b-489d-4dc7-8ee3-57d1a446777d', '18 15 03', '다리 익스텐더', '다리 길이를 늘리기 위해 가구 다리 아래에 배치하는 장치', null, '3', 'true', '1', '2025-12-28 01:55:06.00344+00', '2026-02-09 03:36:58.313004+00'), ('3dfd0068-c197-4857-a732-becb5b986f45', '04 03 21', '흡인기', '폐의 분비물 및 물질을 빨아들이는 장치', null, '3', 'true', '5', '2025-12-28 01:55:31.122993+00', '2026-02-09 03:26:41.971174+00'), ('3ef9d181-422b-469d-af4b-5a68924b32a6', '09 21 06', '피부 세정제', '피부 세정용 물질', null, '3', 'true', '2', '2025-12-28 01:55:11.488996+00', '2026-02-09 03:27:15.521366+00'), ('3f465e5d-d131-4293-b96e-eda0ea30d07e', '15 06 03', '싱크대', '싱크대', null, '3', 'true', '1', '2025-12-28 01:55:05.220348+00', '2026-02-09 03:36:58.313004+00'), ('3f98ad34-8f81-4858-b893-b0d014ee009c', '28 09 03', '크레인, 태클 및 화물 취급 부착물', '화물 및 기타 물체의 수평 및 수직 이송을 위한 와이어 또는 도르래 및 부착물이 있는 수동 또는 전동식 리프팅 장비 예를 들어 이동 크레인, 윈치 크레인, 오버헤드 크레인, 체인, 케이블, 로프, 후크, 도르래 블록, 그리퍼 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:08.460786+00', '2026-02-09 03:28:28.465723+00'), ('3fcff695-f3ea-401d-aad4-9395f78c043b', '12 12 07', '조향 시스템을 조작하는 차량 액세서리 및 차량 개조물', '조작자가 차량을 조종할 수 있도록 차량에 추가할 수 있는 보조기구 및 개조물 예를 들어 스티어링 휠 노브, 스티어링 휠 서보 시스템, 스티어링 칼럼 확장 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:12.794606+00', '2026-02-09 03:36:39.110787+00'), ('4032e52d-97e6-40bf-8242-a8705791c405', '18 33 18', '내화성 바닥재', '내화성 바닥재', null, '3', 'true', '8', '2025-12-28 01:55:48.657592+00', '2026-02-09 03:36:58.313004+00'), ('40aea073-74fd-4d54-a484-5e9e90e77892', '06 04 06', '복벽탈장 지지대', '탈장을 제자리에 지지하고 유지하는 장치 예를 들어 탈장 스트랩, 거들, 탈장대 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:10.480057+00', '2026-02-09 03:27:15.521366+00'), ('40d305f5-3553-4780-96eb-e6be52d5e584', '06 30 15', '등 충전재', '등의 심한 곡면을 채우는 장치', null, '3', 'true', '5', '2025-12-28 01:55:32.047365+00', '2026-02-09 03:27:15.521366+00'), ('41487f1f-9cbf-4725-84a9-0d5a0b2e38f5', '12 06 15', '전동식 보행 보조기', '전동식 보행 보조기', null, '3', 'true', '6', '2025-12-28 01:55:38.400521+00', '2026-02-09 03:36:39.110787+00'), ('423748d8-68a2-4729-a2dc-3f0e6790c0d1', '18 24 21', '조리대', '조리대', null, '3', 'true', '7', '2025-12-28 01:55:44.408582+00', '2026-02-09 03:36:58.313004+00'), ('42c93940-df2d-435f-a461-e4786c3cb749', '12 23 06', '전자식 조향 기능을 갖춘 전동 휠체어', '탑승자가 전자 컨트롤러로 작동하는 전동 휠체어 예를 들어 자가 균형 휠체어 등이 있다. 보조인 제어 전동 휠체어, 12 23 12 참조 모듈식 좌석 시스템, 18 09 39 참조', null, '3', 'true', '2', '2025-12-28 01:55:13.141832+00', '2026-02-09 03:36:39.110787+00'), ('42d8bf86-597c-44f7-bc43-62f25aae7ddd', '09 18 16', '장루 성형 치료용 이분형 유출 시스템용 백', '장루 또는 누공에서 신체 폐기물을 수집하기 위한 밀폐형 또는 배수형 백으로 구성된 탈거할 수 있는 유출물 수거 시스템의 구성요소 예를 들어 고출력 백 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:19.312192+00', '2026-02-09 03:27:15.521366+00'), ('42f98b8d-a14b-4269-be82-e43c46a0f8f1', '22 03 03', '광 필터(흡수 필터)', '정의된 파장의 빛을 흡수하고 원하지 않는 빛을 걸러내는 장치', null, '3', 'true', '1', '2025-12-28 01:55:06.578099+00', '2026-02-09 03:28:46.630705+00'), ('43012344-71d9-4496-b2a2-e9cbc026c343', '12 22 24', '계단 오르기용 수동 휠체어', '안전하게 계단을 오르내릴 수 있고, 탑승자가 점유하고 있는 동안 보조자가 조작할 수 있는 수동 휠체어 전동식 계단 운반 기기, 12 17 03 참조', null, '3', 'true', '8', '2025-12-28 01:55:47.649695+00', '2026-02-09 03:36:39.110787+00'), ('436437c2-d633-4379-b66a-4627b4384e8f', '18 18 06', '고정 가로대 및 손잡이', '서 있거나 자세를 바꾸는 동안 사람을 지지하도록 벽, 벽과 바닥 또는 벽, 천장과 바닥에 영구적으로 부착된 장치(일반적으로 직선 또는 각진 봉)', null, '3', 'true', '2', '2025-12-28 01:55:14.52962+00', '2026-02-09 03:36:58.313004+00'), ('436a5917-53d1-4b9e-abd6-171a064b7c04', '22 39 05', '촉각 디스플레이', '컴퓨터의 정보를 촉각적으로 표시하는 장치 예를 들어 점자 디스플레이, 촉각 그래픽 디스플레이 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:15.789964+00', '2026-02-09 03:28:46.630705+00'), ('43c1d9a7-9569-4b0d-b57d-273bd32af2d7', '12 36 18', '고정식 독립형 호이스트', '사람을 자유롭게 들어올려 이동시키거나 시스템에 의해 제한된 구역에서 이송하는 장비', null, '3', 'true', '7', '2025-12-28 01:55:43.811941+00', '2026-02-09 03:36:39.110787+00'), ('443d6fc3-454b-4fd0-99a7-fe9285fd8c2f', '30 09 33', '수영 및 수상 스포츠용 보조기구', '수영 및 수구 및 수상 스키를 포함한 기타 수상 스포츠를 즐길 수 있도록 지원하는 보조기구 부유 보조기구, 09 33 39 참조 수동 휠체어, 12 22 참조 수영장용 전동 휠체어, 12 23 참조 보트 타기용 보조기구, 30 09 09 참조', null, '3', 'true', '10', '2025-12-28 01:55:54.436878+00', '2026-02-09 03:28:05.359464+00'), ('45240992-1a26-42d7-beb3-cd1764a9f147', '12 24 12', '휠체어용 조명 및 안전 신호 장치', '휠체어 주변을 밝히거나 휠체어의 위치를 표시하기 위해 휠체어에 부착할 수 있는 장치 예를 들어 휠체어 안전 플래그, 반사기 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:27.472927+00', '2026-02-09 03:36:39.110787+00'), ('455d1329-fec8-4f47-b493-1c654cc79179', '09 12 45', '변기 시트용 패딩', '더 나은 편안함과 압력 분산을 위해 변기 시트 및 이동식 변기 의자 시트용으로 특별히 설계된 패드 조직 무결성을 위한 시트 쿠션 및 밑깔개, 04 33 03 참조', null, '3', 'true', '17', '2025-12-28 01:56:01.846874+00', '2026-02-09 03:27:15.521366+00'), ('45970ac7-14df-4001-ae2d-84ed9a6ef185', '24 09 03', '푸시 버튼', '눌렀을 때 기계적 동작을 트리거하거나 수행하는 장치 전기기기용 스위치, 24 13 09 참조', null, '3', 'true', '1', '2025-12-28 01:55:07.611001+00', '2026-02-09 03:28:28.465723+00'), ('45f14506-b081-406d-93aa-683a07e065f3', '22 15 18', '화폐를 이해하기 위한 보조기구', '가치평가, 지급 수단을 이해하기 위한 보조기구', null, '3', 'true', '6', '2025-12-28 01:55:40.197417+00', '2026-02-09 03:28:46.630705+00'), ('45f9b114-b735-45bd-a6fd-0aeba1b976fd', '12 22 09', '단측 수동 구동 휠체어', '탑승자가 한 손으로만 추진할 수 있도록 설계된 휠체어 예를 들어 한 손 레버 구동 휠체어, 한 손 핸드림 구동 휠체어 등이 있다. 수동 휠체어용 추진 장치, 12 24 09 참조', null, '3', 'true', '3', '2025-12-28 01:55:20.703808+00', '2026-02-09 03:36:39.110787+00'), ('462d4c32-c1ef-4f6b-b377-9829035e6c4c', '18 21 15', '잠금 장치', '예를 들어 전기 잠금 장치 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:34.330541+00', '2026-02-09 03:36:58.313004+00'), ('4681d603-e57b-43f9-9ede-21db20d0dacf', '09 12 03', '이동식 변기 의자', '화장실에서 먼 곳에서 배변에 사용되는 수거통이 있는 바퀴가 달려 있는 또는 없는 변기 의자 예를 들어 위생 의자, 화장실 휠체어, 샤워에도 사용되는 이동식 변기 의자 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:02.841819+00', '2026-02-09 03:27:15.521366+00'), ('46bf8907-5dfa-404b-b1ee-a1a371eb453c', '28 06 05', '전동식 보행자 작동 산업용 수송 장비', '물품을 운반하기 위한 바퀴가 2개 이상인 장치. 옆의 바닥에 서서 사람이 장치를 조작함.', null, '3', 'true', '2', '2025-12-28 01:55:16.735251+00', '2026-02-09 03:28:28.465723+00'), ('46c01b39-e2d0-4dbe-a7cf-7b1a333c12d6', '06 03 39', '하악 전진 장치', '상악에 대한 하악의 위치 변화를 허용하는 데 사용되는, 입에 착용하는 보조기 예를 들어 MAS(mandibular advancement splint, 하악 전진 부목) 등이 있다.', null, '3', 'true', '14', '2025-12-28 01:55:59.067467+00', '2026-02-09 03:27:15.521366+00'), ('46c237d1-bfe7-4985-9a44-14d3fa859177', '22 06 27', '청각 보조기구용 액세서리', '예를 들어 오디오 연결, 안경 개조, 보청기용 리모컨, 소프트웨어, 배터리, 충전식 배터리, 배터리 충전기 등이 있다.', null, '3', 'true', '9', '2025-12-28 01:55:51.671451+00', '2026-02-09 03:28:46.630705+00'), ('4721cb7f-cdb4-4672-8371-6db8481b7b7a', '06 03 07', '흉부 보조기', '몸통의 흉부 부위의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '3', '2025-12-28 01:55:18.317466+00', '2026-02-09 03:27:15.521366+00'), ('4734a7aa-e27a-42a1-b463-31ec26026fe6', '04 24 21', '청진기', '청진 또는 인체 내부의 소리를 듣기 위한 장치', null, '3', 'true', '6', '2025-12-28 01:55:36.864342+00', '2026-02-09 03:26:58.608329+00'), ('481cdb1d-9eb8-4f01-8563-3f9fb8eec371', '22 03 09', '확대경, 확대용 렌즈 및 렌즈 시스템', '물체의 이미지를 확대하는 장치 예를 들어 조명이 있거나 없는 렌즈, 루페, 확대경(안경) 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:22.561576+00', '2026-02-09 03:28:46.630705+00'), ('486e4b9f-15d3-42cc-bbf8-e0131559240d', '18 30 05', '고정식 리프팅 플랫폼', '플랫폼을 사용하여 두 개 이상의 수직 레벨 사이에 사람이 화물을 이동시키는 지붕이 없고 샤프트 내에서 들어 올리지 않으며 구조물이 영구적으로 부착된 리프팅 장치 예를 들어 휠체어 리프팅 테이블 및 플랫폼 리프트 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:14.746141+00', '2026-02-09 03:36:58.313004+00'), ('48cafeba-565e-48d3-814f-242af7b25819', '09 15 12', '기관절개 치료용 액세서리', '예를 들어 램프, 브러시, 입력계, 커넥터, 필터, 벨트 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:26.30544+00', '2026-02-09 03:27:15.521366+00'), ('48deba60-d5dd-45e9-8c45-337836e68810', '06 12 09', '무릎 보조기', '무릎 관절을 감싸는 보조기', null, '3', 'true', '3', '2025-12-28 01:55:18.572058+00', '2026-02-09 03:27:15.521366+00'), ('4904506c-8493-45a8-bf04-d006bf15e048', '09 33 04', '목욕 보드', '욕조 건너편 가장자리에 등받이가 없는 시트 목조 선반, 09 33 24 참조', null, '3', 'true', '1', '2025-12-28 01:55:03.4429+00', '2026-02-09 03:30:20.740792+00'), ('49348984-1fb2-44a7-ba63-1f770e577bad', '04 26 24', '원인과 결과에 대한 이해를 높이고 향상시키기 위한 보조기구', '원인과 결과에 대한 이해를 높이고 향상시키기 위한 보조기구', null, '3', 'true', '8', '2025-12-28 01:55:46.203678+00', '2026-02-09 03:26:58.608329+00'), ('49a5ecc1-d3d0-442d-b3ff-98a2e679155c', '04 03 27', '호흡 근육 훈련기', '사람이 호흡할 때 저항을 가하거나 흉벽을 직접 압박하여 호흡 근육을 훈련시키는 장치 예를 들어 들숨과 날숨에 저항을 가하는 마스크 등이 있다.', null, '3', 'true', '7', '2025-12-28 01:55:41.499569+00', '2026-02-09 03:26:41.971174+00'), ('4adf7927-f03a-4d34-9f60-03f6516a0d0b', '12 22 12', '핸드림 작동 전동 휠체어', '인력과 전기 동력이 결합된 탑승자 조작 휠체어, 전기 동력의 활성화는 핸드림에 토크, 변위 또는 힘을 가하여 이루어짐 수동 휠체어용 추진 장치, 12 24 09 참조', null, '3', 'true', '4', '2025-12-28 01:55:27.295993+00', '2026-02-09 03:36:39.110787+00'), ('4bd2c404-4f1f-4cdd-aa50-f387b9cc6423', '12 11 06', '저상 열차', '경사로를 사용하거나 사용하지 않고 열차의 승하차가 용이하도록 바닥을 낮춘 열차 차량 예를 들어 지하철 차량, 트램 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:12.723763+00', '2026-02-09 03:36:39.110787+00'), ('4c0a5673-a361-4f9c-8e54-dd1186eebbd4', '04 03 18', '산소 공급기', '코와 입을 통해 흡입되는 농축 산소 가스를 제공하는 장치 예를 들어 주변 공기의 산소를 농축하는 장치 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:24.852101+00', '2026-02-09 03:26:41.971174+00'), ('4c833c19-f33d-474e-9a93-77d2cce4a8a3', '27 06 30', '유체 밀도 측정용 보조기구 및 도구', '유체 밀도 측정용 보조기구 및 도구', null, '3', 'true', '10', '2025-12-28 01:55:54.327722+00', '2026-02-09 03:28:28.465723+00'), ('4cc44abd-cce4-49b3-8ae5-624a20977813', '09 27 21', '대변 수거 백', '직장에서 대변을 수거하기 위한 신체 착용형 유연한 용기', null, '3', 'true', '6', '2025-12-28 01:55:38.125239+00', '2026-02-09 03:30:20.740792+00'), ('4cf8dab4-5b22-4b5b-bc5b-bf9afa2b2615', '22 33 12', '운영 소프트웨어', '사무용 소프트웨어 및 산업용 소프트웨어, 28 21 12 참조', null, '3', 'true', '4', '2025-12-28 01:55:29.914219+00', '2026-02-09 03:28:46.630705+00'), ('4d0d6200-1c12-48b7-8f8f-029d886a2deb', '06 30 27', '코 보철물', '코의 외형을 재현하는 장치', null, '3', 'true', '9', '2025-12-28 01:55:50.274773+00', '2026-02-09 03:27:15.521366+00'), ('4d4b17fc-9bc6-4d24-9c2c-d3f71a86c8d4', '09 24 15', '여성용 신체 착용 소변기', '신체 미착용 소변기 및 소변 병, 09 27 09 참조', null, '3', 'true', '5', '2025-12-28 01:55:32.519611+00', '2026-02-09 03:27:48.703289+00'), ('4d7529e9-8877-4e5c-ba52-0d9a3e0473ff', '12 31 09', '자체 기립용 비장착 레일', '앉거나 누운 자세에서(예: 침대 또는 의자에서) 일어나는 사람을 지지하는 장치 침대에 고정된 자체 기립용 레일, 18 12 28 참조', null, '3', 'true', '3', '2025-12-28 01:55:21.055172+00', '2026-02-09 03:36:39.110787+00'), ('4d9dcfaa-816a-411b-8031-8c0d1b92ebe5', '12 08 06', '상징 지팡이', '사용자의 시각 장애를 다른 사람에게 경고하기 위해 주로 사용하는 짧은 상징 지팡이', null, '3', 'true', '2', '2025-12-28 01:55:12.588271+00', '2026-02-09 03:36:39.110787+00'), ('4da4c2e7-51a7-4ab0-a640-a295b0e6065e', '12 22 18', '미는 휠체어', '보조인 양 손으로 휠체어의 핸들을 밀어서 추진하고 조종하는 수동 휠체어 운반 의자, 12 27 04 참조 모듈식 좌석 시스템, 18 09 39 참조', null, '3', 'true', '6', '2025-12-28 01:55:38.695132+00', '2026-02-09 03:36:39.110787+00'), ('4dd0728e-300b-49b3-bc5f-65594997d59f', '12 24 18', '휠체어용 주행 브레이크 또는 주차 브레이크', '휠체어를 감속 또는 정지시키거나 고정된 위치에 고정하는 장치', null, '3', 'true', '5', '2025-12-28 01:55:33.472592+00', '2026-02-09 03:36:39.110787+00'), ('4dd9a68c-e92c-4a7b-8d14-fc27c6533b5d', '12 22 15', '발로 움직이는 휠체어', '탑승자가 바닥에 발을 디뎌 추진하고 조종하도록 설계된 휠체어 보행 의자, 12 06 09 참조', null, '3', 'true', '5', '2025-12-28 01:55:33.308218+00', '2026-02-09 03:36:39.110787+00'), ('4e4dcb5b-62bc-44b3-9dfd-4061f10486f6', '24 13 21', '컴퓨터 포인팅 장치', '화면 포인터를 배치하고 컴퓨터 디스플레이에서 항목을 선택하는 보조기구 예를 들어 컴퓨터 마우스, 터치 패드, 트랙볼, 조이스틱 등을 포함한다.', null, '3', 'true', '7', '2025-12-28 01:55:45.282085+00', '2026-02-09 03:28:28.465723+00'), ('4e52bdbe-7232-4879-9c9a-67658844f5bc', '04 48 42', '경사 테이블', '누운 자세에서 곧은 자세로 점진적으로 이동하면서 신체가 해당 위치의 기능에 적응할 수 있도록 사람의 위치를 잡고 지지하는 플랫폼', null, '3', 'true', '11', '2025-12-28 01:55:54.596734+00', '2026-02-09 03:26:58.608329+00'), ('4e6a1e83-49d6-4719-b894-7f55c15149dc', '12 18 24', '자전거용 트레일러', '화물을 운반하기 위해 자전거에 부착하는 트레일러', null, '3', 'true', '7', '2025-12-28 01:55:43.30667+00', '2026-02-09 03:36:39.110787+00'), ('4f2028e7-d18b-4272-ae77-606b32de1839', '27 06 21', '기후 조건 측정용 보조기구 및 도구', '온도, 습도 및 환기를 측정하고 식별하는 장치', null, '3', 'true', '7', '2025-12-28 01:55:45.437198+00', '2026-02-09 03:28:28.465723+00'), ('4f763bff-54d9-4375-b73d-346e122d28f6', '22 13 24', '그리기 및 필기용 수동 기기', '예를 들어 볼펜, 연필, 붓, 그리기용 컴퍼스, 자, 삼각자 및 위의 홀더 등을 포함한다.', null, '3', 'true', '8', '2025-12-28 01:55:48.818497+00', '2026-02-09 03:28:46.630705+00'), ('504e96c5-8a21-4ace-a6c8-21b682894df1', '06 06 03', '손가락 보조기', '손가락의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '1', '2025-12-28 01:55:02.108009+00', '2026-02-09 03:27:15.521366+00'), ('50fd57b2-0634-4740-a31e-e5f8e6169681', '09 18 22', '장루 확장용 보조기구', '장이나 요로에서 신체 노폐물이 배출되는 구멍을 열어두거나 넓히는 데 사용되는 보조기구 예를 들어 확장기, 헤가, ace 스토퍼 등이 있다.', null, '3', 'true', '7', '2025-12-28 01:55:42.658384+00', '2026-02-09 03:27:15.521366+00'), ('513f01a8-ebc1-4ec0-acda-f4ceab8a7373', '09 15 06', '기관절개 보호기', '유해한 외부 영향으로부터 사람의 기관의 개구부를 보호하기 위한 장치 기도 보호용 보조기구, 09 06 27 참조', null, '3', 'true', '3', '2025-12-28 01:55:19.249+00', '2026-02-09 03:27:15.521366+00'), ('519e36f6-2f27-41f7-89ed-74e042220229', '06 30 24', '귀 보철물', '귀의 외형을 재현하는 장치', null, '3', 'true', '8', '2025-12-28 01:55:46.827769+00', '2026-02-09 03:27:15.521366+00'), ('51a45ebb-1676-4f80-b401-a3ba864d0576', '12 17 06', '스탠드온 전동차', '사용자가 그 위에 서서 주행하는 차량. 두 개 이상의 바퀴, 핸들 및 설 수 있는 받침대가 있으며 쉴 수 있는 작은 좌석이 있을 수 있음. 모페드 및 오토바이, 12 16 참조', null, '3', 'true', '2', '2025-12-28 01:55:12.934194+00', '2026-02-09 03:36:39.110787+00'), ('5262beef-427a-4cf2-920a-f2b2a95b316a', '12 08 09', '가이드 지팡이 및 상징 지팡이용 액세서리', '예를 들어 팁, 손목 스트랩, 핸들, 반사경 등을 포함한다.', null, '3', 'true', '3', '2025-12-28 01:55:20.298218+00', '2026-02-09 03:36:39.110787+00'), ('52725765-c85d-403d-bb13-f1bc2cd3dd51', '06 18 09', '경요골 보철물', '절단 후 또는 선천적 사지 결손으로 인한 손목과 팔꿈치 관절 사이의 상지 일부를 대체하는 장치', null, '3', 'true', '3', '2025-12-28 01:55:18.653204+00', '2026-02-09 03:27:15.521366+00'), ('536f8cd4-d4bf-48fd-86b2-12298a6b3cda', '22 13 09', '서명 가이드, 스탬프 및 필기 프레임', '원하는 위치에 서명 또는 자필 문자를 쓰거나 스탬프를 이용하여 인쇄된 서명을 제작할 수 있도록 보조하는 기기', null, '3', 'true', '3', '2025-12-28 01:55:22.803006+00', '2026-02-09 03:28:46.630705+00'), ('53704656-dbfd-4163-81ac-6ff5324d839a', '28 03 09', '작업용 의자 및 사무용 의자', '업무 현장용 조절식 또는 고정식 좌석 예를 들어 조립 의자 등이 있다. 좌식 가구, 18 09 참조 콕시트 의자, 18 09 09 참조 특수 좌식 가구, 18 09 21 참조 좌식 가구용 액세서리, 18 10 참조', null, '3', 'true', '3', '2025-12-28 01:55:24.178928+00', '2026-02-09 03:28:28.465723+00'), ('53c02968-0984-463f-bf40-914ebe283b46', '06 24 47', '하지 보철물용 마감(미용) 구성요소', '정상 사지의 외관과 느낌을 모의하는 미용 구성요소 예를 들어 쉘, 충전재, 스킨, 스타킹, 발 커버 등이 있다.', null, '3', 'true', '20', '2025-12-28 01:56:02.739115+00', '2026-02-09 03:27:15.521366+00'), ('5458feb0-e44f-45f0-9694-cdad8e71aacf', '06 30 18', '유방 보철물', '유방 전체 또는 일부의 외형을 재현하는 장치', null, '3', 'true', '6', '2025-12-28 01:55:37.533478+00', '2026-02-09 03:27:15.521366+00'), ('5515f17d-af7a-448e-9161-1728417697ad', '06 03 33', '척추 및 두개골 보조기의 구조적 구성요소', '보조기의 구조적 구성요소는 관절 및 인터페이스 구성요소를 연결하고 보조기의 정렬을 유지한다. 예를 들어 업라이트, 쉘 등이 있다.', null, '3', 'true', '12', '2025-12-28 01:55:56.42+00', '2026-02-09 03:27:15.521366+00'), ('552a3d81-e281-479c-8af3-474bc1d191ec', '04 24 18', '물리적 검사 및 평가 기재', '앉기, 서기, 구르기, 걷기와 같은 운동 활동뿐만 아니라 관절 안정성, 관절 운동성, 근력 및 신체 지구력과 같은 기능을 검사하고 평가하기 위한 장비', null, '3', 'true', '5', '2025-12-28 01:55:31.265106+00', '2026-02-09 03:26:58.608329+00'), ('555c0f26-d52f-41a4-96ee-f4ae3754e1ee', '12 12 08', '차량 조작에 필요한 보완 기능에 대한 액세서리 및 개조물', '예를 들어 조절식 미러, 도어 잠금장치, 알유리 와이퍼, 표시기, 방향 지시등, 조명 사용과 관련된 보조기구 등이 있다. 신호 장치, 22 29 03 참조', null, '3', 'true', '3', '2025-12-28 01:55:20.451796+00', '2026-02-09 03:36:39.110787+00'), ('55830876-df3e-4ee3-b7eb-a96248f259c0', '09 33 15', '세면대', '신체 부위를 씻을 때 사용하는 고정식 또는 이동식 세면기 높이 조절식 플린스 및 브래킷, 18 15 06 참조', null, '3', 'true', '8', '2025-12-28 01:55:47.298813+00', '2026-02-09 03:30:20.740792+00'), ('563eb1f8-11aa-4093-a310-4597c8a9c252', '15 12 27', '쓰레기 보관 또는 쓰레기 처리를 위한 보조기구', '쓰레기의 보관 또는 처리를 위한 용기 또는 장치', null, '3', 'true', '9', '2025-12-28 01:55:51.337416+00', '2026-02-09 03:36:58.313004+00'), ('569c17c2-3a84-416b-9ee4-98a331bfa8f7', '06 12 15', '둔부 보조기', '고관절을 감싸는 보조기', null, '3', 'true', '6', '2025-12-28 01:55:37.294232+00', '2026-02-09 03:27:15.521366+00'), ('56b191d6-ffc0-4536-ae06-c269622caa91', '09 15 03', '기관절개 삽입관', '기관을 받은 사람이 숨을 쉴 수 있도록 사람의 기도에 있는 개구부에 삽입하는 튜브', null, '3', 'true', '1', '2025-12-28 01:55:02.917807+00', '2026-02-09 03:27:15.521366+00'), ('56c13b6c-8af9-418d-a6d8-3e5080428073', '24 36 09', '수하물 및 쇼핑 트롤리', '바퀴, 손잡이 및 하나 이상의 지지 측면이 있는 물품 운반 장치', null, '3', 'true', '3', '2025-12-28 01:55:23.952567+00', '2026-02-09 03:28:28.465723+00'), ('56ea4bbc-26d2-48d5-9c88-07c4f16f7fce', '06 24 03', '부분 발 보철물', '절단 후 또는 선천적 사지 결손으로 인한 발목 관절의 하지 원위부를 대체하는 장치 예를 들어 발가락 보철물 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:02.32756+00', '2026-02-09 03:27:15.521366+00'), ('56ea730f-6267-4851-bb46-09628839a569', '18 06 06', '독서등 및 작업등', '특정 활동이 용이하도록 특정 영역을 비추는 조명', null, '3', 'true', '2', '2025-12-28 01:55:14.191409+00', '2026-02-09 03:36:58.313004+00'), ('57459773-7463-4658-8943-e81e522938e0', '06 18 30', '손목 장치', '정상 사지의 동적 및 감각적 특성 중 일부를 대체하고 제어된 동작을 통해 정상 손목의 일부 기능을 대체하는 상지 보철물의 기능적 구성요소', null, '3', 'true', '11', '2025-12-28 01:55:54.956471+00', '2026-02-09 03:27:15.521366+00'), ('574f6a8c-ab32-4a80-b4ec-a0588aa00f32', '15 15 24', '다림질 기계 및 다리미', '다림질 기계 및 다리미', null, '3', 'true', '8', '2025-12-28 01:55:48.354744+00', '2026-02-09 03:36:58.313004+00'), ('575643ab-5770-4cff-bf02-f0b929e201c4', '30 03 03', '완구', '고정된 규칙 없이 놀도록 설계된 일반적으로 어린이용 물건', null, '3', 'true', '1', '2025-12-28 01:55:08.966028+00', '2026-02-09 03:28:05.359464+00'), ('5758a815-7fc7-4a07-b164-c6a1a7620a94', '12 27 07', '유모차 및 사륜차', '보조인이 조종하고 제어하도록 설계된 한 명 이상의 사람을 눕거나 앉은 자세로 운반하기 위한 바퀴 달린 장치 예를 들어 성인용 유모차 및 사륜차 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:13.449199+00', '2026-02-09 03:36:39.110787+00'), ('57fc6721-9f0a-439a-8255-3e38a23b917d', '18 24 18', '계단', '사다리 및 발판사다리, 18 30 21 참조', null, '3', 'true', '6', '2025-12-28 01:55:39.710945+00', '2026-02-09 03:36:58.313004+00'), ('58b87b3f-6e1e-4838-83ba-21cb69ce6ce7', '12 31 18', '운반용 의자, 하네스 및 바스켓', '한 명 이상의 보조인이 한 장소에서 다른 장소로 사람을 이동시키는 장치', null, '3', 'true', '6', '2025-12-28 01:55:39.071108+00', '2026-02-09 03:36:39.110787+00'), ('5925d75d-2ccf-406c-a813-c67b7577c3a4', '12 22 06', '양수 레버 구동 휠체어', '양손 조작 레버를 사용하여 탑승자가 추진 및 조향하도록 설계된 휠체어 수동 휠체어용 추진 장치, 12 24 09 참조', null, '3', 'true', '2', '2025-12-28 01:55:13.075029+00', '2026-02-09 03:36:39.110787+00'), ('592edb32-b5a4-4322-b6bf-b39672487133', '06 18 15', '경상박골 보철물', '절단 후 또는 선천적 사지 결손으로 인한 어깨와 팔꿈치 관절 사이의 상지 일부를 대체하는 장치', null, '3', 'true', '5', '2025-12-28 01:55:31.878823+00', '2026-02-09 03:27:15.521366+00'), ('595046e4-7186-4cc7-b286-6940d6663d71', '04 30 06', '한냉 치료용 보조기구', '치료 목적으로 신체 또는 신체 부위를 냉각시키는 장치', null, '3', 'true', '2', '2025-12-28 01:55:10.165578+00', '2026-02-09 03:26:58.608329+00'), ('596264a4-7a93-42cd-83fc-4f4fbdcaf9b1', '09 18 24', '장 세척용 보조기구', '예를 들어 물을 도입하는 직장을 통해 장을 세척하는 보조기구 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:47.140076+00', '2026-02-09 03:27:15.521366+00'), ('59952a92-bdb9-4e48-9531-4e5b2119de59', '18 12 04', '침대 및 분리형 침대 보드/매트리스 지지대, 비조절식', '고정 난간 또는 고정 지지대와 같은 특수 기능이 있는 침대 예를 들어 높은 침대 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:05.899152+00', '2026-02-09 03:36:58.313004+00'), ('59e55c71-9a04-42af-bd33-5e2837a3590e', '09 15 04', '후두절제술 튜브', '기관절개를 열어두기 위해 후두절제술을 받은 사람의 기도에 있는 개구부에 삽입하는 튜브', null, '3', 'true', '2', '2025-12-28 01:55:11.326963+00', '2026-02-09 03:27:15.521366+00'), ('5a02ca5c-362b-44a3-9758-5812efe4e243', '30 09 21', '항공용 보조기구', '항공기를 조종할 수 있게 하는 보조기구', null, '3', 'true', '7', '2025-12-28 01:55:45.839724+00', '2026-02-09 03:28:05.359464+00'), ('5a686696-d4b5-4305-a8c6-9ae6dfa3db8e', '09 24 18', '자가 카테터 삽입용 보조기구', '예를 들어 거울, 음순 확장기, 무릎 벌림 장치, 삽입 보조기, 음경 지지대 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:38.058964+00', '2026-02-09 03:27:48.703289+00'), ('5a8ac849-42b3-4bd1-9ea8-a88986ca3eb4', '28 15 15', '업무 현장 청소 기계 및 장비', '실내 또는 실외 구역 또는 작업 자재의 습식 및 건식 세정을 위한 수동 또는 탑승자 조작 기계 및 장비 가사 청소용 보조기구, 15 12 참조', null, '3', 'true', '5', '2025-12-28 01:55:36.408812+00', '2026-02-09 03:28:28.465723+00'), ('5a8db5fd-cff2-4363-8de9-f88e9832537a', '06 18 25', '집게 동작을 사용하는 분할 후크 및 기타 말단 장치', '집게 동작을 사용하기 위해 후크와 같이 정상 사지의 일부 동적 및 감각적 특성을 대체하는 상지 보철물의 기능적 구성요소 의수용 특수 기기 또는 도구, 06 18 26 참조', null, '3', 'true', '9', '2025-12-28 01:55:50.134016+00', '2026-02-09 03:27:15.521366+00'), ('5b145328-0601-488b-8466-e2a396843711', '09 27 24', '소변과 대변을 수집하는 자동 화장실 시스템', '자동 소변 흡수 장치를 포함한다.', null, '3', 'true', '7', '2025-12-28 01:55:42.804944+00', '2026-02-09 03:30:20.740792+00'), ('5b30f723-8d20-4a37-b1d3-b582b08c297d', '22 03 06', '안경 및 콘택트렌즈', '시야의 초점을 맞출 수 있도록 지원하는 장치 예를 들어 안경테 및 전자 안경 등을 포함한다.', null, '3', 'true', '2', '2025-12-28 01:55:14.967207+00', '2026-02-09 03:28:46.630705+00'), ('5b558c29-b8ad-427b-8fd5-cc1a8afcb486', '04 27 12', '진동기', '치료 목적의 진동 마사지에 사용되는, 빠르게 진동하도록 만든 장치 예를 들어 이완 마사지 장치, 폐의 점액을 풀기 위한 진동기(타진기) 등이 있다. 성행위용 진동기, 09 54 09 참조', null, '3', 'true', '2', '2025-12-28 01:55:10.002623+00', '2026-02-09 03:26:58.608329+00'), ('5ba934d1-b9c7-439e-ba89-1b2585f16426', '06 03 18', '경추-흉추-요추-천골 보조기', '환추-후두 관절을 포함하여 경추, 흉추, 요추, 천장골 부위 전체를 감싸는 보조기', null, '3', 'true', '8', '2025-12-28 01:55:46.412877+00', '2026-02-09 03:27:15.521366+00'), ('5c55923a-6bb5-4ef4-8039-a5d725c20352', '15 18 09', '원예 시 신체를 보호하고 지지하는 보조기구', '식물을 가꾸거나 재배하는 사람을 부상으로부터 보호하거나 추가 지원을 제공하도록 고안된 보조기구 예를 들어 닐링 벤치 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:21.622398+00', '2026-02-09 03:36:58.313004+00'), ('5c5f61d2-f05e-4ab6-affe-c243253fad89', '06 06 19', '팔꿈치-손목-손 보조기', '팔꿈치 및 손목 관절과 손의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '7', '2025-12-28 01:55:41.953519+00', '2026-02-09 03:27:15.521366+00'), ('5c708a97-4d87-43f8-9b74-59336600d154', '22 45 12', '촉각 방향 안내 기재', '터치를 통해 방향 정보를 제공하기 위한 기제 예를 들어 촉각으로 표시된 표면 등을 포함한다. 바닥 및 계단용 촉각 기재, 18 33 15 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.069156+00', '2026-02-09 03:28:46.630705+00'), ('5ca60a5e-d0d4-4f84-a6c6-5971bd00f57a', '12 06 07', '보행 트롤리', '사람이 걷거나 서 있는 동안 안정성과 균형을 향상시킬 수 있도록 밀거나 및/또는 들어 올려 움직일 수 있는 프레임으로, 손잡이가 있고 팔쪽 지지대가 없으며 4개 이상의 바퀴가 있는 프레임', null, '3', 'true', '3', '2025-12-28 01:55:20.16907+00', '2026-02-09 03:36:39.110787+00'), ('5d525f00-8e68-4bde-a7aa-f40f923cb0b9', '06 06 45', '상지 보조기의 구조적 구성요소', '보조기의 구조적 구성요소는 관절 및 인터페이스 구성요소를 연결하고 보조기의 정렬을 유지한다. 예를 들어 업라이트, 쉘 등이 있다.', null, '3', 'true', '18', '2025-12-28 01:56:02.217473+00', '2026-02-09 03:27:15.521366+00'), ('5d855d89-7cc7-423c-b60f-a4010ab0e7f3', '06 24 33', '무릎 장치', '정상 사지의 일부 동적 및 감각적 특성을 대체하고 제어된 동작을 통해 정상 무릎의 일부 기능을 대체하는 하지 보철물의 기능적 구성요소', null, '3', 'true', '12', '2025-12-28 01:55:56.755567+00', '2026-02-09 03:27:15.521366+00'), ('5da69158-0d9d-45fe-abe5-078f3de55487', '22 18 12', '양방향 라디오', '주로 일대일 원격 무선 통신을 수신 및 전송하는 장치 예를 들어 CB(Citizens Band), FRS(Family Radio Services), GMRS(General Mobile Radio Service), 해상 무선 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:29.467121+00', '2026-02-09 03:28:46.630705+00'), ('5e4d958f-0ead-4b19-9c71-2a53c352c33d', '06 24 06', '발목 절단 보철물', '절단 후 또는 선천적 사지 결손으로 인한 발목 관절의 하지 일부를 대체하는 장치', null, '3', 'true', '2', '2025-12-28 01:55:10.773585+00', '2026-02-09 03:27:15.521366+00'), ('5e9a4fc0-f5e6-468f-bb8b-3a6901c3d92d', '09 03 33', '목욕용 의류', '예를 들어 수치료용 의복, 보호용 목욕용 의류 등이 있다. 소변 및 대변 흡수용 보조기구, 09 30 참조', null, '3', 'true', '10', '2025-12-28 01:55:53.040304+00', '2026-02-09 03:27:15.521366+00'), ('5f18299b-37d0-4fa6-bfa9-77d68446c476', '12 10 09', '지붕이 높은 자동차, 밴 및 픽업 트럭', '차량 내부에 휠체어를 탄 사람을 수용할 수 있도록 원래 높은 지붕이 탑재된 자동차, 밴 및 픽업 트럭', null, '3', 'true', '3', '2025-12-28 01:55:20.374356+00', '2026-02-09 03:36:39.110787+00'), ('5fc7f108-4156-4884-afcd-b6ff59808e96', '24 06 06', '튜브 짜는 장치', '튜브 내용물의 추출을 돕는 장치 예를 들어 치약 분배 보조기 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:15.932175+00', '2026-02-09 03:28:28.465723+00'), ('5fc95b04-3e48-4354-b20a-a41262aebc11', '06 06 33', '손목 관절', '해부학적 손목 관절의 움직임을 허용하거나 제어하는 상지 보조기의 관절 구성요소', null, '3', 'true', '14', '2025-12-28 01:55:59.156669+00', '2026-02-09 03:27:15.521366+00'), ('6031774d-0b50-4ff4-9fc1-939285b0b212', '18 12 18', '매트리스 및 매트리스 커버', '편안함을 위한 매트리스 및 커버 조직 무결성을 관리하기 위한 보조기구, 04 33 참조 의자나 침구류를 보호하기 위해 신체에 착용하지 않는 언더패드, 일회용, 09 30 42 참조 의자나 침구류를 보호하기 위해 신체에 착용하지 않는 언더패드 세탁 가능, 09 30 45 참조', null, '3', 'true', '6', '2025-12-28 01:55:39.647495+00', '2026-02-09 03:36:58.313004+00'), ('606cad5d-c54f-4c23-b5f9-7e09e0544145', '09 31 09', '요실금 경보', '자기도 모르게 배뇨 또는 배변이 발생할 때 신호를 생성하는 장치 보조기로 사용하지 않는 근육 자극기, 04 27 09 참조', null, '3', 'true', '3', '2025-12-28 01:55:19.691925+00', '2026-02-09 03:30:20.740792+00'), ('6071a603-7493-4846-9f11-7f8c147a0c59', '28 24 15', '업무 현장의 소음 저감용 보조기구', '업무 현장에서 소음을 줄이거나 흡수하는 장치 또는 기재 예를 들어 흡음재 등이 있다. 소음 저감 보조기구, 27 03 09 참조', null, '3', 'true', '5', '2025-12-28 01:55:36.480161+00', '2026-02-09 03:28:05.359464+00'), ('608707b4-26ea-43a1-9d1e-7a9df16698c1', '15 18 03', '실외 원예용 도구', '밖에 있는 잔디나 정원의 재배 또는 관리를 할 수 있는 보조기구 예를 들어 잔디 깎기, 손잡이가 긴 가지치기 가위, 잡초 제거 기구 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:05.549382+00', '2026-02-09 03:36:58.313004+00'), ('60dc0530-edf4-4fd4-8157-a3299a5da20a', '09 06 06', '눈 보호 또는 안면 보호용 보조기구', '예를 들어 수분 챔버, 시계 유리 드레싱 등이 있다. 광선 치료용 보안경, 04 09 09 참조', null, '3', 'true', '2', '2025-12-28 01:55:10.975438+00', '2026-02-09 03:27:15.521366+00'), ('60e1172b-e6c4-4d6d-9d0c-71e08d2fa3ff', '28 24 18', '업무 현장 및 업무 현장 주변의 안전장치', '위험을 최소화하기 위해 실내 및 건물에 적용하는 장치 예를 들어 경로 표시, 미끄럼 방지 바닥재, 내화성 바닥재 등이 있다. 미끄럼 방지 목욕 매트, 미끄럼 방지 샤워 매트 및 미끄럼 방지 테이프, 09 33 06 참조 바닥재, 18 24 15 참조 바닥 및 계단용 미끄럼 방지 소재, 18 33 03 참조', null, '3', 'true', '6', '2025-12-28 01:55:41.236501+00', '2026-02-09 03:28:05.359464+00'), ('61e2f262-7784-4128-b736-d252dba2efb3', '27 06 12', '질량 측정용 보조기구 및 도구(사람 제외)', '예를 들어 우편 저울 등이 있다. 체중계, 04 24 27 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.461516+00', '2026-02-09 03:28:28.465723+00'), ('61fce9a1-c8ff-46a5-9734-b9c342c80c91', '06 04 09', '복부 보조기의 인터페이스 구성요소', '인터페이스 구성요소는 사용자와 직접 접촉한다. 이러한 구성요소는 보조기와 사용자 사이에 그 기능으로 인한 힘을 전달하며 보조기를 제자리에 유지할 수 있다. 예를 들어 쉘, 패드, 스트랩 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:18.382315+00', '2026-02-09 03:27:15.521366+00'), ('620fd182-30ec-4846-a6fb-7187d5d78d6c', '22 13 51', '점자 훈련용 보조기구', '수동 점자 쓰기 장비, 22 13 27 참조 점자용 휴대용 메모 장치, 22 13 36 참조', null, '3', 'true', '17', '2025-12-28 01:56:02.111783+00', '2026-02-09 03:28:46.630705+00'), ('621a50d7-1067-4b25-a50c-d40f3cd82709', '22 09 06', '개인용 음성 증폭기', '사람의 목소리 크기를 높이는 장치 통신 증폭기, 22 06 06 참조', null, '3', 'true', '2', '2025-12-28 01:55:15.111319+00', '2026-02-09 03:28:46.630705+00'), ('625c6518-9c5d-4582-8a2d-bcf27039d5f2', '18 09 09', '콕시트 의자', '앞쪽 가장자리에 하나 또는 두 개의 경사부가 있는 좌석이 있는 의자 예를 들어 일어서거나 앉는 것을 도와주는 특별한 장치가 있는 관절 고정 의자 및 고관절 성형 의자 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:28.456648+00', '2026-02-09 03:36:58.313004+00'), ('63a20c92-743a-433b-89d2-82400652bb63', '28 06 06', '수동식 리프팅 트럭', '화물을 들어올려 이동하기 위한 수동 등식 리프팅 트럭. 옆의 바닥에 서서 사람이 차량을 조작함. 예를 들어 팰릿(리프팅) 트럭, 하이 리프트 팰릿 트럭 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:24.284037+00', '2026-02-09 03:28:28.465723+00'), ('63bd588a-d603-402e-8287-7a3b4c28c460', '28 24 09', '업무 현장의 진동 저감용 보조기구', '업무 현장의 진동을 완화하기 위한 장치 또는 기재', null, '3', 'true', '3', '2025-12-28 01:55:24.57058+00', '2026-02-09 03:28:05.359464+00'), ('64326686-b59c-41aa-9cc4-52fcbc288bbc', '22 29 09', '환경 비상 경보 시스템', '예를 들어 화재 경보기, 연기 감지기, 내부 송신기가 있는 경보 시스템 등을 포함한다.', null, '3', 'true', '3', '2025-12-28 01:55:23.270239+00', '2026-02-09 03:28:46.630705+00'), ('6445d8dd-12d2-42ac-94bd-f021699979ed', '12 27 10', '썰매', '바퀴가 있거나 없이 러너에 장착된 얼음과 눈 위로 사람을 운반하는 장치 예를 들어 킥 슬레드 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:20.988555+00', '2026-02-09 03:36:39.110787+00'), ('64c98393-d68d-490b-88ae-6512075a34a6', '30 18 06', '도예용 공구, 기재 및 장비', '도자기 및 기타 도자기 공예품 제작에 사용되는 보조기구', null, '3', 'true', '2', '2025-12-28 01:55:17.53073+00', '2026-02-09 03:28:05.359464+00'), ('64d53aa6-77be-4f61-a184-d2e4c0bdc5c7', '06 30 36', '의치', '치아의 외형과 기능을 재현하는 장치', null, '3', 'true', '12', '2025-12-28 01:55:56.849079+00', '2026-02-09 03:27:15.521366+00'), ('64d80266-c73f-4298-9c94-f461a9f6e1ed', '28 27 03', '직업 평가 및 직업 지도를 위한 보조기구', '직업, 비즈니스 또는 전문직에 대한 능력과 관심을 검사하고 평가하기 위한 보조기구', null, '3', 'true', '1', '2025-12-28 01:55:08.898655+00', '2026-02-09 03:28:05.359464+00'), ('64db72a8-3083-4aea-b162-8eb0779c5071', '15 15 43', '의류 건조 보조기구', '예를 들어 텀블 건조기, 건조 캐비닛, 회전 건조기, 에어러, 건조 프레임, 빨랫줄 등이 있다.', null, '3', 'true', '14', '2025-12-28 01:55:59.875246+00', '2026-02-09 03:36:58.313004+00'), ('65130e14-06c8-40aa-a88c-267d1b08a289', '09 39 03', '샴푸용 보조기구', '모발 세척용 장치', null, '3', 'true', '1', '2025-12-28 01:55:03.581106+00', '2026-02-09 03:30:20.740792+00'), ('652112ce-d954-4f26-931c-237d5b535b1e', '12 24 24', '휠체어용 배터리 및 배터리 충전기', '휠체어에 전력을 공급하는 장치', null, '3', 'true', '7', '2025-12-28 01:55:43.454141+00', '2026-02-09 03:36:39.110787+00'), ('66252204-669e-4ddd-8f2d-7c7be668ca53', '12 27 23', '무동력 스쿠터', '한 발로 밀어서 핸들을 움직이는 독립형 차량', null, '3', 'true', '8', '2025-12-28 01:55:47.818902+00', '2026-02-09 03:36:39.110787+00'), ('6637a126-b871-4860-8d0e-8d85cb76d712', '09 18 48', '수술 후 장부 백 및 액세서리', '장루를 생성하여 유지할 때 수술 후 용도로 사용되는 백 및 액세서리 예를 들어 무균 보조기구 등이 있다.', null, '3', 'true', '11', '2025-12-28 01:55:55.394007+00', '2026-02-09 03:27:15.521366+00'), ('66cda35f-9715-499f-a87d-09df8fcbfd82', '22 21 27', '단서 언어 훈련용 보조기구', '수어(signing)로 보충되는 발성 언어 훈련 및 학습 기기', null, '3', 'true', '7', '2025-12-28 01:55:45.07358+00', '2026-02-09 03:28:46.630705+00'), ('66e844e3-e75b-4107-ad1b-750a4ce3be18', '24 27 12', '클립 및 스프링 클립', '고정된 지점에 연결된 두 개의 "턱" 사이에 또는 스프링으로 물건을 고정하기 위한 장치 빨래집게, 15 15 39 참조', null, '3', 'true', '3', '2025-12-28 01:55:23.874407+00', '2026-02-09 03:28:28.465723+00'), ('674d8044-bde6-4b22-9624-338b4bf44ed7', '09 06 21', '발뒤꿈치 보호, 발가락 보호 또는 발 보호용 보조기구', '신발 및 부츠, 09 03 42 참조', null, '3', 'true', '7', '2025-12-28 01:55:42.495523+00', '2026-02-09 03:27:15.521366+00'), ('67ab1f4a-bbdb-4cd4-ae8d-354034eec087', '09 06 09', '귀 보호 또는 청력 보호용 보조기구', '소음 저감 보조기구, 27 03 09 참조', null, '3', 'true', '3', '2025-12-28 01:55:19.022764+00', '2026-02-09 03:27:15.521366+00'), ('67df9229-0aff-4c82-8f1c-8966f9d138ee', '09 39 09', '헤어 드라이어', '모발 건조 및 스타일링 장치 팔 기능, 손 기능, 손가락 기능 또는 이러한 기능의 조합을 보조하거나 대체하는 보조기구, 24 18 참조', null, '3