6-02-09 03:36:58.313004+00'), ('aefb814b-fc7b-46c3-a3b3-6b308b3dfedb', '09 27 05', '개방형 소변 수거 백', '내용물의 배출을 위한 개구부가 있는 소변 수거용 유연한 용기', null, '3', 'true', '2', '2025-12-28 01:55:11.702139+00', '2026-02-09 03:30:20.740792+00'), ('af375564-da7f-42ed-93dd-b98fa15bf17e', '22 13 45', '읽기 훈련용 보조기구', '읽기 능력 훈련 및 개발용 기기(예: 전략, 접근 방식 및 성과)', null, '3', 'true', '15', '2025-12-28 01:56:00.780351+00', '2026-02-09 03:28:46.630705+00'), ('b11ea438-aaa4-4687-8962-555cb2df52c3', '06 30 12', '콧수염 및 턱수염', '콧수염 또는 턱수염을 대체하는 장치', null, '3', 'true', '4', '2025-12-28 01:55:25.905159+00', '2026-02-09 03:27:15.521366+00'), ('b15694f6-1985-420d-9b8c-f2cb27cf4d5b', '12 03 18', '시트가 달린 지팡이', '전완 지지대가 없는 손잡이, 샤프트(들), 하나 이상의 팁(들)(페룰) 및 일반적으로 손잡이 또는 샤프트에 부착된 접이식 시트가 있는 보행 시 지지 장치', null, '3', 'true', '6', '2025-12-28 01:55:38.323087+00', '2026-02-09 03:36:39.110787+00'), ('b1b56019-aa11-43b7-b1fa-525ee14900b9', '09 07 03', '신체 안정화를 위한 안전벨트, 벨트 및 하네스', '예를 들어 탑승자 보호 시스템이 포함된다.', null, '3', 'true', '1', '2025-12-28 01:55:02.690319+00', '2026-02-09 03:27:15.521366+00'), ('b225634d-a230-4e65-bf72-a1b9e6dba949', '30 09 18', '펜싱용 보조기구', '펜싱을 즐길 수 있도록 지원하는 보조기구', null, '3', 'true', '6', '2025-12-28 01:55:41.330241+00', '2026-02-09 03:28:05.359464+00'), ('b2317283-1368-40c3-9a45-e63f9ec178bb', '04 26 15', '분류 훈련용 보조기구', '관련 항목 분류 훈련용 기기', null, '3', 'true', '5', '2025-12-28 01:55:31.335334+00', '2026-02-09 03:26:58.608329+00'), ('b23fb88c-452e-4210-b7ed-866d736d489e', '15 06 15', '행주 탈수기', '천에서 여분의 액체를 짜내는 장치', null, '3', 'true', '4', '2025-12-28 01:55:27.951428+00', '2026-02-09 03:36:58.313004+00'), ('b2c86156-b39d-4874-b5b1-e5664e8252f6', '15 15 39', '빨래집게', '빨랫줄에 옷을 부착하기 위한 클립 또는 포크형 장치', null, '3', 'true', '13', '2025-12-28 01:55:58.805947+00', '2026-02-09 03:36:58.313004+00'), ('b31182f4-3b08-437d-8f34-5d2bbfb1aceb', '06 18 57', '상지 보철물의 마감(미용) 구성요소', '정상 사지의 외관과 느낌을 모의하는 미용 구성요소 예를 들어 쉘, 충전재, 피부, 스타킹, 장갑 등이 있다.', null, '3', 'true', '22', '2025-12-28 01:56:02.99676+00', '2026-02-09 03:27:15.521366+00'), ('b3446d25-ec3c-4c68-95b1-f0446f8b66ea', '12 23 15', '계단 오르기용 전동 휠체어', '탑승자가 탄 채로 조작하여 계단을 안전하게 오르내릴 수 있는 전동 휠체어 전동식 계단 운반 기기, 12 17 03 참조', null, '3', 'true', '5', '2025-12-28 01:55:33.378374+00', '2026-02-09 03:36:39.110787+00'), ('b34a15be-9450-49ea-b807-25ff59700cad', '28 24 03', '업무 현장용 개인보호장치', '건강 및 안전 위험으로부터 보호하기 위해 개인이 착용하거나 소지하도록 고안된 장치 예를 들어 머리 보호, 눈 보호, 청력 보호, 손 보호, 발 보호, 기도 보호 및 전신 보호용 보조기구, 안전화, 작업 보호복, 작업 벨트 등이 있다. 신체 보호용를 위한 신체 착용 보조기구, 09 06 참조 발 보조기, 06 12 03 참조 의류 및 신발, 09 03 참조 신체 보호용를 위한 신체 착용 보조기구, 09 06 참조 피부 관리, 피부 보호 및 피부 세정용 보조기구, 09 21 참조', null, '3', 'true', '1', '2025-12-28 01:55:08.833275+00', '2026-02-09 03:28:05.359464+00'), ('b3c62cc9-fa47-4b5d-9110-65585c7dac55', '04 33 09', '조직 무결성을 위한 특수 장비', '신체 부위의 과도한 압력을 평가하거나 경고하기 위한 장치 예를 들어 피부 무결성 알람 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:25.283121+00', '2026-02-09 03:26:58.608329+00'), ('b41a04e2-e353-4f94-8f39-5d9e9a600341', '30 09 27', '라켓 및 패들 스포츠용 보조기구', '테니스, 탁구, 라켓볼, 스쿼시, 배드민턴 및 기타 라켓 및 패들 스포츠를 즐길 수 있도록 지원하는 보조기구', null, '3', 'true', '8', '2025-12-28 01:55:49.526347+00', '2026-02-09 03:28:05.359464+00'), ('b466a1f5-de9a-4004-9792-c7f176ed8a7c', '12 11 03', '섀시 높이를 조절할 수 있는 버스', '차량 바닥을 지면으로 차량의 섀시를 낮추어 승객이 승하차할 수 있도록 하는 버스', null, '3', 'true', '1', '2025-12-28 01:55:04.217551+00', '2026-02-09 03:36:39.110787+00'), ('b47077e9-8570-45a6-bf4a-96b80c348062', '18 36 09', '침대 옆 캐비닛', '예를 들어 침대 옆 수납 장치, 침대 테이블, 침대 옆 캐비닛 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:22.488026+00', '2026-02-09 03:36:58.313004+00'), ('b4757039-9336-4303-a29c-afdf120ab687', '04 26 88', '인지 기능 향상용 기타 기기', '다른 사람들과 어울려 지내도록 지원하는 기타 보조기구', null, '3', 'true', '11', '2025-12-28 01:55:54.520319+00', '2026-02-09 03:26:58.608329+00'), ('b5e0edfe-a2bf-40b9-a5c6-c831b5d4d4cd', '12 36 09', '누운 자세로 사람을 이송하기 위한 이동식 호이스트', '누운 자세로 사람을 들어 올리고 자유롭게 움직여 이송하는 장비. 신체 지지 장치는 수직으로 조절 가능하지만 수평으로 회전하지 않음.', null, '3', 'true', '4', '2025-12-28 01:55:27.792032+00', '2026-02-09 03:36:39.110787+00'), ('b6044786-27e6-4826-ad1c-0a5d96f2aae2', '09 03 15', '블라우스 및 셔츠', '블라우스 및 셔츠', null, '3', 'true', '4', '2025-12-28 01:55:26.029808+00', '2026-02-09 03:27:15.521366+00'), ('b641e2e2-fec9-40d0-8ac1-99da21bca7bb', '15 15 21', '가위', '식음료를 준비하기 위한 절단, 찍기 및 분할 보조기구, 15 03 06 참조 수공예 도구, 기재 및 장비, 30 18 참조', null, '3', 'true', '7', '2025-12-28 01:55:44.172168+00', '2026-02-09 03:36:58.313004+00'), ('b6748a90-0939-4df0-9104-3ff58810cf58', '27 06 27', '소음 수준 측정용 보조기구 및 도구', '소음 수준 측정 및 표시 장치', null, '3', 'true', '9', '2025-12-28 01:55:52.075268+00', '2026-02-09 03:28:28.465723+00'), ('b697e7cd-b23a-4047-a311-fb7852f52e7a', '09 33 30', '홀더 또는 손잡이가 있는 행주, 스펀지 및 브러시', '몸을 씻거나 때를 미는 데 사용되는 장치', null, '3', 'true', '13', '2025-12-28 01:55:58.649919+00', '2026-02-09 03:30:20.740792+00'), ('b6a58265-52b2-4682-aa3c-0fad482ec67a', '18 30 08', '이동식 리프팅 플랫폼', '이동식으로 설계된 자체 지지 구조로 구조물이나 지면에 부착되지 않고, 플랫폼을 사용하여 두 개 이상의 수직 레벨 사이에 사람이나 화물을 이동하며 지붕이 없고 샤프트 내에서 들어 올리지 않는 리프팅 장치 예를 들어 이동식 휠체어 리프팅 테이블 및 플랫폼 리프트 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:28.892898+00', '2026-02-09 03:36:58.313004+00'), ('b6b4a480-311a-4ebb-a80b-e1ba7c4129d7', '09 09 03', '옷을 입거나 벗을 때 필요한 보조기구', '양말, 스타킹, 스타킹을 착용하거나 벗을 수 있게 해주는 기기 착의 및 탈착 후크 또는 스틱, 09 09 12 참조', null, '3', 'true', '1', '2025-12-28 01:55:02.758403+00', '2026-02-09 03:27:15.521366+00'), ('b71db918-2631-4155-9b9e-e68353bf9b88', '28 09 12', '업무 현장용 리프팅 플랫폼', '다양한 수준에서 작업 활동이 가능하도록 사람을 들어 올리고 위치를 잡기 위한 플랫폼 수직 접근성을 위한 보조기구, 18 30 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.66755+00', '2026-02-09 03:28:28.465723+00'), ('b789edab-4d9d-49ef-83ba-3fed233725c6', '09 09 18', '단추 고리', '옷과 신발의 단추를 채우고 풀 수 있도록 도와주는 장치', null, '3', 'true', '6', '2025-12-28 01:55:37.748728+00', '2026-02-09 03:27:15.521366+00'), ('b7ae67db-ec3a-443d-8e51-b31495869c74', '22 09 09', '음성 흐름 장치', '말의 유창함과 리듬을 향상시키는 장치', null, '3', 'true', '3', '2025-12-28 01:55:22.710602+00', '2026-02-09 03:28:46.630705+00'), ('b80103bd-5a36-4380-9965-3c89c1be3267', '09 42 03', '비전동식 칫솔', '그립 어댑터 및 부착물, 24 18 06 참조', null, '3', 'true', '1', '2025-12-28 01:55:03.644014+00', '2026-02-09 03:30:20.740792+00'), ('b8cf6507-de01-4f75-9fbb-cb62a4f1bea5', '12 23 03', '수동 직접 조향 기능을 갖춘 전동 휠체어', '동력 지원 없이 피벗 구동 휠(들)의 방향을 기계적으로 변경하여 방향을 제어(조향)하는 전기 구동 휠체어 예를 들어 스쿠터 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:04.691001+00', '2026-02-09 03:36:39.110787+00'), ('b8d042e3-1385-438a-93d1-d42470906654', '12 24 34', '햇빛이나 강우로부터 휠체어 및 탑승자를 보호하는 장치', '예를 들어 휠체어용 우산과 캐노피 등이 있다.', null, '3', 'true', '9', '2025-12-28 01:55:51.045007+00', '2026-02-09 03:36:39.110787+00'), ('b8f10629-6bd6-45db-aaa8-1b6583ca79b7', '15 06 18', '식기세척기', '커트러리 및 그릇 세척용 전동 장치', null, '3', 'true', '5', '2025-12-28 01:55:33.919956+00', '2026-02-09 03:36:58.313004+00'), ('b96548c7-451e-4060-8065-861dbcacbc86', '06 18 18', '어깨 절단 보철물', '절단 후 또는 선천적 사지 결손으로 인한 어깨 관절의 상지 일부를 대체하는 장치', null, '3', 'true', '6', '2025-12-28 01:55:37.364654+00', '2026-02-09 03:27:15.521366+00'), ('b985791d-c770-4cb4-9725-1091135f6dca', '22 39 04', '시각 디스플레이', '예를 들어 컴퓨터에서 텍스트와 이미지를 확대하거나 강화하여 정보를 시각으로 표시하는 기기 예를 들어 큰 활자 디스플레이, 화면 돋보기, 눈부심 감소 화면 등이 있다. 화면 확대 소프트웨어, 22 03 21 참조', null, '3', 'true', '1', '2025-12-28 01:55:07.370097+00', '2026-02-09 03:28:46.630705+00'), ('b99c6414-2e60-498a-a2e3-f3077c7a2380', '22 06 09', '스펙터클 보청기', '소리를 증폭시키는 전자 장치가 내장된 안경테', null, '3', 'true', '3', '2025-12-28 01:55:22.641208+00', '2026-02-09 03:28:46.630705+00'), ('bafe4df0-b08e-469c-9c16-8badb3385604', '12 24 36', '휠체어를 자전거에 연결하는 장치', '휠체어를 자전거에 연결하는 연결 시스템 발로 움직이는 삼륜거 및 사륜거, 12 18 06 참조 반수동 자전거, 12 24 11 참조', null, '3', 'true', '10', '2025-12-28 01:55:53.725392+00', '2026-02-09 03:36:39.110787+00'), ('bb10da84-d096-40a7-8deb-3aeb71c775ed', '06 24 09', '경골 보철물', '절단 후 또는 선천적 사지 결손으로 인한 무릎 관절과 발목 관절 사이의 하지 일부를 대체하는 장치', null, '3', 'true', '3', '2025-12-28 01:55:18.719519+00', '2026-02-09 03:27:15.521366+00'), ('bb260356-ca5b-49ff-b3c7-a6eb3384b1b2', '24 18 15', '작동 스틱', '다른 장치를 제어하기 위한 장치 및 입력 장치 페이지 터너, 22 13 03 참조 컴퓨터 포인팅 장치, 24 13 21 참조', null, '3', 'true', '5', '2025-12-28 01:55:36.0377+00', '2026-02-09 03:28:28.465723+00'), ('bb326bb5-2458-417e-9c21-3ccffa332a30', '18 18 11', '힌지 레일 및 팔 지지대', '자세를 변경할 때 사람을 지지하는 장치. 벽이나 바닥에 고정할 수 있고 접근해야 하거나 필요하지 않을 때 접을 수 있는 장치(일반적으로 U자형) 변기에 장착된 변기 팔 지지대 및 변기 등받이, 09 12 24 참조 독립형 변기 팔 지지대 및 변기 등받이, 09 12 25 참조 휠체어용 팔 지지대, 12 25 09 참조', null, '3', 'true', '4', '2025-12-28 01:55:28.660093+00', '2026-02-09 03:36:58.313004+00'), ('bb6705ef-d791-405f-8d41-67a6f4d69f3e', '09 45 09', '피부 관리용 거울', '피부 관리용 거울', null, '3', 'true', '3', '2025-12-28 01:55:19.973108+00', '2026-02-09 03:30:20.740792+00'), ('bb7c21ae-7245-4084-9610-7a37481a91d2', '04 28 03', '빛으로 감각을 자극하는 보조기구', '예를 들어 광선 치료용 보조기구 등을 포함한다. 광선 치료용 보조기구, 04 09 참조 온열 치료용 보조기구, 04 30 03 참조', null, '3', 'true', '1', '2025-12-28 01:55:01.602303+00', '2026-02-09 03:26:58.608329+00'), ('bd0fc823-0595-4c68-9576-b187c66a318d', '18 21 06', '창문 개폐기', '창문 개폐기', null, '3', 'true', '2', '2025-12-28 01:55:14.597052+00', '2026-02-09 03:36:58.313004+00'), ('bd3e1505-80e3-417a-86ce-ce1b18b0f71b', '09 27 04', '폐쇄형 소변 수거 백', '내용물의 배출을 위한 개구부가 없는 소변 수거용 유연한 용기', null, '3', 'true', '1', '2025-12-28 01:55:03.241773+00', '2026-02-09 03:30:20.740792+00'), ('bd4c801e-6393-4371-901d-85e89f7ca105', '28 21 06', '우편물 처리용 보조기구', '우편물 발송을 위한 편지, 소포 및 기타 기재를 준비하고 우편물의 배달 및 수신을 용이하게 하는 장치 예를 들어 소인기(우편요금 인쇄기), 우편 분류기, 우편 개봉기, 봉투 충전 기계 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:17.179065+00', '2026-02-09 03:28:05.359464+00'), ('bd63ee8a-1659-4b4e-b82b-64f0b8999979', '09 18 31', '장루 보호용 보조기구', '외부의 유해한 영향으로부터 장루를 보호하거나 막는 장치 예를 들어 장루 실드, 장루 플러그, 특수 블리스터 등이 있다.', null, '3', 'true', '10', '2025-12-28 01:55:53.284844+00', '2026-02-09 03:27:15.521366+00'), ('bdbdf1a1-1dac-440f-834f-7c00f5c9b293', '09 30 14', '속옷과 유사한 어린이용 보조기구, 일회용', '일반 속옷과 유사하게 디자인된 어린이용 흡수성 요실금 보조기구', null, '3', 'true', '3', '2025-12-28 01:55:19.623602+00', '2026-02-09 03:30:20.740792+00'), ('be11bcbe-f31f-45cf-8d00-226cc678f9c5', '15 09 30', '장내 영양 공급을 위한 영양 시스템', '액체 음식을 위장관으로 직접 주입할 수 있는 영양 공급 시스템(예: 영양 공급) 예를 들어 장내 영양 공급 펌프, 튜브, 액세서리 등이 있다. 주입 펌프, 04 19 24 참조', null, '3', 'true', '10', '2025-12-28 01:55:53.791321+00', '2026-02-09 03:36:58.313004+00'), ('be43c171-6806-4116-8755-6b357eabec56', '24 18 12', '스탠드', '물체를 안정된 위치에 고정하기 위한 독립형 장치 사용하지 않을 때 보행 보조기구를 제자리에 고정하는 보조기구, 12 07 27 참조 칠판, 독서대 및 책받침 쿠션, 22 13 06 참조 공작물 및 공구 고정 및 위치 지정을 위한 보조기구, 28 12 06 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.199338+00', '2026-02-09 03:28:28.465723+00'), ('be63990e-58b0-4875-b9ed-adc99525ff01', '28 03 12', '업무 현장용 스툴 및 스탠딩 의자', '사람을 전반적으로 지지하거나 특히 선 자세 또는 거의 선 자세를 유지하도록 지원하는 등받이 또는 팔 지지대가 있거나 없으며 하나 이상의 다리가 있는 좌석 스툴, 18 09 04 참조 스탠딩 의자, 18 09 07 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.530406+00', '2026-02-09 03:28:28.465723+00'), ('be6e17af-fd59-40d4-9ff3-3a04977c3c11', '18 36 12', '약장', '약장', null, '3', 'true', '4', '2025-12-28 01:55:29.049402+00', '2026-02-09 03:36:58.313004+00'), ('beb4d3c6-c9c9-445a-bc6e-6c4c3241f643', '09 45 03', '면도 브러시, 면도날 및 (전기)면도기', '그립 어댑터 및 부착물, 24 18 06 참조', null, '3', 'true', '1', '2025-12-28 01:55:03.719814+00', '2026-02-09 03:30:20.740792+00'), ('bedd3b30-7ece-456f-bcb2-57700e38383a', '30 18 18', '기타 기재를 사용한 수공예용 공구, 기재 및 장비', '여러 매체로 예술 및 공예품을 만드는 데 사용되는 보조기구 예를 들어 티파니 작업, 종이접기, 바구니 만들기 등이 있다. 가위, 15 15 21 참조', null, '3', 'true', '6', '2025-12-28 01:55:41.400684+00', '2026-02-09 03:28:05.359464+00'), ('bf1021f6-29e6-4690-8c47-bdd3f50b70ff', '04 09 09', '광선 치료용 보안경', '자외선으로부터 눈을 보호하는 장치 눈 보호 또는 안면 보호용 보조기구, 09 06 06 참조', null, '3', 'true', '3', '2025-12-28 01:55:17.68674+00', '2026-02-09 03:26:41.971174+00'), ('bf310997-637a-487f-a633-d966f1b2680a', '18 03 12', '식탁', '식탁', null, '3', 'true', '3', '2025-12-28 01:55:21.68779+00', '2026-02-09 03:36:58.313004+00'), ('bf7dcf28-2187-4e73-b28c-f757496f1bc3', '09 03 45', '신발 및 부츠용 미끄럼 방지 보조기구', '미끄럼 방지를 위해 신발에 부착하는 장치 및 기재 보행 보조기구용 액세서리, 12 07 참조', null, '3', 'true', '13', '2025-12-28 01:55:58.33921+00', '2026-02-09 03:27:15.521366+00'), ('bfd9c27f-7f16-4710-842c-6687b1969a2a', '12 23 09', '내연력 전동 휠체어', '내연기관에 의해 구동되는 휠체어', null, '3', 'true', '3', '2025-12-28 01:55:20.783695+00', '2026-02-09 03:36:39.110787+00'), ('c070de6f-6334-4933-98a7-af7506e85451', '30 03 06', '놀이터 장비', '고정된 규칙 없이 일반적으로 어린이가 놀 수 있도록 구축된 실내 및 실외 구조물 예를 들어 그네, 그네 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:17.401852+00', '2026-02-09 03:28:05.359464+00'), ('c0ba9888-f3a7-4f2a-9306-e8d0fd069171', '06 06 36', '팔꿈치 관절', '해부학적 팔꿈치 관절의 움직임을 허용하거나 제어하는 상지 보조기의 관절 구성요소', null, '3', 'true', '15', '2025-12-28 01:56:00.031655+00', '2026-02-09 03:27:15.521366+00'), ('c0f1ddd0-9d0f-4c40-b058-d0edc8b04f65', '15 15 06', '재봉 또는 짜깁기를 하는 동안 고정된 위치에 기재를 고정하는 장치', '예를 들어 자수 링 등이 있다. 고정용 보조기구, 24 27 참조 공작물 및 공구 고정 및 위치 지정을 위한 보조기구, 28 12 06 참조', null, '3', 'true', '2', '2025-12-28 01:55:13.980364+00', '2026-02-09 03:36:58.313004+00'), ('c101a3f7-40d0-4243-8913-d6e9ffda8e73', '06 18 54', '상지 보철물의 구조적 구성요소', '인터페이스, 기능 및 정렬 구성요소를 연결하고 보철물의 무결성을 유지하는 구조적 구성요소 예를 들어 보철물 제작을 위한 내골격 및 외골격 구성요소 등이 있다.', null, '3', 'true', '21', '2025-12-28 01:56:02.811517+00', '2026-02-09 03:27:15.521366+00'), ('c10d5b02-c276-4dc1-b594-7e04e4ed15ad', '06 03 09', '흉요천추 보조기', '몸통의 흉부, 요추 및 천장골 부위의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '5', '2025-12-28 01:55:31.63717+00', '2026-02-09 03:27:15.521366+00'), ('c11765d6-4d5c-41b2-a90b-5db3c7998d58', '12 03 09', '전완 목발', '전완 수평 지지대, 손잡이, 샤프트 및 단일 팁으로 구성된, 보행 시 지지와 균형을 제공하는 휴대용 장치', null, '3', 'true', '3', '2025-12-28 01:55:20.105925+00', '2026-02-09 03:36:39.110787+00'), ('c12cb393-e26a-4519-998c-036f9f2f5077', '24 09 06', '고정 핸들 및 노브', '물체를 밀거나 당겨서 열거나 닫거나 이동시키는 해당 물체에 장착된 장치', null, '3', 'true', '2', '2025-12-28 01:55:16.00142+00', '2026-02-09 03:28:28.465723+00'), ('c1f44b33-40c9-401b-9367-40182ae79857', '12 03 06', '팔꿈치 목발', '팔꿈치 지지대, 샤프트, 손잡이 및 팁(들)으로 구성된, 보행 시 지지와 균형을 제공하는 휴대용 장치', null, '3', 'true', '2', '2025-12-28 01:55:12.379549+00', '2026-02-09 03:36:39.110787+00'), ('c1f6e6e2-bcbe-40a5-ac43-b3e89a5cf495', '09 12 06', '변기', '예를 들어 올림 또는 높이 조절이 가능한 변기, 세정기 및 공기 건조기가 내장된 변기 등이 있다. 변기에 부착할 수 있는 세정기 및 공기 건조기, 09 12 36 참조', null, '3', 'true', '2', '2025-12-28 01:55:11.259792+00', '2026-02-09 03:27:15.521366+00'), ('c2c0e4da-edf6-41a0-86e1-ccd2b31d2895', '12 36 15', '다른 보조기구에 고정되거나 장착된 고정식 호이스트', '시스템에 의해 제한된 구역에서 사람을 들어올려 이송하는 장비 예를 들어 욕조 호이스트 등이 있다. 일어서거나 앉는 것을 지원하는 상승 장치가 내장된 변기 시트, 09 12 21 참조 휠체어 없이 사람을 차량에 승하차할 수 있는 호이스트, 12 12 15 참조 휠체어에 앉은 사람을 차량에 승하차할 수 있는 보조기구, 12 12 18 참조', null, '3', 'true', '6', '2025-12-28 01:55:39.140869+00', '2026-02-09 03:36:39.110787+00'), ('c34961df-8162-4886-9c3e-d58749d2ad6b', '22 15 21', '수학과 물리 과학 훈련용 보조기구', '수학 및 생물학, 물리학, 화학 등의 자연과학 교육을 지원하는 기기', null, '3', 'true', '7', '2025-12-28 01:55:44.913069+00', '2026-02-09 03:28:46.630705+00'), ('c431ea5f-3d56-43fc-b2d5-37ab0b3de9af', '12 12 05', '속도 제어를 위한 차량 액세서리 및 차량 개조물', '감속 및 정지를 포함하여 운전자가 차량의 속도를 변경하는 데 도움이 되는 기기 및 개조물 예를 들어 주행 브레이크, 주차 브레이크 등을 포함한다.', null, '3', 'true', '1', '2025-12-28 01:55:04.290495+00', '2026-02-09 03:36:39.110787+00'), ('c44cb717-e04a-4384-8ecc-d065242f7fef', '09 31 03', '요실금 방지용 보조기구', '무의식적으로 소변이 나오는 것을 방지하는 보조기구 예를 들어 요도 플러그, 질 보, 음경 클램프, 요도를 접기 위한 풍선, 페서리 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:03.379062+00', '2026-02-09 03:30:20.740792+00'), ('c4f1a17c-fecf-46be-aa31-be0492d70df5', '06 12 13', '하퇴 보조기', '하부 다리 아래쪽을 감싸는 보조기', null, '3', 'true', '5', '2025-12-28 01:55:31.796849+00', '2026-02-09 03:27:15.521366+00'), ('c585c7dd-c3c3-45ca-b8e8-2ef98a42a6ee', '22 13 27', '수동 점자 작성 장비', '특수 스타일러스 또는 스틱을 사용하여 종이에 양각 점자 문자를 생성하는 장치', null, '3', 'true', '9', '2025-12-28 01:55:51.767417+00', '2026-02-09 03:28:46.630705+00'), ('c6159215-b8a4-46d4-8dcb-dac862970afa', '22 13 30', '타자기', '수동 및 전기 타자기 등을 포함한다(예: 점자 타자기).', null, '3', 'true', '10', '2025-12-28 01:55:54.099384+00', '2026-02-09 03:28:46.630705+00'), ('c62c5b09-894d-4440-924f-99151f85d009', '22 21 18', '지문자(손가락 스펠링) 훈련용 보조기구', '지문자(손가락 스펠링) 훈련용 보조기구', null, '3', 'true', '4', '2025-12-28 01:55:29.575244+00', '2026-02-09 03:28:46.630705+00'), ('c6389dda-7138-49e6-bd1d-f4e48d7596b3', '15 18 12', '실내 원예 및 꽃꽂이 도구', '실내에 있는 식물이나 정원을 가꾸거나 재배하고 꽃꽂이를 전시할 수 있는 보조기구', null, '3', 'true', '4', '2025-12-28 01:55:28.292946+00', '2026-02-09 03:36:58.313004+00'), ('c65c892f-5326-4160-8cc8-453a78da93e0', '18 33 12', '구조 장비', '위험한 상황에서 사람을 대피시키기 위한 장치', null, '3', 'true', '6', '2025-12-28 01:55:39.869256+00', '2026-02-09 03:36:58.313004+00'), ('c69e40c0-2512-4ed7-9627-180768309a08', '22 24 33', '인터폰 및 현관 인터폰', '서로 다른 위치에 있는 두 명 이상의 사이에서 제한적이거나 사적인 대화를 촉진하기 위한 독립형 전자 통신 시스템 예를 들어 도어 오프너가 통합된 도어 출입 시스템, 현관 전화 증폭기 등을 포함한다. 신호, 경보, 모니터링 및 식별용 보조기구, 22 29 참조 폐쇄회로 텔레비전 시스템, 22 18 18 참조', null, '3', 'true', '8', '2025-12-28 01:55:49.061922+00', '2026-02-09 03:28:46.630705+00'), ('c7293c53-70cc-4382-b174-0f19be14c794', '12 07 33', '보행 보조기 및 보행 프레임의 높이를 조절하는 액세서리', '보행 보조기구의 높이를 높이기 위해 보행 보조기 또는 보행 프레임에 추가 또는 부착할 수 있는 장치', null, '3', 'true', '9', '2025-12-28 01:55:50.843038+00', '2026-02-09 03:36:39.110787+00'), ('c7641276-a77c-49b2-8b43-54bb81f1e8ea', '18 18 10', '탈착식 가로대 및 손잡이', '서 있거나 자세를 바꾸는 동안 사람을 지지하도록 클램프 또는 흡착 패드를 사용하여 벽, 바닥, 욕조 또는 가구에 임시로 부착할 수 있으며 도구 없이 제거할 수 있는 장치(일반적으로 직선 또는 각진 봉) 침대에 부착하는 자체 기립용 레일, 18 12 28 참조', null, '3', 'true', '3', '2025-12-28 01:55:22.10644+00', '2026-02-09 03:36:58.313004+00'), ('c76ff726-0f7a-433b-8723-7943ebdbda66', '12 24 11', '반수동 자전거', '손으로 추진하는 수동 자전거로 전환하기 위해 수동 휠체어에 추가하는 장치 손으로 움직이는 삼륜거 및 사륜거, 12 18 09 참조', null, '3', 'true', '3', '2025-12-28 01:55:20.849069+00', '2026-02-09 03:36:39.110787+00'), ('c780acd3-4dc5-4243-b08c-d23213da1f74', '12 06 06', '보행 보조기', '걸을 때 안정성과 균형을 유지할 수 있도록 밀거나 당겨서 이동할 수 있는 손잡이와 3개 이상의 캐스터/바퀴가 달린 다리가 있는 보행 장치 예를 들어 밀 수 있는 좌석이 있는 보행 보조기, 앞쪽에 개구부가 있는 당기는 방식의 반전 보행 보조기 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:12.449228+00', '2026-02-09 03:36:39.110787+00'), ('c828708e-ea61-4490-9c69-10bb8ad3b621', '12 24 42', '물건을 고정하거나 운반하기 위해 휠체어에 부착된 장치', '하나 이상의 물건을 운반하기 위해 휠체어에 고정된 보조기구 예를 들어 휠체어에 부착되는 파우치, 바스켓 및 케이스, 지팡이 및 목발 고정 장치, 보행기 캐리어, 휠체어용 트레일러 등이 있다. 자전거용 트레일러, 12 18 24 참조', null, '3', 'true', '12', '2025-12-28 01:55:57.517158+00', '2026-02-09 03:36:39.110787+00'), ('c85da207-346a-4641-b3f1-4571278c476a', '06 12 30', '하지 보조기의 인터페이스 구성요소', '인터페이스 구성요소는 사용자와 직접 접촉한다. 이러한 구성요소는 보조기와 사용자 사이에 그 기능으로 인한 힘을 전달하며 보조기를 제자리에 유지할 수 있다. 예를 들어 쉘, 패드, 스트랩, 발 보조기, 신발 등이 있다.', null, '3', 'true', '15', '2025-12-28 01:56:00.101879+00', '2026-02-09 03:27:15.521366+00'), ('c8f104bd-fd4a-4cf0-a6b5-f01b890b30b0', '09 33 06', '미끄럼 방지 목욕 매트, 미끄럼 방지 샤워 매트 및 미끄럼 방지 테이프', '목욕 또는 샤워 중에 미끄러지는 것을 방지하기 위한 기재 바닥 및 계단용 미끄럼 방지 소재, 18 33 03 참조', null, '3', 'true', '3', '2025-12-28 01:55:19.752847+00', '2026-02-09 03:30:20.740792+00'), ('c9445190-9c82-4f24-990d-4eb03af3b100', '04 15 06', '지속적 복막 투석 장치(CAPD)', '신장 기능이 좋지 않거나 신장이 없는 사람의 혈액을 지속적으로 정화하기 위한 신체 착용 장치 예를 들어 주입 장치 백, 프레임, 히터, 누관 캐뉼러 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:09.497089+00', '2026-02-09 03:26:41.971174+00'), ('c9733d81-65c3-43c0-adb4-6c37540ec8f7', '12 08 03', '가이드 지팡이', '걷는 동안 탐색 및 식별을 위한 긴 지팡이', null, '3', 'true', '1', '2025-12-28 01:55:04.06285+00', '2026-02-09 03:36:39.110787+00'), ('c97ca834-85a6-438b-8f90-7f358b6ae20c', '22 21 30', '점자 이외의 촉각 기호 사용 훈련용 보조기구', '점자 이외의 촉각 기호 사용 훈련용 보조기구', null, '3', 'true', '8', '2025-12-28 01:55:48.983855+00', '2026-02-09 03:28:46.630705+00'), ('c99cb357-3fea-4a65-94b6-c622cff8763e', '27 06 03', '길이 측정용 보조기구', '길이 측정용 보조기구', null, '3', 'true', '1', '2025-12-28 01:55:08.25234+00', '2026-02-09 03:28:28.465723+00'), ('c9a9e6aa-bf97-4d90-bbe2-76bc5469955d', '28 24 06', '업무 현장의 조명 제어용 보조기구', '업무 현장의 조명 조건 조절 장치 조명 제어용 보조기구, 27 03 15 참조', null, '3', 'true', '2', '2025-12-28 01:55:17.256045+00', '2026-02-09 03:28:05.359464+00'), ('c9bb5dde-5f85-4371-8b4f-8fcbae036a5d', '12 12 30', '빈 휠체어를 차량에 싣거나 차량에 부착하기 위한 기기', '하나 이상의 휠체어를 운반하도록 특별히 설계된 차량 후면에 부착할 수 있는 트레일러 또는 빈 휠체어를 수송하기 위해 차량의 지붕이나 후면에 장착할 수 있는 랙 또는 프레임 예를 들어 스쿠터 수송용 보조기구 등이 있다.', null, '3', 'true', '11', '2025-12-28 01:55:55.802786+00', '2026-02-09 03:36:39.110787+00'), ('ca4eb81e-21d1-4dba-9364-5a8630f57039', '04 09 03', '자외선 A(UVA) 램프', '주로 피부 질환 치료에 사용되는 장파 자외선 치료용 램프', null, '3', 'true', '1', '2025-12-28 01:55:01.099396+00', '2026-02-09 03:26:41.971174+00'), ('ca9c4192-04ba-4a35-87c5-261b2ddc0c9d', '18 09 24', '의자 리프트 및 의자 운반기', '탑승자가 있거나 없는 상태로 바퀴가 없는 의자를 운반하는 장치', null, '3', 'true', '7', '2025-12-28 01:55:44.247874+00', '2026-02-09 03:36:58.313004+00'), ('caef5404-4f5a-4f14-9961-6f7d85f1690f', '06 03 30', '척추 및 두개골 보조기의 인터페이스 구성요소', '보조기의 인터페이스 구성요소는 사용자와 직접 접촉하는 구성요소이다. 이러한 구성요소는 보조기와 사용자 사이에 그 기능으로 인한 힘을 전달하며 보조기를 제자리에 유지할 수 있다. 예를 들어 쉘, 패드, 스트랩 등이 있다.', null, '3', 'true', '11', '2025-12-28 01:55:54.676644+00', '2026-02-09 03:27:15.521366+00'), ('caf936be-d750-4837-b765-53c56983475c', '18 03 15', '침대 테이블', '침대 위나 옆에서 사용하도록 고안된 테이블 목욕용 들것, 샤워 테이블 및 기저귀 교환대, 09 33 12 참조 침대 옆 캐비닛, 18 36 09 참조', null, '3', 'true', '4', '2025-12-28 01:55:28.366427+00', '2026-02-09 03:36:58.313004+00'), ('cb17c23e-e2d1-4850-b53e-642e81582f81', '12 18 04', '발로 움직이는 자전거', '1인용 페달 추진 이륜 자전거', null, '3', 'true', '1', '2025-12-28 01:55:04.522551+00', '2026-02-09 03:36:39.110787+00'), ('cb473109-f455-495b-babd-ec1092fd41f1', '12 36 04', '선 자세로 사람을 이송하기 위한 이동식 호이스트', '앉은 자세에서 선 자세로 사람을 들어올려 자세를 바꾸는 장비. 장비를 자유롭게 이동할 수 있다. 신체 지지 장치는 슬링, 발 지지대 및 다리 또는 무릎 지지대로 구성', null, '3', 'true', '2', '2025-12-28 01:55:13.611736+00', '2026-02-09 03:36:39.110787+00'), ('cb9aa59f-7f25-4f44-a03c-1e7398b434d0', '04 26 21', '귀납적/연역적 추론 훈련용 보조기구', '일련의 사실로부터 결론을 도출하고 이를 일반화 및 해석하기 위한 논리적 사고 훈련용 기기', null, '3', 'true', '7', '2025-12-28 01:55:41.734133+00', '2026-02-09 03:26:58.608329+00'), ('cb9fb406-79c2-4536-95cc-59d97db1829d', '22 18 18', '폐쇄회로 텔레비전 시스템', '카메라로 영상을 레코더로 전송하거나 원격 위치에 직접 표시하는 폐쇄 시스템 이미지 확대 시스템, 22 03 18 참조 위치 파악 및 추적 시스템, 22 29 12 참조', null, '3', 'true', '6', '2025-12-28 01:55:40.282646+00', '2026-02-09 03:28:46.630705+00'), ('cba194e1-aecf-487b-9cff-a2200a6c2cdb', '15 15 03', '재봉 기계', '재봉 후프, 핀 쿠션 및 짜깁기 장치', null, '3', 'true', '1', '2025-12-28 01:55:05.459456+00', '2026-02-09 03:36:58.313004+00'), ('cbf71c8e-b8fc-435e-980d-6a998cea5fc2', '06 03 36', '척추 및 두개골 보조기의 마감 구성요소', '미용 구성요소는 보조기에 모양, 색상 및 질감을 부여하는 수단이다. 예를 들어 충전재, 커버, 슬리브 등이 있다.', null, '3', 'true', '13', '2025-12-28 01:55:57.889744+00', '2026-02-09 03:27:15.521366+00'), ('cbfc77e4-b3e2-49ce-9d75-93b4f2cac7f2', '24 13 05', '무선 리모컨', '전기기기 작동을 위한 무선 장치', null, '3', 'true', '2', '2025-12-28 01:55:16.070235+00', '2026-02-09 03:28:28.465723+00'), ('cc217f9d-58c0-4562-93c6-57cf30741e21', '15 09 03', '식음료 제공 및 보관용 보조기구', '식음료를 제공하는 용기 및 이러한 행위에 도움을 주는 기구 예를 들어 서빙용 도구, 쟁반, 식품 용기, 곽 트롤리, 가열된 서빙 접시, 진공 플라스크 등을 포함한다. 운반 및 수송용 보조기구, 24 36 참조', null, '3', 'true', '1', '2025-12-28 01:55:05.322844+00', '2026-02-09 03:36:58.313004+00'), ('cc249b5a-295b-4833-91e9-8f3205f9b1f4', '12 12 21', '빈 휠체어를 차량에 싣기 위한 보조기구', '빈 휠체어를 차량 위 또는 내부에 들어 올리고 위치시키는 장치 예를 들어 휠체어용 자동차 호이스트 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:47.50716+00', '2026-02-09 03:36:39.110787+00'), ('cc9a66fd-bef2-4fb2-939b-1020dc0bec9a', '04 24 09', '혈압계', '혈압계', null, '3', 'true', '2', '2025-12-28 01:55:09.718831+00', '2026-02-09 03:26:58.608329+00'), ('cce8c01d-0529-4fec-9a61-db824f38fe60', '04 48 27', '치료 중 신체 위치 조정을 위한 보조기구', '치료가 용이하도록 올바른 위치에서 사람을 지지하는 장비 경사 테이블, 04 48 42 참조', null, '3', 'true', '6', '2025-12-28 01:55:37.094582+00', '2026-02-09 03:26:58.608329+00'), ('cd9ea583-bdb3-43b1-8a1b-cb9b47170374', '18 09 07', '스탠딩 의자', '선 자세 또는 거의 선 자세로 있는 사람을 지지하는 다리가 하나 이상인 좌석 시트가 달린 지팡이, 12 03 18 참조 업무 현장용 스툴 및 스탠딩 의자, 28 03 12 참조', null, '3', 'true', '3', '2025-12-28 01:55:21.828049+00', '2026-02-09 03:36:58.313004+00'), ('cdcebb21-f97d-4612-9db0-da8277405c76', '09 18 28', '내부 장루 배액 또는 세척용 보조기구', '내부 장루 배액 또는 세척용 기구 예를 들어 내부 장루에서 직접 변기 등으로 신체 노폐물을 배출하기 위한 튜브 또는 신체 노폐물을 수거하기 위한 백에 연결된 튜브 등이 있다.', null, '3', 'true', '9', '2025-12-28 01:55:50.575414+00', '2026-02-09 03:27:15.521366+00'), ('ce2ef7a2-bad7-4a1a-bc93-d9020bfceeb3', '04 26 03', '기억력 훈련용 보조기구', '기억력 훈련용 기기 및 소프트웨어', null, '3', 'true', '1', '2025-12-28 01:55:01.455511+00', '2026-02-09 03:26:58.608329+00'), ('ce973b27-173b-45b5-a12a-a5dfb4f7ec8b', '22 13 21', 'DAISY 플레이어 및 전자책 리더', '예를 들어 DAISY 플레이어 및 전자책 리더용 소프트웨어 등을 포함한다.', null, '3', 'true', '7', '2025-12-28 01:55:44.820969+00', '2026-02-09 03:28:46.630705+00'), ('cebffec8-22a6-44ad-875b-8a98253f4108', '06 24 40', '하지 보철물용 라이너', '지지, 안정화 및 현수를 달성하기 위한 하지 보철물의 인터페이스 구성요소. 기능 구성요소의 활성화/제어에 기여하는 요소를 포함할 수 있다. 예를 들어 발 부분 절단, 발목 절단, 경골(무릎 아래) 절단, 무릎 절단, 경대퇴(무릎 위) 절단, 고절단, 경골반 절단용 소켓에 배치할 조립식 및 맞춤형 라이너 등이 있다.', null, '3', 'true', '15', '2025-12-28 01:56:00.288061+00', '2026-02-09 03:27:15.521366+00'), ('cf56fa4f-ff90-47c2-91e2-8d33040376ac', '04 03 12', '호흡기', '호흡이 곤란한 사람을 위해 코, 입 또는 공기관의 인공 구멍(기관절개)을 통해 인공 통기를 제공하는 장치 예를 들어 주변 공기를 걸러내거나 정화하는 인공호흡기, CPAP(지속적기도양압), BiPAP(이상성양압호흡기) 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:17.606299+00', '2026-02-09 03:26:41.971174+00'), ('cf68981c-9759-4a80-8ca1-c75a251a426e', '04 26 30', '시간 이해 훈련용 보조기구', '시간의 개념과 기능 훈련용 보조기구', null, '3', 'true', '10', '2025-12-28 01:55:52.319187+00', '2026-02-09 03:26:58.608329+00'), ('cff6851b-7ed4-47a1-92a6-3a34bbd7457b', '12 25 15', '휠체어용 다리 지지대 및 발 지지대', '예를 들어 다리 지지대, 발 지지대, 발판, 휠체어에 부착된 스텀프 지지대, 회전, 내전 근, 무릎 분리대 등을 포함한다. 앉는 가구용 다리 받침대 및 발 받침대, 18 10 15 참조', null, '3', 'true', '5', '2025-12-28 01:55:33.573809+00', '2026-02-09 03:36:39.110787+00'), ('d0225870-7baa-46c7-a197-018ea09f1536', '12 24 28', '휠체어 또는 휠체어의 일부를 청소하는 장치', '예를 들어 휠체어 청소 시스템, 휠체어 타이어 브러시 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:47.736045+00', '2026-02-09 03:36:39.110787+00'), ('d023a208-c47e-4f22-b7c9-36e64e4bd858', '28 27 07', '직업 훈련용 보조기구', '기본 직업 기술(예: 컴퓨터, 통신 사용, 프로그래밍 교육, 경제 과목 교육)을 가르치는 보조기구 원격 통신용 보조기구, 22 24 참조 시간, 계획, 기억 및 체계화 표시를 위한 보조기구, 22 28 참조 신호, 경보, 모니터링 및 식별용 보조기구, 22 29 참조', null, '3', 'true', '2', '2025-12-28 01:55:17.333271+00', '2026-02-09 03:28:05.359464+00'), ('d06ce722-4817-4a83-9695-f966c90824f3', '12 18 09', '손으로 움직이는 삼륜거 및 사륜거', '바퀴가 3개 또는 4개인 손 추진 자전거', null, '3', 'true', '4', '2025-12-28 01:55:27.216305+00', '2026-02-09 03:36:39.110787+00'), ('d1a17975-63d4-44b8-8c82-48ee24306b6e', '12 18 15', '2인승 이상의 탠덤차, 삼륜거 및 사륜거', '페달로 추진하는 두 명 이상의 사람이 탈 수 있도록 두 개 이상의 좌석이 있는 장치', null, '3', 'true', '5', '2025-12-28 01:55:33.227134+00', '2026-02-09 03:36:39.110787+00'), ('d1b97066-74dd-4eb2-8df2-dcaef7f9eade', '04 28 09', '신체적 접촉을 통해 감각을 자극하는 보조기구', '정적 또는 동적 물리적 접촉을 통해 감각을 자극하는 보조기구 예를 들어 감각 자극을 위한 커버, 쿠션, 의류, 브러시, 볼 등을 포함한다.', null, '3', 'true', '3', '2025-12-28 01:55:18.116486+00', '2026-02-09 03:26:58.608329+00'), ('d33c2a24-222c-46c5-b513-0df1f692f6db', '09 09 09', '옷걸이', '옷을 입는 동안 정해진 위치에 옷을 고정하는 장치', null, '3', 'true', '3', '2025-12-28 01:55:19.099218+00', '2026-02-09 03:27:15.521366+00'), ('d33cee1a-dd8e-4342-af16-2dca279435dd', '18 09 39', '모듈식 좌석 시스템', '특정 시트 구성을 달성하기 위해 위치를 조절할 수 있는 선택된 시트 모듈을 부착할 수 있는 프레임워크 기반 시트 좌석 시스템 예를 들어 별도의 용도로 조립된 의자 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:48.427766+00', '2026-02-09 03:36:58.313004+00'), ('d3c92388-f34a-49e3-aa60-5f31525b4849', '15 03 15', '조리용 기계', '예를 들어 푸드 믹서, 푸드 프로세서, 수동 및 전동 달걀 거품기 등이 있다. 상품 생산 및 가공용 기계, 28 15 09 참조', null, '3', 'true', '5', '2025-12-28 01:55:33.849751+00', '2026-02-09 03:36:58.313004+00'), ('d3c9d437-8554-4769-ad50-b87737a28595', '06 03 08', '흉요추 보조기', '몸통의 흉부 및 요추 부위의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '4', '2025-12-28 01:55:25.436579+00', '2026-02-09 03:27:15.521366+00'), ('d42315e4-34d5-4eae-85cb-aff05f450fcd', '09 21 18', '피부 보호제', '피부를 보호하는 물질', null, '3', 'true', '5', '2025-12-28 01:55:32.4523+00', '2026-02-09 03:27:15.521366+00'), ('d46db8d7-0ad9-4177-aea3-b7d70ccdfcce', '22 18 21', '비디오 자막 및 자막 텔레비전용 디코더', '비디오 자막을 인공 음성으로 변환하고 음성 출력을 디코딩하여 비디오 자막을 제공하는 장치 음성 인식 시스템은 제외된다.', null, '3', 'true', '7', '2025-12-28 01:55:44.981081+00', '2026-02-09 03:28:46.630705+00'), ('d5827ffb-ec7b-4bdc-9a29-9978517c4710', '22 21 33', '의사소통을 위한 시각 기호 사용 훈련용 보조기구', '의사소통을 위한 Bliss, 아이콘, 그림, 사진 및 기타 기호의 사용을 교육하기 위한 보조 기구를 포함한다.', null, '3', 'true', '9', '2025-12-28 01:55:51.917398+00', '2026-02-09 03:28:46.630705+00'), ('d58fe977-c452-42d1-a002-a10ca5dcde39', '18 03 06', '독서대, 책상 및 입식 책상', '업무용 책상, 28 03 03 참조', null, '3', 'true', '1', '2025-12-28 01:55:05.617453+00', '2026-02-09 03:36:58.313004+00'), ('d61214b6-c698-4689-ae8f-96a4433d53e9', '18 12 10', '전동 조절식 침대 및 분리형 침대 보드/매트리스 지지대', '높이나 각도를 조절할 수 있는 섹션이 하나 이상인 매트리스 지지대를 갖춘 침대. 조정은 사용자 또는 보조인이 전동 장치를 조작하여 수행함.', null, '3', 'true', '3', '2025-12-28 01:55:21.974488+00', '2026-02-09 03:36:58.313004+00'), ('d6386ee4-6a6f-47e9-9732-9a465cbbb9b4', '09 18 19', '장루 성형 치료용 유출 시스템을 지지하고 제자리에 고정하기 위한 보조기구', '결장루 주위 탈장의 경우 장루 판 또는 장루 백의 올바른 위치를 유지하기 위한 지지대를 제공하는 보조기구 예를 들어 벨트 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:32.384553+00', '2026-02-09 03:27:15.521366+00'), ('d673f211-0b31-4bca-a41a-610a44fe7eda', '06 18 51', '상지 보철물용 정렬 구성요소', '서로에 대한 보철물 구성요소의 위치 변경을 허용하는 정렬 구성요소 예를 들어 보철물 구조의 일부이거나 제거하고 다른 구조적 구성요소로 대체할 수 있는 정렬 구성요소 등이 있다.', null, '3', 'true', '20', '2025-12-28 01:56:02.664924+00', '2026-02-09 03:27:15.521366+00'), ('d6805ba1-6cf3-4c89-954f-4530a8a207f4', '09 21 15', '밀봉제', '피부의 부위를 완전히 감싸는 물질', null, '3', 'true', '4', '2025-12-28 01:55:26.460341+00', '2026-02-09 03:27:15.521366+00'), ('d79c954c-eb14-4d3a-9ef9-660cbfae9cbb', '12 36 21', '호이스트용 신체 지지 장치', '호이스트로 들어 올리는 사람을 지지하기 위한 장치 예를 들어 슬링, 시트, 들것, 이동식 변기 시트 및 사람 이송용 고정식 호이스트 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:47.989734+00', '2026-02-09 03:36:39.110787+00'), ('d7bbc152-3363-46a3-a716-15c775fe0bba', '06 24 48', '하지 절단 환자용 임시 보철물', '최종 보철물 제공 전 하지 절단 환자의 초기 이동에 사용되는 장치', null, '3', 'true', '21', '2025-12-28 01:56:02.895652+00', '2026-02-09 03:27:15.521366+00'), ('d881fbe6-706d-454f-8f14-b0a16976604c', '06 24 45', '하지 보철물용 정렬 구성요소', '서로에 대한 보철물 구성요소의 위치 변경을 허용하는 정렬 구성요소 예를 들어 보철물 구조의 일부이거나 제거하고 다른 구조적 구성요소로 대체할 수 있는 정렬 구성요소 등이 있다.', null, '3', 'true', '18', '2025-12-28 01:56:02.367527+00', '2026-02-09 03:27:15.521366+00'), ('d8ea0382-d2f7-486f-a83c-5ab7e9af76cc', '09 30 27', '소변을 담는 남성용 파우치, 일회용', '음경과 때로는 음낭을 덮을 수 있도록 주머니 형태로 디자인된 남성용 흡수성 요실금 패드', null, '3', 'true', '10', '2025-12-28 01:55:53.361942+00', '2026-02-09 03:30:20.740792+00'), ('d900667b-82a9-4dc4-a83a-76774e51d933', '09 33 36', '신체 건조 보조기구', '신체를 말린 있는 기재 변기, 09 12 06 참조 변기에 부착하는 세정기 및 공기 건조기, 09 12 36 참조 헤어 드라이어, 09 39 09 참조', null, '3', 'true', '15', '2025-12-28 01:56:00.578321+00', '2026-02-09 03:30:20.740792+00'), ('d9b9bda1-6462-47a5-97b2-89e64ce9104d', '04 28 12', '지각 차별 및 매칭 훈련용 보조기구', '외부 자극을 구별, 일치, 분류할 수 있게 해주는 장비 예를 들어 진동 의자(청각 장애인 훈련용) 등을 포함한다.', null, '3', 'true', '4', '2025-12-28 01:55:25.212939+00', '2026-02-09 03:26:58.608329+00'), ('d9cc4496-937c-4beb-9f7b-c414848de5c6', '06 12 27', '고관절', '해부학적 고관절의 움직임을 허용하거나 제어하는 하지 보조기의 관절 구성요소', null, '3', 'true', '14', '2025-12-28 01:55:59.245677+00', '2026-02-09 03:27:15.521366+00'), ('da3137b1-3472-4459-a782-93014311eaf8', '04 25 03', '언어 검사 및 평가 기재', '의사소통 수단으로 언어를 사용하고 이해하는 방법을 검사하고 평가하는 장비', null, '3', 'true', '1', '2025-12-28 01:55:01.387495+00', '2026-02-09 03:26:58.608329+00'), ('da7976e0-4699-4142-997c-47840e4565b0', '09 03 21', '스커트 및 드레스', '스커트 및 드레스', null, '3', 'true', '6', '2025-12-28 01:55:37.606069+00', '2026-02-09 03:27:15.521366+00'), ('dabcb21c-8cb9-4e3a-80b5-807036e80bdf', '06 06 12', '손목-손 보조기', '손목 관절과 손의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '4', '2025-12-28 01:55:25.599502+00', '2026-02-09 03:27:15.521366+00'), ('db2f65ef-2e56-40e6-b176-bba79ad80598', '22 03 12', '쌍안경 및 망원경', '한 눈 또는 두 눈으로 멀리 있는 물체의 이미지를 확대하는 장치 예를 들어 안경 장착 단안 및 쌍안 망원경 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:29.135589+00', '2026-02-09 03:28:46.630705+00'), ('db39900d-2eb4-4b51-8513-b6167455027f', '04 33 03', '조직 무결성을 위한 시트 쿠션 및 밑깔개', '둔부에 가해지는 하중의 재분배를 통한 조직 무결성을 위한 장치 변기 시트용 패딩, 09 12 45 참조 시트 쿠션 및 밑깔개, 12 25 06 참조', null, '3', 'true', '1', '2025-12-28 01:55:01.790473+00', '2026-02-09 03:26:58.608329+00'), ('db446f57-9029-4fae-b7d4-d062367aadd4', '24 36 12', '트롤리', '손잡이가 있거나 없는 평평한 표면이 있는 상품 운반을 위한 바퀴 달린 무동력 장치 음식과 음료를 제공하고 보관하기 위한 보조기구, 15 09 03 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.33125+00', '2026-02-09 03:28:28.465723+00'), ('dc5c1033-e70a-45cb-ab53-783269e33f87', '28 06 04', '수동식 산업용 수송 장비', '물품을 운반하기 위한 바퀴가 2개 이상인 장치. 옆의 바닥에 서서 사람이 장치를 조작함. 예를 들어 산업용 캐스터 세트, 카트, 트롤리 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:08.38745+00', '2026-02-09 03:28:28.465723+00'), ('dd8f087d-1613-465f-bfeb-c516bfb910eb', '24 36 06', '캐스터 세트', '회전 롤러/휠이 있는 장치', null, '3', 'true', '2', '2025-12-28 01:55:16.450509+00', '2026-02-09 03:28:28.465723+00'), ('dd902d61-a94f-417a-9a67-dff8a9d84c76', '30 09 15', '승마용 보조기구', '승마를 즐길 수 있도록 지원하는 보조기구', null, '3', 'true', '5', '2025-12-28 01:55:36.548744+00', '2026-02-09 03:28:05.359464+00'), ('dd9e0058-70a4-4475-9c97-4544c62fabf4', '09 31 06', '변실금 방지용 보조기구', '무의식적으로 대변이 나오는 것을 방지하는 보조기구 예를 들어 항문 탐폰, 플러그 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:11.837723+00', '2026-02-09 03:30:20.740792+00'), ('dd9e0c50-aae9-46fc-95f0-ab89f91b9c8b', '15 09 09', '마개 및 깔때기', '마개는 액체가 용기 밖으로 쏟아지는 것을 방지하는 장치. 깔때기는 액체를 용기에 부을 때 유출을 줄이는 원뿔 모양의 장치임', null, '3', 'true', '3', '2025-12-28 01:55:21.377309+00', '2026-02-09 03:36:58.313004+00'), ('dda2dccb-ef18-4345-a60a-e18ee1340693', '22 06 06', '청각 증폭기', '주변 소리를 증폭시키거나 한 명 이상의 목소리 볼륨을 높이기 위해 사람의 신체 위나 근처에 배치하는 장치 예를 들어 통신 증폭기 등을 포함한다.', null, '3', 'true', '2', '2025-12-28 01:55:15.042492+00', '2026-02-09 03:28:46.630705+00'), ('dddc3f68-3e44-4624-b38f-0bc74c805ea6', '09 33 05', '목욕 의자', '욕조 가장자리에 걸거나 욕조 안에 배치하는 의자 예를 들어 등받이가 있거나 없는 목욕용 의자를 포함한다.', null, '3', 'true', '2', '2025-12-28 01:55:11.936303+00', '2026-02-09 03:30:20.740792+00'), ('de687b55-b689-4629-8d26-428fffc0e0d6', '09 06 03', '머리 보호용 보조기구', '외상으로부터 머리를 보호하는 헬멧 및 기타 모자 차광용 헬멧은 제외한다. 모자, 09 03 09 참조', null, '3', 'true', '1', '2025-12-28 01:55:02.575274+00', '2026-02-09 03:27:15.521366+00'), ('deb40478-c801-4cd0-b157-afe8e42d3944', '09 30 30', '방수 받침이 없는 패드, 일회용', '방수 받침이나 일체형 고정 장치가 없는 흡수성 요실금 패드; 방수 받침이 포함된 별도의 고정 장치를 사용하여 제자리에 고정하거나 다른 흡수성 요실금 기구 내부에 사용한다.', null, '3', 'true', '12', '2025-12-28 01:55:57.224701+00', '2026-02-09 03:30:20.740792+00'), ('ded69216-2227-49c5-940a-bd58ec4175ec', '09 06 24', '몸통 보호 또는 전신 보호용 보조기구', '예를 들어 넘어질 때 골절을 방지하기 위한 보호 기능이 내장된 바지 및 내의 등이 있다.', null, '3', 'true', '8', '2025-12-28 01:55:46.992337+00', '2026-02-09 03:27:15.521366+00'), ('df004aac-55cf-4ebd-8419-ef1d411c5b1c', '18 10 03', '등쿠션', '앉는 자세와 좌식 가구의 편안함을 향상시키는 비장착형 용품 예를 들어 요추 지지대와 등받이 패드 등을 포함한다. 조직 무결성을 위한 등쿠션 및 패드, 04 33 04 참조 휠체어용 등받이, 12 25 03 참조', null, '3', 'true', '1', '2025-12-28 01:55:05.833724+00', '2026-02-09 03:36:58.313004+00'), ('df7d76e1-08ab-4f06-bc43-a68f43f8dbc6', '09 06 12', '팔꿈치 보호 또는 팔 보호용 보조기구', '부상으로부터 보호하기 위한 보행 보조기구 액세서리, 12 07 18 참조', null, '3', 'true', '4', '2025-12-28 01:55:26.112654+00', '2026-02-09 03:27:15.521366+00'), ('e0142c52-1fb6-47fb-86ca-1c01b14e612a', '28 03 15', '업무 현장의 보관 및 공급 시스템', '업무 현장에서 쉽게 접근할 수 있도록 물건을 보관하는 장치 예를 들어 구성품 상자, 서류 캐비닛, 용기 등이 있다. 선반, 18 36 03 참조 찬장, 18 36 06 참조', null, '3', 'true', '5', '2025-12-28 01:55:36.268971+00', '2026-02-09 03:28:28.465723+00'), ('e0656e90-5d17-45da-a551-d1351d089173', '09 30 26', '소변을 담는 패드(접착 스트립 포함), 일회용', '속옷용 패드는 일반적으로 소량의 소변을 담을 수 있도록 설계되며 성별에 따라 모양이 다른 경우가 많다. 요도를 덮지만 항문은 덮지 않는 패드(즉, 소변은 담지만 대변은 담지 않음), 사용자의 일반 속옷에 위치하며 제자리에 고정하는 데 도움이 되는 접착 스트립이 있을 수 있다.', null, '3', 'true', '9', '2025-12-28 01:55:50.684666+00', '2026-02-09 03:30:20.740792+00'), ('e0672d89-a2c9-472b-8a24-b81838ab210e', '04 33 04', '조직 무결성을 위한 등쿠션 및 등받이 패드', '등의 취약부의 하중을 재분배하는 장치 등받이, 12 25 03 참조', null, '3', 'true', '2', '2025-12-28 01:55:10.234046+00', '2026-02-09 03:26:58.608329+00'), ('e08cb481-aba9-4b6a-859b-329bae868e57', '12 07 15', '특정 신체 부위를 지지하는 보행 보조기구용 액세서리', '사용자가 보조기구를 사용하는 동안 올바른 자세를 유지할 수 있도록 특정 신체 부위를 지지하는 보행 보조기구에 부착된 보조기구 예를 들어 겨드랑이 지지대, 등 지지대, 머리 지지대, 안전 벨트 등이 있다. 신체 안정화 보조기구, 09 07 참조', null, '3', 'true', '3', '2025-12-28 01:55:20.23638+00', '2026-02-09 03:36:39.110787+00'), ('e09dea5f-751b-447e-9c1c-051994365b73', '28 06 09', '자재를 들어 올리고 운반하는 데 사용하는 전동 산업용 차량', '화물을 들어 올려 운반하는 수송 차량. 사람이 차량에 앉거나 서서 차량을 조작함. 예를 들어 지게차, 오더 피킹 스태커 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:36.343166+00', '2026-02-09 03:28:28.465723+00'), ('e0ad3158-65c3-4fd9-a630-895ef5c407f1', '22 28 06', '달력 및 시간표', '일상생활에서 시간을 관리하기 위해 특정 시간과 관련된 계획된 활동이나 순서에 대한 정보를 제공하는 기능이 있거나 없는 캘린더 정보를 제공하는 기기 예를 들어 특별한 달력 소프트웨어 등을 포함한다. 사무용 소프트웨어 및 산업용 소프트웨어, 28 21 12 참조', null, '3', 'true', '2', '2025-12-28 01:55:15.573453+00', '2026-02-09 03:28:46.630705+00'), ('e0dbfd7e-cf06-4285-9aa7-6995b9722bd7', '09 03 12', '장갑 및 벙어리장갑', '손 보호용 보조기구, 09 06 15 참조', null, '3', 'true', '3', '2025-12-28 01:55:18.941747+00', '2026-02-09 03:27:15.521366+00'), ('e1869840-90cc-4516-a8d5-f3ddc57fd518', '04 28 18', '감각 통합 훈련용 보조기구', '다양한 감각에서 뇌로 들어오는 감각 정보의 조정 및 통합을 촉진하는 기기', null, '3', 'true', '6', '2025-12-28 01:55:37.021521+00', '2026-02-09 03:26:58.608329+00'), ('e20f2d31-471b-4e14-9345-abdaf3f021eb', '06 04 03', '복근 지지대', '복부를 지지하는 장치', null, '3', 'true', '1', '2025-12-28 01:55:02.041561+00', '2026-02-09 03:27:15.521366+00'), ('e2a950b1-96fe-425f-bdae-d8a31695ffc0', '12 25 06', '시트 쿠션 및 밑깔개', '안정된 앉은 자세를 교정하고 유지하기 위해 좌석에 장착하는 쿠션 및 기타 장치 조직 무결성을 위한 시트 쿠션 및 밑깔개, 04 33 03 참조', null, '3', 'true', '2', '2025-12-28 01:55:13.335689+00', '2026-02-09 03:36:39.110787+00'), ('e328e268-8e9d-4642-802b-4670744b6ae5', '28 24 12', '업무 현장용 공기청정기', '업무 현장의 대기오염물질을 제거하는 장치 실내 공기 질 개선을 위한 보조기구, 27 03 06 참조', null, '3', 'true', '4', '2025-12-28 01:55:30.873395+00', '2026-02-09 03:28:05.359464+00'), ('e372de98-b6b4-42c4-97a5-88b874350283', '22 15 06', '계산기', '예를 들어 음성 출력, 대형 버튼, 대형 디스플레이 등이 첨부된 계산기를 포함한다.', null, '3', 'true', '2', '2025-12-28 01:55:15.290053+00', '2026-02-09 03:28:46.630705+00'), ('e3a74605-dc5d-46f2-a8f2-bf09ce68e5ee', '12 07 42', '보행 보조기구용 전동 보조 장치', '보행 보조기구에 부착하여 바퀴를 구동시키거나 높이, 폭, 접힘, 보행 방향을 조절할 수 있는 장치', null, '3', 'true', '12', '2025-12-28 01:55:57.416191+00', '2026-02-09 03:36:39.110787+00'), ('e3cf7673-b6e2-4207-afe0-b6f1d125a456', '22 06 12', '인이어 보청기', '귀 안에 착용하여 소리를 증폭시키는 장치 예를 들어 고막 보청기 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:29.20593+00', '2026-02-09 03:28:46.630705+00'), ('e407406a-d139-4c2c-8cb2-4ce425b87f24', '09 36 09', '손톱 가위 및 손톱깎이', '손톱을 자르거나 짧게 하는 장치', null, '3', 'true', '3', '2025-12-28 01:55:19.826462+00', '2026-02-09 03:30:20.740792+00'), ('e40a57e9-b8c4-43f4-9d0b-6332bd7039cd', '15 09 24', '에그 컵', '에그 컵', null, '3', 'true', '8', '2025-12-28 01:55:48.156359+00', '2026-02-09 03:36:58.313004+00'), ('e44aabca-081e-4823-a0ca-584084625c50', '04 26 27', '사회화 훈련용 보조기구', '예를 들어 인형을 이용한 심리 치료용 보조기구와 소셜 로봇 등을 포함한다. 기억력 보조용 기기, 22 28 12 참조', null, '3', 'true', '9', '2025-12-28 01:55:49.764322+00', '2026-02-09 03:26:58.608329+00'), ('e452da19-1562-4ac0-a3b2-0c1cf462198f', '12 24 48', '피벗 구동 휠 장치', '수동 휠체어의 프레임 앞에 고정/조립할 수 있고 구동력을 전달하며 휠체어 프레임의 각도 방향을 변경하여 수동 휠체어를 조종하는 탈착식 추진 바퀴 장치 수동 휠체어용 추진 장치, 12 24 09 참조', null, '3', 'true', '14', '2025-12-28 01:55:59.792937+00', '2026-02-09 03:36:39.110787+00'), ('e4f0d24d-b7c9-4330-8d38-588ff5e48f02', '22 45 09', '나침반', '동서남북 방향의 정보를 제공하는 안내 장치', null, '3', 'true', '3', '2025-12-28 01:55:23.50389+00', '2026-02-09 03:28:46.630705+00'), ('e54f23ad-3c5c-407e-a5ed-25c1227abf3b', '06 06 30', '어깨-팔꿈치-손목-손 보조기', '어깨, 팔꿈치 및 손목 관절과 손의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '12', '2025-12-28 01:55:56.488383+00', '2026-02-09 03:27:15.521366+00'), ('e55066a7-62fa-498b-ad6e-eab69e7cdad6', '09 06 30', '목욕용 보호 덮개', '피부 또는 붕대의 방수 보호', null, '3', 'true', '10', '2025-12-28 01:55:53.112586+00', '2026-02-09 03:27:15.521366+00'), ('e6a1c81f-d0b8-4195-b754-f58ce9e84967', '04 06 09', '순환 관리를 위한 공기 충전 의류 및 압박 장치', '신체의 환부를 둘러싸기 위한 공기 충전 부착물이 있는 장치. 순환을 돕고 순환 문제로 인한 부종을 방지하기 위해 압박 파형을 생성하는 압박 의류와 압박기로 구성된 장치', null, '3', 'true', '2', '2025-12-28 01:55:09.340936+00', '2026-02-09 03:26:41.971174+00'), ('e6a7e942-f076-419d-a6d0-56291f29955a', '28 15 06', '전동 수공구', '기재나 물질을 다루기 위한 전동 휴대형 장치 예를 들어 드릴링 머신, 압착 공기 파일, 그라인더 등이 있다. 수공예 도구, 기재 및 장비, 30 18 참조', null, '3', 'true', '2', '2025-12-28 01:55:16.975504+00', '2026-02-09 03:28:28.465723+00'), ('e6c79308-2d83-456e-9b37-28c542801665', '18 30 21', '사다리 및 발판사다리', '계단, 18 24 18 참조', null, '3', 'true', '9', '2025-12-28 01:55:51.603229+00', '2026-02-09 03:36:58.313004+00'), ('e7181f62-9402-4e91-987a-5841b6b0e789', '15 09 16', '머그, 유리잔, 컵 및 접시', '해당 용품용 그립 어댑터를 포함한다. 그립 어댑터 및 부착물, 24 18 06 참조', null, '3', 'true', '5', '2025-12-28 01:55:33.990018+00', '2026-02-09 03:36:58.313004+00'), ('e76c9f24-0eb8-40f0-850f-882a305d8d7b', '22 21 12', '대면 통신 소프트웨어', '같은 장소에 있는 사람들 사이의 의사 소통을 위한 소프트웨어 텍스트 및 멀티미디어 처리 소프트웨어, 22 13 39 참조', null, '3', 'true', '3', '2025-12-28 01:55:23.031083+00', '2026-02-09 03:28:46.630705+00'), ('e7d0af2f-6cc7-4248-a4dc-a95768195522', '30 09 06', '양궁용 보조기구', '양궁에 참여할 수 있게 지원하는 보조기구', null, '3', 'true', '2', '2025-12-28 01:55:17.465313+00', '2026-02-09 03:28:05.359464+00'), ('e7d143f8-4a86-4ed4-865c-441d717a0083', '15 12 07', '키친롤용 디스펜서', '키친롤 용지의 고정 및 배출을 용이하게 하는 장치', null, '3', 'true', '3', '2025-12-28 01:55:21.464576+00', '2026-02-09 03:36:58.313004+00'), ('e82ccae7-e4ea-4961-b835-76f87701705a', '06 24 21', '경골반 보철물', '절단 후 또는 선천적 사지 결손으로 인한 반골반의 일부 또는 전체와 함께 하지를 대체하는 장치', null, '3', 'true', '7', '2025-12-28 01:55:42.234221+00', '2026-02-09 03:27:15.521366+00'), ('e853608d-76b2-4fe3-ab03-37d9ce75e4c9', '24 18 18', '포인팅 램프', '시각 매체를 강조하는 데 사용되는 집중 광선을 방출하는 장치 유선 리모컨, 24 13 03 참조', null, '3', 'true', '6', '2025-12-28 01:55:40.7082+00', '2026-02-09 03:28:28.465723+00'), ('e8e6dcb3-9dcd-4ef2-990f-f1c015ddcffb', '06 06 06', '손 보조기', '손의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '2', '2025-12-28 01:55:10.541285+00', '2026-02-09 03:27:15.521366+00'), ('e934f29a-7570-43b2-acb0-8830e3158955', '06 12 12', '무릎-발목-발 보조기', '무릎 및 발목 관절과 발을 감싸는 보조기', null, '3', 'true', '4', '2025-12-28 01:55:25.671578+00', '2026-02-09 03:27:15.521366+00'), ('e98cb071-e23c-4214-b914-ace7543a7175', '28 18 06', '업무 현장 품질 보증 장치', '사전 정의된 품질 요구사항을 충족하기 위해 보조기구를 제조하거나 활동을 수행할 때 계획, 모니터링 및 수정하는 장치 예를 들어 조립 공정 추적 시스템 및 소프트웨어 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:17.075412+00', '2026-02-09 03:28:28.465723+00'), ('e9c0e969-2176-430a-a23c-d1803692d6bc', '09 30 45', '의자나 침구류를 보호하기 위해 신체에 착용하지 않는 언더패드, 세탁 가능', '매트리스 및 매트리스 커버, 18 12 18 참조', null, '3', 'true', '17', '2025-12-28 01:56:01.927621+00', '2026-02-09 03:30:20.740792+00'), ('ea1b7e98-6b5b-4756-addc-fb372cc93b93', '27 03 15', '조명 제어용 보조기구', '조명 조건을 제어하기 위한 장치 조명기구, 18 06 참조 장치 작동 및 제어용 기계식 보조기구, 24 09 참조 업무 현장의 조명 제어용 보조기구, 28 24 06 참조', null, '3', 'true', '5', '2025-12-28 01:55:36.098363+00', '2026-02-09 03:28:28.465723+00'), ('ea620b78-cbd8-4711-87ee-685cc67946c7', '22 33 03', '데스크톱(비휴대용) 컴퓨터', '데스크톱(비휴대용) 컴퓨터', null, '3', 'true', '1', '2025-12-28 01:55:07.300401+00', '2026-02-09 03:28:46.630705+00'), ('ead02326-c63a-45b1-ae30-a55661e09f28', '15 06 09', '식기 건조대', '물이 빠져나갈 수 있도록 씻은 접시를 놓는 틀', null, '3', 'true', '3', '2025-12-28 01:55:21.293047+00', '2026-02-09 03:36:58.313004+00'), ('ead8a2ce-6076-47fc-b2df-b6441e838e22', '15 06 06', '식기 세척용 브러시 및 플라스크 브러시', '식기 세척용 브러시 및 플라스크 브러시', null, '3', 'true', '2', '2025-12-28 01:55:13.77294+00', '2026-02-09 03:36:58.313004+00'), ('eae9b1ca-fda9-4ffb-abb7-21fc5a096c8a', '15 15 27', '다리미판 및 다리미대', '다리미판 및 다리미대', null, '3', 'true', '9', '2025-12-28 01:55:51.452814+00', '2026-02-09 03:36:58.313004+00'), ('eaefa65d-e747-4ad2-a893-3ed19b70aae8', '30 18 15', '창의적인 그림 디자인을 위한 공구, 기재 및 장비', '컴퓨터나 기타 전자적 수단을 사용하지 않고 그림을 그리는 데 사용되는 보조기구 예를 들어 페인팅, 그리기 스케치, 그래픽 아트 등이 있다. 그리기 및 필기용 수동 장치, 22 13 24 참조 칠판, 독서대 및 책받침 쿠션, 22 13 06 참조 그리기 및 페인팅 소프트웨어, 22 13 42 참조', null, '3', 'true', '5', '2025-12-28 01:55:36.614154+00', '2026-02-09 03:28:05.359464+00'), ('eafd999d-e314-4255-8cde-e8c421e9eabf', '22 45 15', '시각 방향 안내 기재', '시각을 통해 방향에 대한 정보를 제공하기 위한 기제', null, '3', 'true', '5', '2025-12-28 01:55:35.862599+00', '2026-02-09 03:28:46.630705+00'), ('eb462628-e21a-456e-b32f-ec6854961c19', '04 48 39', '스탠딩 프레임 및 스탠딩 지지대', '사람이 직립 자세를 유지할 수 있도록 지지해주는 고정 장비', null, '3', 'true', '10', '2025-12-28 01:55:52.392942+00', '2026-02-09 03:26:58.608329+00'), ('eb542f42-3113-4735-abcc-6e6a553f4b53', '22 15 12', '연산의 기초 훈련 및 지원용 보조기구', '사물의 수, 도형, 기초 산술 연산 사이의 개념적 연결 고리의 획득을 돕기 위해 고안된 기기', null, '3', 'true', '4', '2025-12-28 01:55:29.405794+00', '2026-02-09 03:28:46.630705+00'), ('ec658e0c-eae5-473f-b4f9-867180d0a8cc', '12 36 03', '슬링 시트가 있는 앉은 자세로 사람을 이송하기 위한 이동식 호이스트', '앉은 자세, 반 앉은 자세 및 반 누운 자세에서 사람을 들어 올리고 자유롭게 움직여 이송하는 장비. 신체 지지 장치는 슬링으로 구성', null, '3', 'true', '1', '2025-12-28 01:55:05.074926+00', '2026-02-09 03:36:39.110787+00'), ('ec9a5803-b3b2-4f56-ad0a-914a1597c03e', '12 24 39', '계단을 오르내리기 쉽도록 휠체어에 부착된 장치', '휠체어를 안전하게 고정하여 휠체어를 탑승한 상태에서 안전하게 계단을 오르내릴 수 있도록 하는 수동 또는 전기 동력으로 작동되는 카트 및 기타 유형의 차량 전동식 계단 운반 기카, 12 17 03 참조 계단 오르기용 전동 휠체어, 12 23 15 참조 수직 접근성을 위한 보조기구, 18 30 참조', null, '3', 'true', '11', '2025-12-28 01:55:55.886283+00', '2026-02-09 03:36:39.110787+00'), ('ed67f1e9-f600-47c8-bae8-4ca1dc913837', '04 24 12', '혈액 분석 장치, 장비 및 기재', '예를 들어 혈당 모니터 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:17.908198+00', '2026-02-09 03:26:58.608329+00'), ('ee279054-491e-4b2c-9986-832815d37a39', '04 24 15', '심전도 장비(ECG)', '심장의 활동을 모니터링하고 기록하는 장비 청진기, 04 24 21 참조', null, '3', 'true', '4', '2025-12-28 01:55:25.015909+00', '2026-02-09 03:26:58.608329+00'), ('ee281966-3f12-41ee-a29a-04433cad0595', '04 03 06', '흡입 장치', '증기, 기체, 액체 스프레이 또는 미세 먼지 형태의 약물을 흡입하거나 투여하는 데 도움을 주는 장치 예를 들어 제트 디스펜서, 자동 흡입기 디스펜서, 압력 호흡기, 초음파 분무기, 필터, 용량 에어로졸이 있는 분무기 등이 있다.', null, '3', 'true', '2', '2025-12-28 01:55:09.240771+00', '2026-02-09 03:26:41.971174+00'), ('ef090055-f1fb-4981-9935-3c6b256ed6d7', '15 15 30', '바퀴 달린 세탁물 바구니', '바퀴 달린 세탁물 바구니', null, '3', 'true', '10', '2025-12-28 01:55:53.863657+00', '2026-02-09 03:36:58.313004+00'), ('ef0b3d8e-731b-46ad-98b3-bcc523203baf', '09 36 03', '네일 브러시', '손톱 세정 및 광택 장치 그립 어댑터 및 부착물, 24 18 06 참조', null, '3', 'true', '1', '2025-12-28 01:55:03.516501+00', '2026-02-09 03:30:20.740792+00'), ('ef45fe50-a99c-4683-a0c2-b88801dc442d', '06 18 48', '지지 구성요소', '신체에 대해 보철물을 유지하는 데 사용되는 지지 구성요소 예를 들어 주요 지지 부위, 골반, 몸통, 어깨(들), 상완, 상완골과, 요골/척골 경상돌기용 지지 구성요소 등이 있다.', null, '3', 'true', '19', '2025-12-28 01:56:02.525067+00', '2026-02-09 03:27:15.521366+00'), ('ef52f950-a207-47a3-9815-e93bffce19ec', '04 33 06', '누워 있을 때 조직 무결성을 위한 보조기구', '누워 있을 때 신체 취약부의 하중을 재분배하여 욕창을 예방하기 위한 기구 매트리스 및 매트리스 커버, 18 12 18 참조', null, '3', 'true', '3', '2025-12-28 01:55:18.183652+00', '2026-02-09 03:26:58.608329+00'), ('f0062157-b6fd-42c0-b9fa-3b2392f89b4d', '06 24 15', '경대퇴 보철물', '절단 후 또는 선천적 사지 결손으로 인한 고관절과 무릎 관절 사이의 하지 일부를 대체하는 장치', null, '3', 'true', '5', '2025-12-28 01:55:31.956268+00', '2026-02-09 03:27:15.521366+00'), ('f0793fbc-175a-4130-84e0-736c4a333567', '15 12 24', '바닥 광택기', '바닥 광택기', null, '3', 'true', '7', '2025-12-28 01:55:44.089247+00', '2026-02-09 03:36:58.313004+00'), ('f0b6792a-4cab-4ed9-a0e9-874d1fa76fb7', '24 18 27', '수동 활동을 허용하는 팔 지지대', '사무 작업 또는 식사 등 수동 활동 중 전완을 지지하는 장치 휠체어용 팔 지지대, 12 25 09 참조', null, '3', 'true', '7', '2025-12-28 01:55:45.366583+00', '2026-02-09 03:28:28.465723+00'), ('f0cf98b4-a720-4dfb-8826-55ba0ce5c1ba', '04 26 12', '개념 개발 훈련용 보조기구', '색상, 크기, 모양 등의 개념 이해 훈련용 보조기구', null, '3', 'true', '4', '2025-12-28 01:55:25.081118+00', '2026-02-09 03:26:58.608329+00'), ('f0dad095-e4ca-4fbc-9993-29d8fad84ce2', '09 33 21', '욕조', '목욕통이라고도 함. 예를 들어 휴대용 및 접이식 욕조 등이 있다.', null, '3', 'true', '10', '2025-12-28 01:55:53.475053+00', '2026-02-09 03:30:20.740792+00'), ('f0edc698-c14d-4f53-bbec-2fc8a5c0357f', '09 24 12', '소변 슈트', '선 자세로 사용할 수 있는 신체에서 변기로 직접 소변을 배출하는 장치', null, '3', 'true', '4', '2025-12-28 01:55:26.539262+00', '2026-02-09 03:27:48.703289+00'), ('f135d908-bc58-4be5-9f52-8cf1b6704d2b', '12 06 09', '보행 의자', '전완 지지대가 있거나 없으며 보행 시 몸을 지지하는 바퀴 좌석 또는 슬링이 있는 장치 수동으로 구동되는 독립형 이동 장치, 12 27 24 참조', null, '3', 'true', '4', '2025-12-28 01:55:26.95956+00', '2026-02-09 03:36:39.110787+00'), ('f1856918-3d2f-4e51-8edd-61601c82670e', '04 28 15', '지각 협응 훈련용 보조기구', '외부 자극, 특히 공간과 시간의 개념, 공간 개념, 눈과 손의 협응과 관련된 자극을 정확하게 처리하고 조정하는 능력을 향상시키기 위한 훈련용 장비', null, '3', 'true', '5', '2025-12-28 01:55:31.453368+00', '2026-02-09 03:26:58.608329+00'), ('f1942cbd-57da-4e1f-be73-f38cfae7aa93', '30 09 30', '사격용 보조기구', '사냥이나 사격 중에 사람이 총을 쏠 수 있도록 지원하는 보조기구', null, '3', 'true', '9', '2025-12-28 01:55:52.159594+00', '2026-02-09 03:28:05.359464+00'), ('f21b6038-1e44-4d53-a776-923188001542', '22 06 15', '귀 뒤 보청기', '귀 뒤에 착용하여 소리를 증폭시키는 장치 예를 들어 헤드밴드/보청기 등이 있다.', null, '3', 'true', '5', '2025-12-28 01:55:34.741848+00', '2026-02-09 03:28:46.630705+00'), ('f24dad3a-773d-4d90-a98f-e51b9d447b0e', '18 10 13', '좌식 가구용 목 지지대 및 머리 지지대', '좌식 가구에 편안함을 제공하기 위해 등받이 상단에 배치된 머리 지지대와 비장착형 쿠션', null, '3', 'true', '2', '2025-12-28 01:55:14.328697+00', '2026-02-09 03:36:58.313004+00'), ('f337b3cf-868f-4007-8e1e-c893e7908f01', '06 12 33', '하지 보조기의 구조적 구성요소', '구조적 구성요소는 관절 및 인터페이스 구성요소를 연결하고 보조기의 정렬을 유지한다. 예를 들어 업라이트, 쉘 등이 있다.', null, '3', 'true', '16', '2025-12-28 01:56:00.936926+00', '2026-02-09 03:27:15.521366+00'), ('f33f8599-a156-43f3-bf93-9352e2bd322c', '06 12 19', '(흉부-)요추-천골-둔부-무릎-발목-발 보조기', '척추의 흉부 부분을 포함하거나 포함하지 않은 몸통의 요추 부위, 둔부, 무릎 및 발목 관절과 발을 감싸는 보조기', null, '3', 'true', '10', '2025-12-28 01:55:52.627967+00', '2026-02-09 03:27:15.521366+00'), ('f3fecf3a-3c65-43fc-a048-6c6be8037c61', '15 12 09', '진공청소기', '예를 들어 진공 청소 로봇 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:28.128868+00', '2026-02-09 03:36:58.313004+00'), ('f49ab59b-2f08-445b-848d-1201e7740798', '09 03 05', '외투', '갑작스러운 추위, 온도, 바람 및 모든 유형의 강수량으로부터 사람을 보호하기 위해 일반적으로 다른 옷 위에 입는 야외용 의류 예를 들어 야외용 코트, 판초 및 랩 등이 있다.', null, '3', 'true', '1', '2025-12-28 01:55:02.472989+00', '2026-02-09 03:27:15.521366+00'), ('f50e3244-4f42-4f17-9a3a-54dc3b2389af', '06 30 06', '헤어피스 및 부분 가발', '사람의 머리카락의 일부를 대체하는 장치', null, '3', 'true', '2', '2025-12-28 01:55:10.842935+00', '2026-02-09 03:27:15.521366+00'), ('f52cdee9-abc2-433b-86cd-274e7aaa12e9', '06 12 36', '하지 보조기의 마감(미용) 구성요소', '보조기에 모양, 색상 및 질감을 부여하는 미용 구성요소 예를 들어 충전재, 커버, 슬리브 등이 있다.', null, '3', 'true', '17', '2025-12-28 01:56:01.596325+00', '2026-02-09 03:27:15.521366+00'), ('f561f8c9-c9d2-48a2-94da-4e7c482e240e', '18 12 21', '담요 지지대', '시트 및 담요 무게가 신체에 인가되지 않도록 침대에 장착된 프레임', null, '3', 'true', '7', '2025-12-28 01:55:44.337903+00', '2026-02-09 03:36:58.313004+00'), ('f5b62bc7-606b-404d-a977-f9cc40d0fddf', '04 27 21', '세포 성장 촉진용 보조기구', '예를 들어 뼈 성장 및 조직 성장의 자기장 자극 및 전기 자극 등이 있다.', null, '3', 'true', '3', '2025-12-28 01:55:18.049157+00', '2026-02-09 03:26:58.608329+00'), ('f652367d-b292-4fc3-aab0-71f07ef531a2', '22 21 03', '문자 및 기호 세트 및 보드', '의사소통을 지원하는 문자, 기호 및 단어가 포함된 팩/책자 또는 보드', null, '3', 'true', '1', '2025-12-28 01:55:06.991089+00', '2026-02-09 03:28:46.630705+00'), ('f69e633c-3c53-4104-a77e-a28bc7536b7c', '04 48 07', '보행 패턴 운동용 보조기구', '보행 패턴 개선 훈련을 하는 사람을 지지하기 위한 고정 장비 예를 들어 평행봉, 체중 지지 트레드밀 시스템 등이 있다. 개인 이동 훈련용 보조기구, 04 48 36 참조 한 팔로 조작하는 보행 보조기구, 12 03 참조 양팔로 조작하는 보행 보조기구, 12 06 참조', null, '3', 'true', '2', '2025-12-28 01:55:10.323513+00', '2026-02-09 03:26:58.608329+00'), ('f71406c3-3bcb-49ce-af39-cb1fff8cafb4', '06 03 27', '척추 보조기용 관절 구성요소', '척추의 해부학적 관절의 움직임을 허용하거나 제어하는 보조기의 관절 구성요소 예를 들어 척추 보조기용 관절 등이 있다.', null, '3', 'true', '10', '2025-12-28 01:55:52.463402+00', '2026-02-09 03:27:15.521366+00'), ('f732885d-8fe5-42bd-81d5-773275e66479', '18 30 18', '고정식 경사로', '두 레벨 사이의 제한된 간격을 연결하는 고정된 경사면', null, '3', 'true', '8', '2025-12-28 01:55:48.576395+00', '2026-02-09 03:36:58.313004+00'), ('f7347b42-6b81-4751-9770-c505e4766384', '06 12 03', '발 보조기', '발의 전체 또는 일부를 감싸는 보조기 예를 들어 교정용 신발, 안창, 깔창, 패드, 아치 지지대, 뒤꿈치 쿠션, 힐 컵, 교정용 인레이 등이 있다. 신발 및 부츠, 09 03 42 참조', null, '3', 'true', '1', '2025-12-28 01:55:02.177222+00', '2026-02-09 03:27:15.521366+00'), ('f7b76354-9324-48f2-be9b-7c53c1f1d7d7', '09 12 27', '화장지 집게', '화장지 고정 및 밑 닦기를 용이하게 하는 장치', null, '3', 'true', '11', '2025-12-28 01:55:55.312471+00', '2026-02-09 03:27:15.521366+00'), ('f8790742-7c2f-4e0d-b17f-74077e2ef81b', '30 18 09', '목공예용 공구, 기재 및 장비', '나무로 공예품을 만드는 데 사용되는 보조기구', null, '3', 'true', '3', '2025-12-28 01:55:24.780761+00', '2026-02-09 03:28:05.359464+00'), ('f88577b3-59b5-4ae9-9df8-27dfdafdadbf', '09 12 33', '침대용 변기', '예를 들어 침대에서 배뇨 및 배변을 할 수 있는 신체 배설물 수거 용기', null, '3', 'true', '13', '2025-12-28 01:55:58.491707+00', '2026-02-09 03:27:15.521366+00'), ('f8bc2a0a-1246-425f-a1b6-7d5de8eed6b1', '18 09 21', '특수 좌식 가구', '사람의 특정 착석 요구 사항을 충족하는 의자 예를 들어 어린이용 높은 의자, 시팅 백, 바닥 시트 등이 있다. 자동차용 시트와 쿠션, 및 차량 시트 관련 액세서리 및 개조물, 12 12 12 참조', null, '3', 'true', '6', '2025-12-28 01:55:39.58068+00', '2026-02-09 03:36:58.313004+00'), ('f98c04bb-6478-40da-8bec-df2e74379914', '24 13 03', '유선 리모컨', '전기기기 작동을 위한 유선 장치', null, '3', 'true', '1', '2025-12-28 01:55:07.706588+00', '2026-02-09 03:28:28.465723+00'), ('f9b789ad-0304-4c8f-9742-0278fd3ff258', '22 28 12', '기억 지원 보조기구', '과거의 기억을 회상하거나(예: 말하는 사진 앨범) 단일 또는 다중 작업(예: 자기 모니터링의 일환으로서 복용, 동작 실행 또는 측정)을 홍보하거나 상기시키기 위한 전자 장치 및 소프트웨어', null, '3', 'true', '4', '2025-12-28 01:55:29.760911+00', '2026-02-09 03:28:46.630705+00'), ('f9cbc468-b59a-465c-aa5f-f337923ece0f', '22 45 06', '음향 항법용 보조기구', '시각 장애가 있는 사람의 방향을 안내하기 위해 소리나 메시지를 생성하는 안내 장치 예를 들어 사운드 비콘 등을 포함한다.', null, '3', 'true', '2', '2025-12-28 01:55:15.863475+00', '2026-02-09 03:28:46.630705+00'), ('fafc20b8-acde-49cd-b8b7-537225eb42e0', '04 48 30', '턱 운동기구', '예를 들어 턱 견인 장치 등이 있다.', null, '3', 'true', '7', '2025-12-28 01:55:41.806332+00', '2026-02-09 03:26:58.608329+00'), ('fb11253b-de01-46b2-96ba-da3ea37e082a', '15 12 22', '바닥 물걸레 청소 장비', '예를 들어 바닥 걸레, 양동이, 스탠드, 바닥 물걸레 청소 기구 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:39.41825+00', '2026-02-09 03:36:58.313004+00'), ('fb1cb8d6-9e41-4835-bd81-4566b9e5c57a', '09 27 09', '신체 미착용 소변기 및 소변 병', '침대용 변기, 09 12 33 참조 여성용 신체 착용 소변기, 09 24 15 참조 남성용 신체 착용 소변기, 09 24 21 참조', null, '3', 'true', '3', '2025-12-28 01:55:19.5311+00', '2026-02-09 03:30:20.740792+00'), ('fb239b43-d18d-4078-8f58-d5edcb584259', '04 26 06', '연속성 훈련용 보조기구', '단어, 행동, 숫자 등을 올바른 순서로 배열하도록 훈련시키는 기기', null, '3', 'true', '2', '2025-12-28 01:55:09.923468+00', '2026-02-09 03:26:58.608329+00'), ('fb2486fe-1443-423e-9851-660667cd1879', '06 04 12', '복부 보조기의 마감 구성요소', '미용 구성요소는 보조기에 모양, 색상 및 질감을 부여하는 수단이다. 예를 들어 충전재, 커버, 슬리브 등이 있다.', null, '3', 'true', '4', '2025-12-28 01:55:25.507141+00', '2026-02-09 03:27:15.521366+00'), ('fb39a5c9-d6ec-4a9e-8c70-e5a75e86637a', '15 09 27', '영양 장치', '음식을 접시에서 입으로 가져와 먹을 수 있도록 하는 전동 또는 수동 장치 예를 들어 영양 공급 로봇 등이 있다.', null, '3', 'true', '9', '2025-12-28 01:55:51.234526+00', '2026-02-09 03:36:58.313004+00'), ('fb777e63-f5b1-4070-b37b-90e66aed70d4', '09 18 17', '장루 성형 치료용 추가 백', '장루 시스템의 백에 연결하여 신체 노폐물을 수거할 수 있는 추가 용량을 갖춘 추가 백', null, '3', 'true', '4', '2025-12-28 01:55:26.390497+00', '2026-02-09 03:27:15.521366+00'), ('fba98060-7a91-484f-afe5-336958d8399e', '04 24 03', '소변 분석 장비', '소변 분석 장비', null, '3', 'true', '1', '2025-12-28 01:55:01.318889+00', '2026-02-09 03:26:58.608329+00'), ('fbdb4c5b-1c10-4c03-a877-aa7fe9b752ca', '22 21 21', '청각 장애인을 위한 지문자(예: 촉각 의사소통) 교육 및 학습 보조기구', '수화 훈련용 보조기구 청각 장애인용 수화(예: 시각 언어) 훈련 및 학습용 기기', null, '3', 'true', '5', '2025-12-28 01:55:35.132203+00', '2026-02-09 03:28:46.630705+00'), ('fc0f62c1-01ec-463e-99ff-d5e17e8afeb6', '18 12 28', '침대에 고정하는 자체 기립용 레일', '사용자가 침대에서 자세를 변경하거나 독립적으로 앉을 수 있는 탈착식 레일 비장착식 자체 기립용 레일, 12 31 09 참조', null, '3', 'true', '10', '2025-12-28 01:55:53.943217+00', '2026-02-09 03:36:58.313004+00'), ('fc194411-cc97-474d-99f6-f00107624b10', '18 10 21', '일어서거나 앉는 것을 도움이 되도록 좌석에 추가된 쿠션 또는 시스템', '앉은 자세에서 서 있는 자세로 이동할 수 있도록 사람을 들어 올릴 수 있는 장치가 있는 좌석 쿠션. 이 장치는 또한 앉은 채로 사람과 하강을 지원할 수 있음.', null, '3', 'true', '4', '2025-12-28 01:55:28.518779+00', '2026-02-09 03:36:58.313004+00'), ('fc3e5f83-a79d-4a5e-b421-c1a3a4285f9d', '22 13 18', 'OCR 장비 및 OCR 소프트웨어', '인쇄된 텍스트를 인식하고 디지털 형식으로 변환하는 데 사용되는 스캐너 및 소프트웨어 휴대용 스캐너 등을 포함한다.', null, '3', 'true', '6', '2025-12-28 01:55:40.092573+00', '2026-02-09 03:28:46.630705+00'), ('fc61a711-1927-4b26-aeb7-99603877a189', '06 12 06', '발목-발 보조기', '발목 관절 및 발의 전체 또는 일부를 감싸는 보조기', null, '3', 'true', '2', '2025-12-28 01:55:10.614722+00', '2026-02-09 03:27:15.521366+00'), ('fe40bb32-826f-40ad-9110-10e437c0be63', '22 18 09', '라디오 수신기', '예를 들어 오디오 디스플레이가 있는 라디오 수신 기 등을 포함한다.', null, '3', 'true', '3', '2025-12-28 01:55:22.960911+00', '2026-02-09 03:28:46.630705+00'), ('fe50a632-b65d-4d7a-bb97-e06682264278', '06 06 25', '상완 보조기', '팔꿈치 또는 손목 관절을 포함하거나 포함하지 않은 상완을 감싸는 보조기(예: 골절 치료)', null, '3', 'true', '11', '2025-12-28 01:55:54.759063+00', '2026-02-09 03:27:15.521366+00'), ('fe540629-d550-4272-a165-2a7b76316b54', '06 06 24', '어깨-팔꿈치 보조기', '어깨 및 팔꿈치 관절을 감싸는 보조기', null, '3', 'true', '10', '2025-12-28 01:55:52.535052+00', '2026-02-09 03:27:15.521366+00'), ('fe8b92d7-57bb-48f9-b06e-50776f78c78c', '27 06 15', '전기적 특성 측정용 보조기구 및 도구', '전기적 특성 측정용 보조기구 및 도구', null, '3', 'true', '5', '2025-12-28 01:55:36.181918+00', '2026-02-09 03:28:28.465723+00'), ('fe9bd4f8-4532-43ab-8e62-81cbd108d1d6', '22 28 03', '시계 및 타임피스', '시간을 측정하고 표시하고 말하기 위한 기기 예를 들어 휴대용 및 비휴대용 장치, 타이머 및 알림 기능이 있거나 없는 장치 등을 포함한다.', null, '3', 'true', '1', '2025-12-28 01:55:07.123046+00', '2026-02-09 03:28:46.630705+00'), ('fed2680b-9007-4e82-9d4a-5acbec24eb34', '06 18 24', '의수 및 의지', '정상 팔다리의 일부 동적 및 감각적 특성을 대체하는 상지 보철물의 기능적 구성요소. 외수는 정상 손의 일부 기능을 대체하도록 설계되었으며 정적, 수동적, 능동적 또는 수동적/능동적 조합이 될 수 있다. 의수는 외부 동력 또는 신체 동력으로 구동할 수 있다.', null, '3', 'true', '8', '2025-12-28 01:55:46.666571+00', '2026-02-09 03:27:15.521366+00'), ('fefeb98d-79ab-4749-a547-201ed484b42e', '18 36 15', '선반, 찬장 및 캐비닛용 피팅', '선반, 찬장 및 캐비닛용 피팅', null, '3', 'true', '5', '2025-12-28 01:55:34.604056+00', '2026-02-09 03:36:58.313004+00'), ('ff2bcb94-cf72-4f73-8ce6-0314ce64ec6f', '18 30 11', '플랫폼이 있는 계단 승강기', '플랫폼이 하나 이상의 레일에 부착되어 있고 계단의 모양과 각도를 따라 이동하는 리프팅 장치 예를 들어 휠체어용 계단 승강기 등이 있다.', null, '3', 'true', '6', '2025-12-28 01:55:39.783155+00', '2026-02-09 03:36:58.313004+00'), ('ff758221-c656-42d5-9166-f0d32391e4b7', '15 15 33', '세탁기', '세탁기', null, '3', 'true', '11', '2025-12-28 01:55:55.970142+00', '2026-02-09 03:36:58.313004+00');